window.SAILIB_QUIZ_BANK =[{"answer": 3, "explanation": "He named houses, jewellery, furniture and scooters (04:58 in the satsang).", "id": "en-bk-001", "kind": "single_select", "language": "en", "options": ["Houses", "Jewellery", "Furniture", "A second car"], "question": "In Sri Babuji's 'Desire vs Need' satsang he audits a lifetime of 'survival savings' — money earned for survival that became four things. Which of these did he NOT name in the audit?", "source_label": "Desire vs Need satsang (YouTube), 04:58", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA&t=298s"}, {"answer": false, "explanation": "He corrects this directly: udi is Baba's padadhuli — the dust of His feet — 'there is no vairagya in it, no Vedanta.'", "id": "en-bk-002", "kind": "true_false", "language": "en", "question": "Sri Babuji teaches that udi is a symbol of vairagya (renunciation) and Vedanta.", "source_label": "Desire vs Need satsang (YouTube)", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA"}, {"answer": [0, 1, 2], "explanation": "The three tests: (1) THE MEASURE — one metre makes a shirt, one ticket rides the bus; whatever exceeds the requirement's measure is desire. (2) THE SAVINGS AUDIT — 'did you do all this for mere survival?' (3) THE PRAISE TEST — would you still want it if no one praised you for it?", "id": "en-bk-003", "kind": "multi_select", "language": "en", "options": ["The measure — whatever exceeds the requirement's measure is desire", "The savings audit — 'did you do all this for mere survival?'", "The praise test — would you still want it if no one praised you?", "The horoscope test — what the stars say about it"], "question": "Sri Babuji gives three tests to sort need from desire. Which of these are they?", "source_label": "Desire vs Need satsang (YouTube)", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA"}, {"answer": "desireless", "explanation": "From the satsang: 'the one prayer worth praying: make me desireless' (40:13).", "id": "en-bk-004", "kind": "quote_completion", "language": "en", "question": "Complete the one prayer Sri Babuji says is worth praying: 'Make me ______.'", "source_label": "Desire vs Need satsang (YouTube), 40:13", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA&t=2413s"}, {"answer": 1, "explanation": "Wanting nothing IS mukti; what is left to give?", "id": "en-bk-005", "kind": "single_select", "language": "en", "options": ["He never laughed — she misheard", "Wanting nothing IS mukti; what is left to give?", "She should have wanted enlightenment instead", "Laughter was simply his teaching method"], "question": "A woman told Ramana Maharshi she had no desires and wanted only mukti. He laughed — why?", "source_label": "Desire vs Need satsang (YouTube)", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA"}, {"answer": "One ticket gets you there — would you buy two? Whatever exceeds the requirement's measure is desire. (In the satsang's Telugu line: the moment you see coffee, desire arises — from the samskaras already inside you.)", "explanation": "The bus-ticket rule from the Desire vs Need satsang (01:11).", "id": "en-bk-006", "kind": "flashcard", "language": "en", "question": "Sri Babuji's one-line rule — with the bus ticket", "source_label": "Desire vs Need satsang (YouTube)", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA"}, {"answer": {"'Who am I?' — wielded as a brahmastra": "Ramana Maharshi", "Whoever has seen me has seen the Father.": "Jesus (answering Philip)", "Why do you seek for God? Your God is in your pocket.": "Sri Babuji (on the Bombay merchant)", "You are seeing me now — that itself is sakshatkara; I myself am God.": "Baba (to Das Ganu)"}, "explanation": "Das Ganu's demand for sakshatkara got the same answer Philip got from Jesus; the merchant's punch line is Sri Babuji's own.", "id": "en-bk-007", "kind": "matching", "language": "en", "pairs": [["You are seeing me now — that itself is sakshatkara; I myself am God.", "Baba (to Das Ganu)"], ["Why do you seek for God? Your God is in your pocket.", "Sri Babuji (on the Bombay merchant)"], ["Whoever has seen me has seen the Father.", "Jesus (answering Philip)"], ["'Who am I?' — wielded as a brahmastra", "Ramana Maharshi"]], "question": "Match each line to who said it (as Sri Babuji teaches them):", "source_label": "Satsang teachings — Whose Words?", "source_link": "https://muse.ai/s/sri-babuji-digests-ox06xhhxrxkdxji6"}, {"answer": 2, "explanation": "Not $100 or $1000 — our peace, our joy, and our time.", "id": "en-bk-008", "kind": "single_select", "language": "en", "options": ["$100 or $1000", "A silk cloth", "Our peace, our joy, and our time", "Gold ornaments"], "question": "What does Sri Babuji say is the TRUE dakshina we give Baba?", "source_label": "Desire vs Need satsang (YouTube)", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA"}, {"answer": false, "explanation": "Marking pages ('today 12 pages') is not parayana; true parayana is tattva-enquiry: take ONE leela and ask it 100 questions with real jijnasa, until 'we disappear'.", "id": "en-bk-009", "kind": "true_false", "language": "en", "question": "True parayana, as Sri Babuji teaches, means finishing a fixed number of Satcharitra pages every day.", "source_label": "Satsang teachings", "source_link": "https://muse.ai/s/sri-babuji-digests-ox06xhhxrxkdxji6"}, {"answer": "He sought Brahma-jnana but could not part with Rs. 5 dakshina. Sri Babuji's punch line: 'Why do you seek for God? Your God is in your pocket.'", "explanation": "From the Desire vs Need satsang's Bombay merchant story.", "id": "en-bk-010", "kind": "flashcard", "language": "en", "question": "The Bombay merchant", "source_label": "Desire vs Need satsang (YouTube)", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA"}, {"answer": 1, "explanation": "'Who am I?' — his brahmastra.", "id": "en-bk-011", "kind": "single_select", "language": "en", "options": ["Silence", "'Who am I?'", "Fasting", "Pilgrimage to Arunachala"], "question": "What was Ramana Maharshi's 'brahmastra' — the weapon he used to silence pestering questioners?", "source_label": "Desire vs Need satsang (YouTube)", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA"}, {"answer": {"Magnet & iron": "Contact with the Sadguru reorders our clashing desires — nothing added, nothing lost", "The train engine": "Couple every attachment to Baba like compartments to an engine; only the engine matters", "The umbrella in the rain": "The Sadguru doesn't stop prarabdha's rain, but under his shelter it cannot touch you", "The upside-down vessel": "One tilt of the ego — namaskar, bending the ego — lets grace flood in"}, "explanation": "These are Sri Babuji's classic analogies from the satsangs.", "id": "en-bk-012", "kind": "matching", "language": "en", "pairs": [["Magnet & iron", "Contact with the Sadguru reorders our clashing desires — nothing added, nothing lost"], ["The upside-down vessel", "One tilt of the ego — namaskar, bending the ego — lets grace flood in"], ["The umbrella in the rain", "The Sadguru doesn't stop prarabdha's rain, but under his shelter it cannot touch you"], ["The train engine", "Couple every attachment to Baba like compartments to an engine; only the engine matters"]], "question": "Match each of Sri Babuji's analogies to the teaching it illustrates:", "source_label": "Satsang teachings — analogies", "source_link": "https://muse.ai/s/sri-babuji-digests-ox06xhhxrxkdxji6"}, {"answer": 1, "explanation": "He was scolded for days: exact obedience to the teacher's word, not creative substitution (46:41).", "id": "en-bk-013", "kind": "single_select", "language": "en", "options": ["He was praised for his initiative", "He was scolded for days — exact obedience to the teacher's word, not creative substitution", "Nothing was said about it", "He was asked to leave the satsang"], "question": "In the satsang story, the lights went out and a disciple was told to light the corner candle — but he lit a different one, thinking he knew better. What happened?", "source_label": "Desire vs Need satsang (YouTube), 46:41", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA&t=2801s"}, {"answer": false, "explanation": "Baba never did Vedic fire ritual; the dhuni is kept lit 'to burn our sins' — the dhuni is 'the factory that produces His feet-dust' (udi).", "id": "en-bk-014", "kind": "true_false", "language": "en", "question": "Sri Babuji says Baba kept the dhuni lit because He performed the Vedic fire ritual (agnihotra).", "source_label": "Desire vs Need satsang (YouTube)", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA"}, {"answer": 2, "explanation": "Satyam (truth): 'take them all; satyam alone I will never give' (17:21).", "id": "en-bk-015", "kind": "single_select", "language": "en", "options": ["His body", "His wealth", "Satyam (truth)", "His devotion"], "question": "Ramakrishna offered Goddess Kali his happiness, sorrow, wisdom, ignorance and knowledge — but refused to give one thing. What?", "source_label": "Desire vs Need satsang (YouTube), 17:03", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA&t=1023s"}, {"answer": "'Guard the small things carefully; big things take care of themselves.' (36:02 in the Desire vs Need satsang.)", "explanation": "From the Desire vs Need satsang (36:02).", "id": "en-bk-016", "kind": "flashcard", "language": "en", "question": "Sri Babuji on guarding small things", "source_label": "Desire vs Need satsang (YouTube), 36:02", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA&t=2162s"}, {"answer": 1, "explanation": "Small, honest, obedient methods beat grand sadhana apparatus.", "id": "en-bk-017", "kind": "single_select", "language": "en", "options": ["Modern tools are useless", "Small, honest, obedient methods beat grand sadhana apparatus", "Mechanics are the true gurus", "You should never call experts"], "question": "In the honest-mechanic story, experts with instruments failed while a simple hand-test fixed it (50:08). What does Sri Babuji say it illustrates?", "source_label": "Desire vs Need satsang (YouTube), 50:08", "source_link": "https://www.youtube.com/watch?v=ddi_2z6OekA&t=3008s"}, {"answer": "I myself am God.", "explanation": "Baba's answer to Das Ganu's demand for sakshatkara as the fruit of his Bhagavata saptaha.", "id": "en-bk-018", "kind": "quote_completion", "language": "en", "question": "Complete Baba's reply to Das Ganu, as Sri Babuji teaches it: 'You are seeing me now — that itself is sakshatkara; _____.'", "source_label": "What true sakshatkara is — Telugu discourse (quote in English summary)", "source_link": "https://www.youtube.com/watch?v=0FcSI2XuwmA&t=180s"}, {"answer": 1, "explanation": "His samadhi is in Saipatham, Shirdi — a place of prayer and meditation.", "id": "en-bk-019", "kind": "single_select", "language": "en", "options": ["Tiruvannamalai", "Saipatham, Shirdi", "The Samadhi Mandir, Shirdi", "Bodhan, Telangana"], "question": "Sri Babuji took mahasamadhi in November 2010. Where is his samadhi (tomb)?", "source_label": "Bound to Love, p. 12", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=34"}, {"answer": "pretexts!", "explanation": "Sri Babuji explains: 'Sai Baba never asks us to give up our desires, or to destroy our desires. Instead he exerts his influence and creates circumstances in such a way that the desires come to the surface.'", "id": "en-bk-020", "kind": "quote_completion", "language": "en", "options": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf", "question": "Complete Baba's words as quoted by Sri Babuji: 'My devotees come with different kinds of desires – maybe for health, for money, for a job, for a promotion, for children, for many things – and I draw them all with these ____.'", "source_label": "From the Desire vs Need satsang (36:02).", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf"}, {"answer": 0, "explanation": "It was Sri Babuji's aim to bring us closer to what he called Sai Baba — the delicious dish he himself was experiencing in every moment.", "id": "en-bk-021", "kind": "single_select", "language": "en", "options": ["Sai Baba", "The Satcharitra", "Self-realization", "The Sadguru's feet"], "question": "Sri Babuji said: 'What I do is give medicines for your appetite – appetizers! Or sometimes, even a purgative or laxative when it is needed! And then I show you: 'Here is the delicious dish: _____.''", "source_label": "Bound to Love, p. 27", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=49"}, {"answer": false, "explanation": "He was 'absolutely adamant in denying' it: 'I am just a page in Baba's book,' and 'Baba is so great, he is the doer of everything.'", "id": "en-bk-022", "kind": "true_false", "language": "en", "question": "Sri Babuji claimed to be an incarnation of Sai Baba.", "source_label": "Bound to Love, p. 36", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=58"}, {"answer": "page", "explanation": "He always declared himself to be a simple devotee of Baba.", "id": "en-bk-023", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's own description of himself: 'I am just a _____ in Baba's book.'", "source_label": "Bound to Love, p. 36", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=58"}, {"answer": 1, "explanation": "'How was it that the bus could go without nuts on one of its wheels and hadn't fallen into the ravine?'", "id": "en-bk-024", "kind": "single_select", "language": "en", "options": ["It had no brakes at all", "One wheel had no nuts, yet the bus had not fallen into the gorge", "The driver had fallen asleep", "It ran 50 km on a flat tyre"], "question": "On the 1998 North India journey with Sri Babuji, devotees driving to Kausani on mountain roads above deep gorges discovered something shocking about their minibus. What?", "source_label": "Bound to Love, p. 41", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=63"}, {"answer": 0, "explanation": "After Sri Babuji called them to his room, a thick blanket of pristine snow fell. The hotel staff said it hadn't snowed this much for three years.", "id": "en-bk-025", "kind": "single_select", "language": "en", "options": ["Thick snow fell that afternoon — the hotel staff said it hadn't snowed this much for three years", "They drove to higher ground to find snow", "They returned disappointed", "It snowed only on their last day"], "question": "In Simla, the devotees wanted snow, but there was none when they arrived in January. What happened?", "source_label": "Bound to Love, p. 42", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=64"}, {"answer": 1, "explanation": "Sri Babuji gave her medicines with precise instructions; a week later her letter, translated with growing amazement, reported her stomach ache had vanished.", "id": "en-bk-026", "kind": "single_select", "language": "en", "options": ["She needed surgery anyway", "Her stomach ache vanished — her letter a week later described her recovery", "He declined to treat her", "She stayed in Shirdi for a month"], "question": "The Sakori Mataji, head of the Sakori Ashram, came to meet Sri Babuji in Shirdi in August 1992 about her stomach ailment. What was the outcome?", "source_label": "Bound to Love, p. 43", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=65"}, {"answer": "Sri Babuji picked up a guava, did namaskar to Baba and gave the fruit to a woman, saying: 'Only you should eat this fruit.' (Bound to Love, p. 38.)", "explanation": "From a devotee's experience recorded in Bound to Love.", "id": "en-bk-027", "kind": "flashcard", "language": "en", "options": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf", "question": "The guava", "source_label": "From a devotee's experience recorded in Bound to Love.", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf"}, {"answer": false, "explanation": "'Sai Baba never asks us to give up our desires, or to destroy our desires. Instead he exerts his influence and creates circumstances in such a way that the desires come to the surface.'", "id": "en-bk-028", "kind": "true_false", "language": "en", "question": "Sri Babuji teaches that Baba asks us to give up our desires before He draws us to Himself.", "source_label": "Bound to Love, p. 24", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=46"}, {"answer": 0, "explanation": "His constant refrain: it is Baba who gave the experience — 'It is enough if they know that it is Baba who gave the experience.'", "id": "en-bk-029", "kind": "single_select", "language": "en", "options": ["By pointing to Baba — attributing the experience to Baba, not to himself", "With long explanations of how the miracle worked", "By saying nothing at all", "By accepting their praise"], "question": "When devotees told Sri Babuji about their experiences, how did he usually respond?", "source_label": "Bound to Love, p. 27", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=49"}, {"answer": [0, 1, 2], "explanation": "'What I do is give medicines for your appetite – appetizers! Or sometimes, even a purgative or laxative when it is needed! And then I show you: 'Here is the delicious dish: Sai Baba.''", "id": "en-bk-030", "kind": "multi_select", "language": "en", "options": ["Appetizers for the appetite", "A purgative or laxative when needed", "Showing the 'delicious dish: Sai Baba'", "Prescribing himself as the cure"], "question": "Sri Babuji described his own work with a medical metaphor. Which of these did he name?", "source_label": "Bound to Love, p. 27", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=49"}, {"answer": 1, "explanation": "'Baba's udi and Guruji's compassion were the cure that restored my health and mental balance.' She treated the wounds only with udi and they healed completely.", "id": "en-bk-031", "kind": "single_select", "language": "en", "options": ["A special ointment", "Baba's udi and Sri Babuji's compassion — she treated the wounds only with udi", "A change of climate", "Homeopathy"], "question": "Saraswati Bevara of Srikakulam suffered a terrible itching, swelling skin disease for eight months. After she stopped all medicines and met Sri Babuji in Shirdi, what restored her?", "source_label": "Bound to Love, p. 52", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=74"}, {"answer": "Sai Baba", "explanation": "His personal principle, stated in the book's introduction to his life.", "id": "en-bk-032", "kind": "quote_completion", "language": "en", "question": "Complete the sentence about Sri Babuji's personal principle: 'to be dependent on nothing and nobody other than _____.'", "source_label": "Bound to Love, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=33"}, {"answer": 0, "explanation": "A biography of Sri Ramana Maharshi, the great saint of Arunachala. He would tear up any imperfect pages and have them typed again.", "id": "en-bk-033", "kind": "single_select", "language": "en", "options": ["Sri Ramana Maharshi", "Sri Poondi Swami", "Kabir", "Sri Ekkirala Bharadwaja"], "question": "At his Master's behest, Sri Babuji wrote a biography of which saint — typing the manuscript himself and tearing up any imperfect pages?", "source_label": "Bound to Love, p. 33", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=55"}, {"answer": false, "explanation": "'Sai Baba never publicized himself through discoursing, touring or preaching... His teaching was his own life and divine transforming presence.'", "id": "en-bk-034", "kind": "true_false", "language": "en", "question": "Sai Baba publicized Himself through discoursing, touring and preaching.", "source_label": "Bound to Love, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=30"}, {"answer": 1, "explanation": "In Venkatagiri, on his Master's instructions, giving satsang every day dedicated to Sai Baba.", "id": "en-bk-035", "kind": "single_select", "language": "en", "options": ["Ongole", "Venkatagiri", "Nellore", "Tiruvannamalai"], "question": "In 1977, Sri Babuji founded an English medium school in which place?", "source_label": "Bound to Love, p. 33", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=55"}, {"answer": 1, "explanation": "Eight months — 'This nightmare went on for eight months.'", "id": "en-bk-036", "kind": "single_select", "language": "en", "options": ["Two weeks", "Eight months", "Two years", "Five years"], "question": "In 'End of a nightmare' (Srikakulam), how long had the woman suffered from the itching, swelling skin affliction before she came to Shirdi?", "source_label": "Bound to Love, p. 51", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=73"}, {"answer": "'No... I am not a teacher! I am not a guru! I am not a saint! ... I am just like you. I am a simple Sai devotee.' (Bound to Love, p. 40.)", "explanation": "Sri Babuji's words, quoted verbatim in Bound to Love.", "id": "en-bk-037", "kind": "flashcard", "language": "en", "options": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf", "question": "Sri Babuji once asked a roomful of people: 'Have I called you? Have I invited you? Have I promised you anything?'", "source_label": "Sri Babuji's words, quoted verbatim in Bound to Love.", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf"}, {"answer": 1, "explanation": "Sri Babuji's own words, in a satsang recorded in Bound to Love.", "id": "en-bk-038", "kind": "single_select", "language": "en", "options": ["Sai Baba", "Sri Babuji", "B. V. Narasimha Swami", "Upasani Baba"], "question": "'In Baba I see love, his love to help everybody. He is ready to help. I see his power that can help so many people. And that spirit of willingness, that passion to help, that love is the basis of a Satguru.' Whose words?", "source_label": "Bound to Love, p. 50", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=72"}, {"answer": "responsibility.", "explanation": "Sri Babuji adds: 'Stepping into Dwarkamai means not physically stepping into the mosque, but becoming a child of Baba.'", "id": "en-bk-039", "kind": "quote_completion", "language": "en", "question": "Complete Baba's promise as quoted by Sri Babuji: 'The moment you step into this Dwarkamai, your karma has ended. Now it is my _____.'", "source_label": "Bound to Love, p. 121", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=143"}, {"answer": 0, "explanation": "Sai Deevena ('Sai's Blessings').", "id": "en-bk-040", "kind": "single_select", "language": "en", "options": ["Sai Deevena ('Sai's Blessings')", "Smriti Sumalu", "Sarathchandrikalu", "Sai Bhakti Sadhana Rahasyam"], "question": "The Telugu edition of Bound to Love is published under what title?", "source_label": "Bound to Love, p. 21", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=43"}, {"answer": true, "explanation": "No matter how noble the cause or intention, Sri Babuji always refused donations.", "id": "en-bk-041", "kind": "true_false", "language": "en", "question": "At Saipatham in Shirdi, a sign in the small office room at the entrance reads: 'Donations are neither expected nor accepted.'", "source_label": "Bound to Love, p. 82", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=104"}, {"answer": 1, "explanation": "'This hajji Falke waited for nine months but afterwards he was so well-treated...' — Baba didn't even allow him to step into the mosque at first.", "id": "en-bk-042", "kind": "single_select", "language": "en", "options": ["Nine days", "Nine months", "Nine years", "Nine hours"], "question": "Siddiq Falke, who had done the hajj pilgrimage, waited in Shirdi for how long just to be allowed into Dwarkamai?", "source_label": "Bound to Love, p. 61", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=83"}, {"answer": 0, "explanation": "'But saburi means happily waiting, waiting with a thrill.'", "id": "en-bk-043", "kind": "single_select", "language": "en", "options": ["happily waiting, waiting with a thrill", "cheerful endurance", "silent acceptance", "giving up wanting"], "question": "Sri Babuji said: 'Baba said nishtha and saburi are necessary. Nishtha is having a purposeful adherence to your own goal... And then saburi — it is usually translated as patience. However, the word 'patience' connotes a sense of suffering. But saburi means _____'", "source_label": "Bound to Love, pp. 60-61", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=82"}, {"answer": "When Guruji was to perform the girls' aksharabhyas in Poondi, the family waited anxiously for the astrologically 'right' moment. Guruji instead took the arrival of a man bearing Baba's calendars as Baba's own timing and did the ceremony — teaching that there is no need to resort to astrology; Baba is our sole refuge. (Bound to Love, p. 95.)", "explanation": "From the aksharabhyas episode in Poondi, Bound to Love.", "id": "en-bk-044", "kind": "flashcard", "language": "en", "options": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf", "question": "'See, Baba has come! This is the auspicious time set by Baba.'", "source_label": "From the aksharabhyas episode in Poondi, Bound to Love.", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf"}, {"answer": 0, "explanation": "'In common parlance in Indian culture, guru means not only a spiritual teacher, but anyone who teaches you – a profession, a musical instrument, or even the alphabet... Because of over-use, the word guru has become commonplace.'", "id": "en-bk-045", "kind": "single_select", "language": "en", "options": ["anyone who teaches you – a profession, a musical instrument, even the alphabet", "only a realized master", "a temple priest", "a village elder"], "question": "Sri Babuji explains why he says 'Satguru' rather than 'guru': in common Indian parlance, 'guru' also means _____?", "source_label": "Bound to Love, p. 179-180", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=201"}, {"answer": "them.", "explanation": "'Why didn't Baba give that complete fulfilment? Nobody asked, and nobody was interested.'", "id": "en-bk-046", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's summary of the essence of Baba's teachings: 'I will give people what they ask, till they ask me for what I want to give _____.'", "source_label": "Bound to Love, p. 148", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=170"}, {"answer": 0, "explanation": "'I always relate to people individually, personally. I advise people according to their nature... Everybody is unique to me. Every individual is so important. My goal is the individual.'", "id": "en-bk-047", "kind": "single_select", "language": "en", "options": ["The individual", "The organization", "The ritual", "The donation"], "question": "Sri Babuji told his devotees: 'I have told you again and again that, to me, a group is not important. _____ is important.'", "source_label": "Bound to Love, p. 78", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=100"}, {"answer": "ten rupees.", "explanation": "Sri Babuji adds: 'That is the real qualification' — Baba accepted donations as a fakir may, and more than repaid them.", "id": "en-bk-048", "kind": "quote_completion", "language": "en", "question": "Complete Baba's words as quoted by Sri Babuji: 'If I take one rupee from you, I have the obligation to give you _____.'", "source_label": "Bound to Love, p. 80", "source_link": "https://downloads.saibaba.com/publications/pdfs/Bound_to_love.pdf#page=102"}, {"answer": 1, "explanation": "Behind the verbal foreground, the writer felt 'a deep current of boundless peace and silence, radiant with an unfathomable love'.", "id": "en-bk-049", "kind": "single_select", "language": "en", "options": ["quiet and sleepy", "electric", "formal and solemn", "strictly silent"], "question": "The GuruPurnima Satsang Booklet opens: 'Satsang with Guruji was an extraordinary experience. The atmosphere was _____, sparkling with wit, insight, and humour.'", "source_label": "GuruPurnima Satsang Booklet, p. 2", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=2"}, {"answer": 0, "explanation": "It was his custom not to speak unless asked; he never spoke unilaterally, or discoursed or gave lectures.", "id": "en-bk-050", "kind": "single_select", "language": "en", "options": ["'What news?'", "'Who are you?'", "'What do you want?'", "'Why have you come?'"], "question": "Sri Babuji would look up and ask quietly, in his deep, rich, melodious bass voice:", "source_label": "GuruPurnima Satsang Booklet, p. 3", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=3"}, {"answer": [0, 1, 2], "explanation": "'Sat means 'truth' or 'reality', and sang means 'company' or 'communion'.' (1) communion with truth, (2) company of those who have realized the truth, (3) company of like-minded people sharing the truth.", "id": "en-bk-051", "kind": "multi_select", "language": "en", "options": ["Our communion with truth — attunement to truth", "Being in the company of those who have realized the truth", "Being in the company of like-minded people who share and discuss the truth", "Singing bhajans loudly in a temple"], "question": "Sri Babuji gave three meanings of satsang. Which are they?", "source_label": "GuruPurnima Satsang Booklet, p. 4", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=4"}, {"answer": true, "explanation": "He adds: 'Everything should be relevant to you, to your problem, to your need, to your situation.'", "id": "en-bk-052", "kind": "true_false", "language": "en", "question": "Sri Babuji says: 'Baba is not a set of beliefs or doctrines, some dogma. It is an individual experience.'", "source_label": "GuruPurnima Satsang Booklet, p. 4-5", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=5"}, {"answer": "He gives!", "explanation": "'He never says, ‘If you do this I will give you. Don't do that! If you do that I won't give you.’ Nothing like that. He knows how to give, that is my experience.'", "id": "en-bk-053", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's line on Baba's way: 'Because what Baba does, he doesn't do by any verbal teachings. His way is different: _____'", "source_label": "GuruPurnima Satsang Booklet, p. 6", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=6"}, {"answer": false, "explanation": "He says the opposite: 'Books and lectures will never transform anybody... It may be intellectually nourishing... but the actual transformation is not due to these words.'", "id": "en-bk-054", "kind": "true_false", "language": "en", "question": "Sri Babuji says the real transformation in satsang comes from the spoken word — 'books and lectures will transform anybody.'", "source_label": "GuruPurnima Satsang Booklet, p. 9", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=9"}, {"answer": 0, "explanation": "Samadhana: 'a state where there are no more questions, as if everything has been solved. The quest has ended.'", "id": "en-bk-055", "kind": "single_select", "language": "en", "options": ["Samadhana", "Samadhi", "Samskara", "Sadhana"], "question": "The Sanskrit word Sri Babuji uses for 'a state of being answered' — what a jnani gets — is:", "source_label": "GuruPurnima Satsang Booklet, p. 12", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=12"}, {"answer": "mystery", "explanation": "'Because by trying to give you answers I'm shutting down your curiosity, your sense of mystery, your quest.'", "id": "en-bk-056", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's line: 'I'm not trying to give you answers, I am only trying to create a sense of _____ in you.'", "source_label": "GuruPurnima Satsang Booklet, p. 13", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=13"}, {"answer": "'Always remember one thing in any satsang: never try to understand everything! ... This is like a restaurant, I have provided you with a menu, you pick those things which you like.' And: 'So don't quote chapattis!' (Booklet, p. 15.)", "explanation": "From the GuruPurnima Satsang Booklet's restaurant-menu teaching.", "id": "en-bk-057", "kind": "flashcard", "language": "en", "options": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf", "question": "Sri Babuji's restaurant-menu rule for satsang", "source_label": "From the GuruPurnima Satsang Booklet's restaurant-menu teaching.", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf"}, {"answer": 0, "explanation": "'If we love something and we get it, simply loving it gives us joy, happiness. If that love is not there, no joy will come.'", "id": "en-bk-058", "kind": "single_select", "language": "en", "options": ["mother", "sister", "food", "source"], "question": "Sri Babuji: 'Happiness is the child of love... So it is equal to: love is the _____ of happiness!'", "source_label": "GuruPurnima Satsang Booklet, p. 17", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/2020_GuruPurnima_Satsang_Booklet_English.pdf#page=17"}, {"answer": "long before.", "explanation": "'For some it is a long rope so that those needs and experiences can be fulfilled and then they can recognize Baba as their own, but the rope is there, whether it is long or short.'", "id": "en-bk-059", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's answer to a devotee who asked when Baba chose her: 'You are only aware of Baba now, but he was aware of you _____.'", "source_label": "Guru Booklet, p. 2", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf#page=2"}, {"answer": 1, "explanation": "'His grace will shower upon us, not by seeing our effort... Grace is unconditional. He just loves you because of the connection, the way a father loves a child.'", "id": "en-bk-060", "kind": "single_select", "language": "en", "options": ["righteousness", "rinanubandha", "initiation", "devotion"], "question": "'There is only _____, or 'indebtedness', which binds a Guru to you,' says Sri Babuji — grace is unconditional, like a father loving his child.", "source_label": "Guru Booklet, p. 5", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf#page=5"}, {"answer": 0, "explanation": "Tatya Kote Patil, one of Baba's closest devotees.", "id": "en-bk-061", "kind": "single_select", "language": "en", "options": ["Tatya Kote Patil", "Das Ganu", "Hemadpant", "Nanasaheb Chandorkar"], "question": "Which devotee is named in the Guru Booklet as the example of Baba's deeply personal love — people thought Baba gave up His body to save his life?", "source_label": "Guru Booklet, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf#page=8"}, {"answer": "Baba's words, quoted in the Guru Booklet (p. 10): 'His whole life and all his teachings are a commentary on that word.'", "explanation": "From the Guru Booklet's chapter on the Sadguru's omnipresence.", "id": "en-bk-062", "kind": "flashcard", "language": "en", "options": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf", "question": "'Where can I go? I am here.'", "source_label": "From the Guru Booklet's chapter on the Sadguru's omnipresence.", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf"}, {"answer": 0, "explanation": "'Not only are we pieces of iron but we are rusted pieces of iron! We don't have that sensitivity.'", "id": "en-bk-063", "kind": "single_select", "language": "en", "options": ["rusted!", "asleep", "too busy", "too far away"], "question": "'Guruji's magnetic field is all pervasive, but we don't experience it because we are _____.'", "source_label": "Guru Booklet, p. 12", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf#page=12"}, {"answer": [0, 1, 2], "explanation": "'That is your Himalaya! That is your ocean! That is your sky!' Guru in Sanskrit means big — and the experience of that vastness is where you become small but not unhappy.", "id": "en-bk-064", "kind": "multi_select", "language": "en", "options": ["The Himalayas", "The ocean", "The night sky", "A city skyline"], "question": "Sri Babuji describes the Sadguru's vastness — where becoming small brings joy, not fear — with which images?", "source_label": "Guru Booklet, pp. 23-25", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf#page=25"}, {"answer": 1, "explanation": "'We cannot push ourselves to submit our mind to the Guru. Bhagavan said, ‘Submit your mind to me and I will strike it.’'", "id": "en-bk-065", "kind": "single_select", "language": "en", "options": ["guide it", "strike it", "bless it", "free it"], "question": "Ramana Maharshi's instruction quoted in the Guru Booklet: 'Submit your mind to me and I will _____.'", "source_label": "Guru Booklet, p. 17", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf#page=17"}, {"answer": 0, "explanation": "'There is no need for Baba to wait for us like this flock of birds did, but he waits for us. He waits for us to give us a helping hand.'", "id": "en-bk-066", "kind": "single_select", "language": "en", "options": ["the Sadguru", "the world", "our family", "society"], "question": "In the Guru Booklet, Sri Babuji describes a flock of migrating birds receiving a lost, crippled bird. 'We are the crippled bird and that whole flock is _____.'", "source_label": "Guru Booklet, p. 20", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/Guru_booklet_English.pdf#page=20"}, {"answer": [0, 1, 2], "explanation": "The full reply: 'There should be no barriers or persons between the devotee and Baba. There should be no superstitions, rituals or ostentations — the only thing present should be love for Sai Baba.'", "id": "en-bk-067", "kind": "multi_select", "language": "en", "options": ["superstitions", "rituals", "ostentations", "donations"], "question": "When asked how a Sai Baba temple ought to be, Sri Babuji replied: 'There should be no barriers or persons between the devotee and Baba. There should be no _____, _____ or _____ — the only thing present should be love for Sai Baba.'", "source_label": "9 Vigrahapratistas, p. 4", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=4"}, {"answer": true, "explanation": "'In this way, over time, the devotees' love and dedication organically grow and take the form of a physical temple.'", "id": "en-bk-068", "kind": "true_false", "language": "en", "question": "Sri Babuji said that before a temple is built, devotees should gather over many years at the proposed site for prayer, worship and contemplation of Baba's life and teachings.", "source_label": "9 Vigrahapratistas, p. 4", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=4"}, {"answer": 0, "explanation": "The Sri Sainathuni Dhyana Mandiram at Haritachala, Tiruvannamalai and the Sri Sainathuni Dhyana Mandiram at Saibaba Central School, Ongole.", "id": "en-bk-069", "kind": "single_select", "language": "en", "options": ["Sri Sainathuni Dhyana Mandiram at Haritachala, Tiruvannamalai and the one at Saibaba Central School, Ongole", "The Samadhi Mandir and Dwarkamai", "The Shirdi and Bodhan temples", "The Tenali and Lalaguda temples"], "question": "According to the booklet, which two Sai Baba temples began simply as satsangs and later developed into temples?", "source_label": "9 Vigrahapratistas, p. 4", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=4"}, {"answer": 0, "explanation": "Tenali, Andhra Pradesh — 30 May 1993, at Morris Pet. 'This was special because it was the first arati to the statue of Sri Sai Baba offered by Sri Babuji.'", "id": "en-bk-070", "kind": "single_select", "language": "en", "options": ["Tenali, Andhra Pradesh — 30 May 1993", "Hyderabad — 12 April 1998", "Tirupati — 9 December 2001", "Bodhan — 15 January 2000"], "question": "Where and when was the FIRST vigrahapratishta — the first arati to a Baba statue offered by Sri Babuji?", "source_label": "9 Vigrahapratistas, p. 5", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=5"}, {"answer": 1, "explanation": "'Sai namam had been going on with fervour for 24 hours since the previous day.' The cold enveloping Bodhan lifted, and devotees felt nature itself had turned milder to welcome their Sadguru.", "id": "en-bk-071", "kind": "single_select", "language": "en", "options": ["12 hours", "24 hours", "48 hours", "One week"], "question": "At the Bodhan consecration (15 January 2000, the day of the Sankranthi festival), Sai namam had been going on with fervour since the previous day for how long?", "source_label": "9 Vigrahapratistas, p. 9", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=9"}, {"answer": 2, "explanation": "Three times: 'first in the temple, then in the adjacent satsang hall and finally from the dais outside the temple.'", "id": "en-bk-072", "kind": "single_select", "language": "en", "options": ["Once", "Twice", "Three times — in the temple, the satsang hall, and from the dais", "Continuously all day"], "question": "At Bodhan, after the consecration, devotees had the great fortune of Sri Babuji's darshan how many times?", "source_label": "9 Vigrahapratistas, p. 9", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=9"}, {"answer": 0, "explanation": "'This was such a sudden unusual change that it was reported the next day in 2018The Hindu2019 newspaper.'", "id": "en-bk-073", "kind": "single_select", "language": "en", "options": ["The Hindu newspaper", "The Times of India", "Eenadu", "It was not reported anywhere"], "question": "At the Tirupati consecration (9 December 2001, Konka Street), the hot weather suddenly turned cooler the moment Sri Babuji sat on the stage. Where was this reported the next day?", "source_label": "9 Vigrahapratistas, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=11"}, {"answer": 0, "explanation": "The villagers had kept it in the Satsang hall at Saiyana, Shirdi — 'it remained in that sacred atmosphere for over a year' before being taken in grand procession to Palsood.", "id": "en-bk-074", "kind": "single_select", "language": "en", "options": ["In the Satsang hall at Saiyana, Shirdi", "In the Samadhi Mandir", "At Tiruvannamalai", "In Bodhan"], "question": "Before its installation at Palsood (8 July 2001), where was the beautiful statue of Sri Sai Baba kept for over a year?", "source_label": "9 Vigrahapratistas, p. 10", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=10"}, {"answer": 0, "explanation": "12 April 1998 — the temple was decorated and prepared for the consecration of Sri Sai Baba's statue by Sri Babuji.", "id": "en-bk-075", "kind": "single_select", "language": "en", "options": ["12 April 1998", "30 May 1993", "3 January 2000", "14 January 2004"], "question": "The consecration at the APSRTC complex, Lalaguda, Hyderabad took place on which date?", "source_label": "9 Vigrahapratistas, p. 5", "source_link": "https://downloads.saibaba.com/publications/pdfs/2020/9_Vigrahapratistas_By_Sri_Babuji_english.pdf#page=6"}, {"answer": 0, "explanation": "Dasganu Maharaj was 'expressing that stupefied feeling where one forgets oneself' — and 'when we sing the arati our minds should get stupefied: that is the real arati.'", "id": "en-bk-076", "kind": "single_select", "language": "en", "options": ["'I am dumbfounded' — literally 'my tongue is exhausted'", "'I am forever grateful'", "'I sing Your praise'", "'I bow at Your feet'"], "question": "In the Arati chapter, what does 'Thaka gayi meri rasanaa' in Baba's arati mean?", "source_label": "Rose Petals, January 2012 — Arati", "source_link": "https://saipatham.saibaba.com/rose-petals/jan2012.html"}, {"answer": "Dasganu, an orthodox Brahmin, chose the most 'untouchable' object to be himself — the broom, the only thing with the fortune of collecting the dust of Baba's feet and of the devotees' feet too. Sri Babuji: 'So try to do the arati with meaning!'", "explanation": "Dasganu's expression of egolessness in the Kakad Arati.", "id": "en-bk-077", "kind": "flashcard", "language": "en", "question": "'Apane masjida ka jharu Ganu hai' — 'Ganu is your mosque's broom'", "source_label": "Rose Petals, January 2012 — Arati", "source_link": "https://saipatham.saibaba.com/rose-petals/jan2012.html"}, {"answer": 0, "explanation": "'He was so confident that Baba was a Muslim that he wanted to express it in a Muslim fashion, so he used Islamic wording.'", "id": "en-bk-078", "kind": "single_select", "language": "en", "options": ["He was so confident Baba was a Muslim that he wanted to express it in a Muslim fashion", "He didn't know Hindi", "It was required by tradition", "He wanted to convert Hindus"], "question": "Sri Babuji explains why Dasganu used Islamic wording like 'nazar' in his aratis. Why?", "source_label": "Rose Petals, January 2012 — Arati", "source_link": "https://saipatham.saibaba.com/rose-petals/jan2012.html"}, {"answer": false, "explanation": "'Just sitting there and happily enjoying listening to it and looking at Baba with respect, that is participating.' Being among fellow lovers gives added enjoyment.", "id": "en-bk-079", "kind": "true_false", "language": "en", "question": "Sri Babuji says everyone must sing the arati to truly participate in it.", "source_label": "Rose Petals, January 2012 — Arati", "source_link": "https://saipatham.saibaba.com/rose-petals/jan2012.html"}, {"answer": 0, "explanation": "Kabir related to Ram as His dog — 'even for only a biscuit... he will always be going around you.' Sri Babuji urges that egoless feeling.", "id": "en-bk-080", "kind": "single_select", "language": "en", "options": ["'I am Ram's dog!'", "'I am Ram's servant'", "'I am Ram's friend'", "'I am Ram's devotee'"], "question": "Kabir's self-description, quoted by Sri Babuji: 'Main Ram ka kuttaa hun!' means:", "source_label": "Rose Petals, January 2012 — Arati", "source_link": "https://saipatham.saibaba.com/rose-petals/jan2012.html"}, {"answer": "Sri Babuji: 'Try to read it and enjoy it — don't make it a textbook!' Read life like a novel and the book of life becomes 'a pleasure to read'.", "explanation": "From The Aesthetic Experience: read life as a novel, not a textbook.", "id": "en-bk-081", "kind": "flashcard", "language": "en", "question": "'Life is a novel, a beautiful novel! Written by whom? Written by Baba.'", "source_label": "Rose Petals, February 2012 — The Aesthetic Experience", "source_link": "https://saipatham.saibaba.com/rose-petals/feb2012.html"}, {"answer": 1, "explanation": "Going there just to cry — crying is unpleasant, yet he craved it, because what he got was an aesthetic experience, and that gives joy. 'That is the mystery of it!'", "id": "en-bk-082", "kind": "single_select", "language": "en", "options": ["To memorize the dialogues", "Going there just to cry — the crying gave him an aesthetic experience, which gives joy", "He owned the cinema", "He was paid to watch it"], "question": "Sri Babuji tells of a man who watched the Telugu tragedy Rakta Sambandham two hundred times. Why?", "source_label": "Rose Petals, February 2012 — The Aesthetic Experience", "source_link": "https://saipatham.saibaba.com/rose-petals/feb2012.html"}, {"answer": 0, "explanation": "'What is this static-dynamic? It's a paradox!' — and enjoying the paradox, not resisting it, gives beautiful insights.", "id": "en-bk-083", "kind": "single_select", "language": "en", "options": ["static-dynamic", "big-small", "hot-cold", "loud-silent"], "question": "Sri Babuji calls Arunachala a paradox: 'Aruna means dynamic, achala means static.' What is the paradox?", "source_label": "Rose Petals, February 2012 — The Aesthetic Experience", "source_link": "https://saipatham.saibaba.com/rose-petals/feb2012.html"}, {"answer": "Sri Babuji: a poet is not one who gives up saying 'I can't explain it' — a poet is one who tries. Like a mother who understands the different cries of her baby, the longing behind the words is what matters. 'His words are always worthy, that's why he is words-worth.'", "explanation": "From The Aesthetic Experience: a poet is one who tries to express the inexpressible.", "id": "en-bk-084", "kind": "flashcard", "language": "en", "question": "'All poetry is baaa baaas.'", "source_label": "Rose Petals, February 2012 — The Aesthetic Experience", "source_link": "https://saipatham.saibaba.com/rose-petals/feb2012.html"}, {"answer": 2, "explanation": "'But that nirvana should be your nirvana, your personal nirvana, not the Buddha's nirvana, not Sai Baba's nirvana nor Ramana Maharshi's nirvana – it should be your own nirvana!'", "id": "en-bk-085", "kind": "single_select", "language": "en", "options": ["The Buddha's nirvana", "Sai Baba's nirvana", "Your own personal nirvana — not someone else's", "Ramana Maharshi's nirvana"], "question": "In 'Start From Where You Are', what kind of nirvana does Sri Babuji say we should seek?", "source_label": "Rose Petals, March 2012 — Start Where You Are", "source_link": "https://saipatham.saibaba.com/rose-petals/mar2012web.html"}, {"answer": "Sri Babuji: the small fulfilment we have now is like one bird in the hand, lasting happiness like two in the bush — 'But they are not two! ... We evolve in happiness, we evolve in fulfilment!'", "explanation": "From Start Where You Are: temporary and lasting happiness are not two.", "id": "en-bk-086", "kind": "flashcard", "language": "en", "question": "'Let the path also be happy, not only the goal!'", "source_label": "Rose Petals, March 2012 — Start Where You Are", "source_link": "https://saipatham.saibaba.com/rose-petals/mar2012web.html"}, {"answer": false, "explanation": "'If there are ten million molecules in the iron, they won't become even ten million and one, nor will a single molecule be lost.' Nothing added, nothing lost — only the direction changes.", "id": "en-bk-087", "kind": "true_false", "language": "en", "question": "In Sri Babuji's magnet analogy, when a piece of iron becomes a magnet, molecules are added to it.", "source_label": "Rose Petals, April 2012 — In the Orbit of the Magnet", "source_link": "https://saipatham.saibaba.com/rose-petals/apr2012web.html"}, {"answer": 0, "explanation": "Arunachala was his magnet and he stuck to it like a piece of iron — 'If this was the practice of even a great saint, a siddha like Ramana Maharshi, then what about us?'", "id": "en-bk-088", "kind": "single_select", "language": "en", "options": ["'a magnetic hill' — 'a big magnet'", "a holy river", "a silent mountain", "the southern Kailash"], "question": "Ramana Maharshi called Arunachala:", "source_label": "Rose Petals, April 2012 — In the Orbit of the Magnet", "source_link": "https://saipatham.saibaba.com/rose-petals/apr2012web.html"}, {"answer": 1, "explanation": "'He sat for twelve years just looking at his Sadguru, focused totally on him. He said that his guru always loved and protected him wherever he was.'", "id": "en-bk-089", "kind": "single_select", "language": "en", "options": ["Forty days", "Twelve years", "Seven years", "One year"], "question": "Baba said that He sat for how long, gazing at His own Sadguru with total focus?", "source_label": "Rose Petals, April 2012 — In the Orbit of the Magnet", "source_link": "https://saipatham.saibaba.com/rose-petals/apr2012web.html"}, {"answer": "Sri Babuji, closing the magnet chapter: 'Complete fulfilment is our goal and we are all racing towards that goal! And when we get it, it becomes grace.'", "explanation": "Closing line of the magnet chapter, In the Orbit of the Magnet.", "id": "en-bk-090", "kind": "flashcard", "language": "en", "question": "'That 'G'-factor is the guru, that which makes the race the grace – guru-G!'", "source_label": "Rose Petals, April 2012 — In the Orbit of the Magnet", "source_link": "https://saipatham.saibaba.com/rose-petals/apr2012web.html"}, {"answer": 2, "explanation": "Six years. 'If floods were expected, I used to go earlier, at five o'clock, and take a raft... If I had a fever of 104 or 105 degrees, I would go! ... In six years I didn't miss even once.'", "id": "en-bk-091", "kind": "single_select", "language": "en", "options": ["One year", "Three years", "Six years", "Ten years"], "question": "In 1971, when Sri Babuji first met his Master, he was told: 'Take charge of the satsang!' — meaning just arranging the room and Baba's photos. For how long did he do it every Thursday without missing even once?", "source_label": "Rose Petals, May 2012 — Niyama", "source_link": "https://saipatham.saibaba.com/rose-petals/may2012web.html"}, {"answer": 1, "explanation": "He punished the mind's trickery: he put water in an earthen pot to make it colder, and got up even earlier at 2:45 a.m. 'Next time the mind didn't even dare to think that thought!'", "id": "en-bk-092", "kind": "single_select", "language": "en", "options": ["He gave up the niyama", "He got up even earlier (2:45 a.m.) and used water made colder in an earthen pot", "He slept longer", "He asked his Master to excuse him"], "question": "When Sri Babuji's mind tried to trick him into skipping his cold 3 a.m. bath, what did he do?", "source_label": "Rose Petals, May 2012 — Niyama", "source_link": "https://saipatham.saibaba.com/rose-petals/may2012web.html"}, {"answer": [0, 1, 2], "explanation": "Recalling or anticipating something affecting our image (imaginary); lack of clear understanding (remedied by clarity); experiencing pain or discomfort (the antidote is love).", "id": "en-bk-093", "kind": "multi_select", "language": "en", "options": ["Recalling or anticipating something that affects our image (the ego)", "Lack of clear understanding", "Experiencing pain or feeling uncomfortable", "Eating spicy food"], "question": "Sri Babuji names three reasons for anger. Which are they?", "source_label": "Rose Petals, June 2012 — Light on Anger", "source_link": "https://saipatham.saibaba.com/rose-petals/june2012web.html"}, {"answer": "She shouted in anger — then learned he was blind, and her anger instantly became 'Oh, I'm very, very sorry,' even offering him her seat. The anger was not from the pain, but from the expectation of politeness. Understanding transforms anger into compassion.", "explanation": "From Light on Anger: understanding turns anger into compassion.", "id": "en-bk-094", "kind": "flashcard", "language": "en", "question": "The blind man who stepped on her toe", "source_label": "Rose Petals, June 2012 — Light on Anger", "source_link": "https://saipatham.saibaba.com/rose-petals/june2012web.html"}, {"answer": 0, "explanation": "Baba's — and the saints': 'So saints don't feel it as aggression... a child doesn't know what she is doing.' Even when Jesus was being crucified he said, 'Father, they know not what they do.'", "id": "en-bk-095", "kind": "single_select", "language": "en", "options": ["Baba's", "A child's", "A king's", "His own"], "question": "Sri Babuji: 'If a child passes a stool on your leg, will you hit her? Will you cut off your leg?' — Whose reaction to provocation is he describing?", "source_label": "Rose Petals, June 2012 — Light on Anger", "source_link": "https://saipatham.saibaba.com/rose-petals/june2012web.html"}, {"answer": false, "explanation": "'What actually drove him from Madurai to Arunachala was simply his love of Arunachala, that's all.' Love is the driving force, not renunciation.", "id": "en-bk-096", "kind": "true_false", "language": "en", "question": "Sri Babuji says Ramana Maharshi left home out of a sense of renunciation, fed up with maya.", "source_label": "Rose Petals, July 2012 — The Chemistry of Love", "source_link": "https://saipatham.saibaba.com/rose-petals/july2012web.html"}, {"answer": "Sri Babuji: 'It is in the ego that love is kindled. And when the love grows, the ego is burnt up in the fire of love — it is no more there.' The form of the Sadguru acts like the wick (not wicked!). 'And it is there, only in love, that by losing one gains.'", "explanation": "From The Chemistry of Love: love burns the ego as fuel.", "id": "en-bk-097", "kind": "flashcard", "language": "en", "question": "The ego as fuel, the Sadguru's form as the wick", "source_label": "Rose Petals, July 2012 — The Chemistry of Love", "source_link": "https://saipatham.saibaba.com/rose-petals/july2012web.html"}, {"answer": 0, "explanation": "'If you are hungry and you don't get a full meal, will you refuse just a plate of iddlis? ... No, you will take even one iddly.' Love grows; the whole path is happiness.", "id": "en-bk-098", "kind": "single_select", "language": "en", "options": ["If you're hungry you won't refuse a plate of iddlis just because it's not a full meal", "A half candle still gives light", "A drop of water still quenches", "A single flower still smells sweet"], "question": "'Even if it's not 100%, 10% love is also good, because it is love.' Sri Babuji's homely illustration:", "source_label": "Rose Petals, July 2012 — The Chemistry of Love", "source_link": "https://saipatham.saibaba.com/rose-petals/july2012web.html"}, {"answer": false, "explanation": "'Even though it is not a path, just tell them, Guruji's path is a path of clarity and fulfilment.' Clarity first — even about so-called nirvana or Baba's sakshatkar.", "id": "en-bk-099", "kind": "true_false", "language": "en", "question": "Sri Babuji describes his path as a path of devotion (bhakti).", "source_label": "Rose Petals, August 2012 — Clarity and Fulfilment", "source_link": "https://saipatham.saibaba.com/rose-petals/aug2012web.html"}, {"answer": "lame", "explanation": "First stop blaming others: 'By realizing that other people are not responsible for your happiness or unhappiness. First you free them, then you'll be free from them.'", "id": "en-bk-100", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's wordplay: 'To blame is to 'be _____.''", "source_label": "Rose Petals, August 2012 — Clarity and Fulfilment", "source_link": "https://saipatham.saibaba.com/rose-petals/aug2012web.html"}, {"answer": 0, "explanation": "Each frame passes so quickly — 'twenty-four frames per second' — that it appears like one continuous reality. The principle of movement connects the frames.", "id": "en-bk-101", "kind": "single_select", "language": "en", "options": ["Twenty-four frames per second passing so fast they appear as one", "The projector's light alone", "The audience's imagination", "The actors' speed"], "question": "In 'The Principle of Flow', what makes a movie appear continuous though it is really separate frames?", "source_label": "Rose Petals, January 2015 — The Principle of Flow", "source_link": "https://saipatham.saibaba.com/rose-petals/january2015web.html"}, {"answer": "Sri Babuji on Arunachala: 'Aruna' (red — the colour of activity, the dynamic state) + 'achala' (not moving) — 'it's neither motionless nor full of motion, it's something beyond.'", "explanation": "From The Principle of Flow: Arunachala as dynamic stillness.", "id": "en-bk-102", "kind": "flashcard", "language": "en", "question": "'Aruna means red... achala is motionless, static.'", "source_label": "Rose Petals, January 2015 — The Principle of Flow", "source_link": "https://saipatham.saibaba.com/rose-petals/january2015web.html"}, {"answer": 0, "explanation": "'It makes you always live in the present, with no past memories, no future plans, no thoughts. He mirrors the dynamic nature of your own consciousness and you become one with it.'", "id": "en-bk-103", "kind": "single_select", "language": "en", "options": ["Live always in the present, with no past memories, no future plans, no thoughts", "Plan the future carefully", "Remember the past", "Analyze his form"], "question": "Sri Babuji: 'Watching the Ganges is just like watching Baba. A Sadguru always looks new, like the river... every moment he is new, as though you were seeing him for the first time.' What does this make you do?", "source_label": "Rose Petals, January 2015 — The Principle of Flow", "source_link": "https://saipatham.saibaba.com/rose-petals/january2015web.html"}, {"answer": 0, "explanation": "'You cannot achieve a pure goal through impure means.' The end is always abstract; what we have in hand is only the means, which is concrete.", "id": "en-bk-104", "kind": "single_select", "language": "en", "options": ["'You cannot achieve a pure goal through impure means'", "The end justifies the means", "Means don't matter if the goal is noble", "Only the goal is concrete, the means abstract"], "question": "In 'Purity of Means', what does Sri Babuji say about a pure goal and impure means?", "source_label": "Rose Petals, February 2015 — Purity of Means", "source_link": "https://saipatham.saibaba.com/rose-petals/february2015web.html"}, {"answer": 0, "explanation": "One village's violence was enough: 'That is adherence to purity of means: uncompromising, unflinching, steadfast adherence to the means, to the quality of the means. I like that.'", "id": "en-bk-105", "kind": "single_select", "language": "en", "options": ["Stopped the whole Non-Cooperation Movement", "Continued the movement", "Expelled the villagers", "Ignored the incident"], "question": "Sri Babuji admires Gandhi's adherence to purity of means: after the Chauri Chaura violence, what did Gandhi do?", "source_label": "Rose Petals, February 2015 — Purity of Means", "source_link": "https://saipatham.saibaba.com/rose-petals/february2015web.html"}, {"answer": "Sri Babuji: 'We're all his devotees and we need not fear. There's no such thing as worthy or unworthy. In fact, we're all unworthy and it's Baba who makes us worthy. We're all just like pieces of paper, and his grace is the governor's signature which makes them currency notes.'", "explanation": "From Purity of Means: Baba makes the unworthy worthy.", "id": "en-bk-106", "kind": "flashcard", "language": "en", "question": "'I never let my devotees down' — and what Baba said is law!", "source_label": "Rose Petals, February 2015 — Purity of Means", "source_link": "https://saipatham.saibaba.com/rose-petals/february2015web.html"}, {"answer": 0, "explanation": "'Why are we here, what are the things we should and shouldn't be doing, and how are we doing them? ... Here you are your own examiner!'", "id": "en-bk-107", "kind": "single_select", "language": "en", "options": ["Why are we here, what should/shouldn't we be doing, and how are we doing them", "Why, what, and how much", "Why me, what now, how long", "Why God, what soul, how mind"], "question": "Sri Babuji's three-point formula — 'Why, What and How' — means asking:", "source_label": "Rose Petals, February 2015 — Purity of Means", "source_link": "https://saipatham.saibaba.com/rose-petals/february2015web.html"}, {"answer": "puja", "explanation": "On rituals: 'If rituals become simply mechanical, without meaning, then you can throw them away.' But re-enacting them may trigger something — 'If you want to nurture an emotion, you have to express it.'", "id": "en-bk-108", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's definition: 'Anything you do to express your love – that is _____, that is worship.'", "source_label": "Rose Petals, March 2015 — The Role of Ritual", "source_link": "https://saipatham.saibaba.com/rose-petals/march2015web.html"}, {"answer": 0, "explanation": "'Saints come in order to breathe life into them again.' Jesus: 'I have come not to destroy the law but to fulfil it.' When the Vedic tradition became too ritualized, the Buddha came, Mahavira came — and 'now Sai Baba has come.'", "id": "en-bk-109", "kind": "single_select", "language": "en", "options": ["Breathe life into them again", "Abolish all rituals", "Create new religions", "Punish the priests"], "question": "On rituals: 'When the rituals started they conveyed some meaning, but during the course of time they can lose their meaning and become mechanical, just dead wood.' What does Sri Babuji say saints come to do?", "source_label": "Rose Petals, March 2015 — The Role of Ritual", "source_link": "https://saipatham.saibaba.com/rose-petals/march2015web.html"}, {"answer": 0, "explanation": "Jesus was not opposing the Jewish tradition — 'he was only saying it had become so ritualized that he wanted to infuse love and meaning into it.'", "id": "en-bk-110", "kind": "single_select", "language": "en", "options": ["fulfil it", "replace it", "judge it", "abolish it"], "question": "Sri Babuji quotes Jesus: 'I have come not to destroy the law but to _____.'", "source_label": "Rose Petals, March 2015 — The Role of Ritual", "source_link": "https://saipatham.saibaba.com/rose-petals/march2015web.html"}, {"answer": "'I think the effect which gives us the illusion that we are making a choice is called will. And if we go on willing and willing and willing like that, willing to be a part of that delusion, that would be our last will!'", "explanation": "From The Question of Choice: will as the illusion of choosing.", "id": "en-bk-111", "kind": "flashcard", "language": "en", "question": "'Will' — Sri Babuji's definition", "source_label": "Rose Petals, June 2015 — The Question of Choice", "source_link": "https://saipatham.saibaba.com/rose-petals/june2015web.html"}, {"answer": 0, "explanation": "'What I say is, you never had it to lose!' Take any small thing — how you dress, what you eat — 'and try to explore it. You will see that you don't have much choice!'", "id": "en-bk-112", "kind": "single_select", "language": "en", "options": ["'You never had it to lose!'", "It is absolute", "It grows with age", "It is the soul's nature"], "question": "In 'The Question of Choice', what does Sri Babuji say about our much-prized freedom to choose?", "source_label": "Rose Petals, June 2015 — The Question of Choice", "source_link": "https://saipatham.saibaba.com/rose-petals/june2015web.html"}, {"answer": 0, "explanation": "'You give the choice to him and you feel, ‘Yes, I have given the choice to him, he will steer my life... ’ ... He gives you that sense of security so that you can explore, and enjoy the choicelessness.'", "id": "en-bk-113", "kind": "single_select", "language": "en", "options": ["A sense of security, so we can explore and enjoy choicelessness", "Slavery", "Confusion", "Nothing at all"], "question": "Sri Babuji says that giving our choice to a Sadguru who loves us gives us:", "source_label": "Rose Petals, June 2015 — The Question of Choice", "source_link": "https://saipatham.saibaba.com/rose-petals/june2015web.html"}, {"answer": "Sri Babuji drops a pen and catches it mid-air: the pen was 'destined' to fall — but catching it shows destiny is not absolute. 'If this possibility was not there, there would be no question of spirituality, a Sadguru, mukti or liberation.'", "explanation": "From The Question of Choice: catching the pen refutes absolute predestination.", "id": "en-bk-114", "kind": "flashcard", "language": "en", "question": "The pen-drop: predestination vs. grace", "source_label": "Rose Petals, June 2015 — The Question of Choice", "source_link": "https://saipatham.saibaba.com/rose-petals/june2015web.html"}, {"answer": 0, "explanation": "'But all thoughts express something within you, they are trying to catch hold of some sort of fulfilment in you.' A thought is just like a wave — it comes and goes.", "id": "en-bk-115", "kind": "single_select", "language": "en", "options": ["five or six", "fifty", "ninety", "none"], "question": "In 'The Mind': 'Of a hundred thoughts, probably only _____ are really needed and relevant.'", "source_label": "Rose Petals, August 2015 — The Mind", "source_link": "https://saipatham.saibaba.com/rose-petals/august2015web.html"}, {"answer": 0, "explanation": "'In a drama there are two types of speaking: dialogue or soliloquy. Our thoughts are our soliloquies.' There is such a human need for expression that even when nobody is there, we express at least to ourselves.", "id": "en-bk-116", "kind": "single_select", "language": "en", "options": ["soliloquies", "enemies", "masters", "dreams"], "question": "Sri Babuji on thoughts: 'Our thoughts are our _____, we talk to ourselves in our thoughts.'", "source_label": "Rose Petals, August 2015 — The Mind", "source_link": "https://saipatham.saibaba.com/rose-petals/august2015web.html"}, {"answer": "Young Sri Babuji, frustrated with dry Vedantic answers: 'My problem is not that I don't know who I am... When I ask about my problem, you talk about God. I'm not concerned about Him! What about me, first tell me that!'", "explanation": "From Guruji's Early Years of Seeking: Sri Babuji's demand for real answers.", "id": "en-bk-117", "kind": "flashcard", "language": "en", "question": "'Let God rest happily in his so-called heaven. What about me?'", "source_label": "Rose Petals, October 2015 — Guruji's Early Years of Seeking", "source_link": "https://saipatham.saibaba.com/rose-petals/october2015web.html"}, {"answer": 1, "explanation": "The Master had 'never faced such an opponent' and encouraged him: 'Come on! Come on! Come on!' Sri Babuji was nearly eighteen then.", "id": "en-bk-118", "kind": "single_select", "language": "en", "options": ["Silenced him", "Encouraged him — 'Come on! Come on! Come on!'", "Sent him away", "Answered in Vedantic jargon"], "question": "When young Sri Babuji argued fiercely with his Master, what did the Master do?", "source_label": "Rose Petals, October 2015 — Guruji's Early Years of Seeking", "source_link": "https://saipatham.saibaba.com/rose-petals/october2015web.html"}, {"answer": "guru!", "explanation": "'It was Sai Baba who came in his form and then taught me what was needed.'", "id": "en-bk-119", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words about his Master: 'He is my guru. He was my guru, he is my guru, he will be my ___.'", "source_label": "Rose Petals, October 2015 — Guruji's Early Years of Seeking", "source_link": "https://saipatham.saibaba.com/rose-petals/october2015web.html"}, {"answer": "Sri Babuji on following his guru: 'He held out a stick, I grasped the other end of the stick and followed him... Without choices and without excuses. ... any word, any instruction of his, whether spiritual or material, was law to me.'", "explanation": "From Guruji's Early Years of Seeking: following the guru without choices or excuses.", "id": "en-bk-120", "kind": "flashcard", "language": "en", "question": "The blind man and the stick", "source_label": "Rose Petals, October 2015 — Guruji's Early Years of Seeking", "source_link": "https://saipatham.saibaba.com/rose-petals/october2015web.html"}, {"answer": 0, "explanation": "'They might have been one of the stones that helped me hit the mango on the tenth try, by helping me learn the art of throwing.' He found another, easier way — which is why he doesn't prescribe these practices.", "id": "en-bk-121", "kind": "single_select", "language": "en", "options": ["'One of the stones that helped me hit the mango on the tenth try, by helping me learn the art of throwing'", "A complete waste of time", "The only true path", "What he prescribes to everyone"], "question": "Sri Babuji's 'mango' analogy: his years of strenuous sadhanas (mantra, tantra, japa; no sandals; 3 a.m. cold baths) were:", "source_label": "Rose Petals, October 2015 — Guruji's Early Years of Seeking", "source_link": "https://saipatham.saibaba.com/rose-petals/october2015web.html"}, {"answer": false, "explanation": "'I found something else... I don't prescribe these practices to you, in the same manner, because I found another way to easily achieve the same goal. But, if you want to do all that, good, do it! No problem.'", "id": "en-bk-122", "kind": "true_false", "language": "en", "question": "Sri Babuji prescribes his own extreme early sadhanas (no sandals, 3 a.m. cold baths, never looking at a movie poster) to his devotees.", "source_label": "Rose Petals, October 2015 — Guruji's Early Years of Seeking", "source_link": "https://saipatham.saibaba.com/rose-petals/october2015web.html"}, {"answer": 0, "explanation": "'A Sadguru will never reject anybody. That's how Baba himself phrases it.'", "id": "en-bk-123", "kind": "single_select", "language": "en", "options": ["merge", "vanish", "drown", "return"], "question": "Complete Baba's words as quoted by Sri Babuji: 'I won't reject anybody. Will the ocean reject the rivers which are coming and merging into it?' — 'The Sadguru is like the ocean, so there is no question of rejecting the rivers — they come and simply _____.'", "source_label": "Rose Petals, December 2015 — Guru and Disciple", "source_link": "https://saipatham.saibaba.com/rose-petals/december2015web.html"}, {"answer": "Sri Babuji, when a devotee feared rejection: 'I never reject anyone. I accept everybody because they are Baba's prasad to me. Without Baba's will, without Baba's calling, nobody comes to me.'", "explanation": "From Guru and Disciple: Sri Babuji never rejects anyone.", "id": "en-bk-124", "kind": "flashcard", "language": "en", "question": "'You are all Baba's prasad to me. Sacred prasad. How can anyone reject prasad?'", "source_label": "Rose Petals, December 2015 — Guru and Disciple", "source_link": "https://saipatham.saibaba.com/rose-petals/december2015web.html"}, {"answer": 0, "explanation": "'The real sign of a disciple's maturity is that he doesn't think of any other thing than his object of love; he doesn't seek signs of maturity. That is the sign of maturity!' Like a fruit maturing on the tree — 'Baba is the tree and we're all hanging from one of his many branches.'", "id": "en-bk-125", "kind": "single_select", "language": "en", "options": ["He doesn't think of any other thing than his object of love; he doesn't seek signs of maturity", "He meditates six hours daily", "He can quote the scriptures", "He wears simple clothes"], "question": "What does Sri Babuji say is the real sign of a disciple's maturity?", "source_label": "Rose Petals, December 2015 — Guru and Disciple", "source_link": "https://saipatham.saibaba.com/rose-petals/december2015web.html"}, {"answer": false, "explanation": "He says liberation is not merely freedom from suffering — one wants happiness itself.", "id": "en-tx-001", "kind": "true_false", "language": "en", "question": "Sri Babuji says liberation is merely freedom from suffering.", "source_label": "Fire of Love: Happiness", "source_link": "https://www.youtube.com/watch?v=7Gw7MhpUuME&t=0s"}, {"answer": 0, "explanation": "He argues there is nothing wrong with wanting happiness, so long as it is a permanent happiness that brings no pain as its consequence.", "id": "en-tx-002", "kind": "single_select", "language": "en", "options": ["There is nothing wrong with it, so long as it is a permanent happiness that brings no pain", "Wanting happiness is selfish and must be dropped", "It should wait until after liberation", "Happiness is only for saints"], "question": "What does Sri Babuji say about wanting happiness?", "source_label": "Fire of Love: Happiness", "source_link": "https://www.youtube.com/watch?v=7Gw7MhpUuME&t=0s"}, {"answer": "The goal is not just removal of pain but the gain of happiness itself — a permanent happiness that brings no pain as its consequence.", "explanation": "Tap to reveal: the gain of happiness is Sri Babuji's stated goal of the spiritual life.", "id": "en-tx-003", "kind": "flashcard", "language": "en", "question": "'The gain of happiness' — what does Sri Babuji mean by this?", "source_label": "Fire of Love: Happiness", "source_link": "https://www.youtube.com/watch?v=7Gw7MhpUuME&t=60s"}, {"answer": true, "explanation": "The fear of death comes from love of life; the remedy is to make life lovable.", "id": "en-tx-004", "kind": "true_false", "language": "en", "question": "Sri Babuji says we fear death because we love life — death implies its extinction.", "source_label": "Fire of Love: Love of Life", "source_link": "https://www.youtube.com/watch?v=9STJJys807w&t=0s"}, {"answer": 0, "explanation": "The real problem is that our life is not so lovable; the remedy is to make life lovable and focus on fulfillment here and now.", "id": "en-tx-005", "kind": "single_select", "language": "en", "options": ["Our life is not lovable — we must make life lovable", "Too much philosophy", "Fear of the unknown future", "Attachment to our family"], "question": "What does Sri Babuji call the real problem behind the fear of death?", "source_label": "Fire of Love: Love of Life", "source_link": "https://www.youtube.com/watch?v=9STJJys807w&t=0s"}, {"answer": [0, 1, 2], "explanation": "Make life lovable, focus on fulfillment here and now, and know life's true principle — then the fear of death is seen as an illusion.", "id": "en-tx-006", "kind": "multi_select", "language": "en", "options": ["Make life lovable", "Focus on fulfillment here and now", "Truly know the principle of life — how lovable and blissful life itself is", "Increase your fear so that courage is born"], "question": "Which of these are part of Sri Babuji's teaching on overcoming the fear of death? (Choose all that apply)", "source_label": "Fire of Love: Love of Life", "source_link": "https://www.youtube.com/watch?v=9STJJys807w&t=60s"}, {"answer": [1, 2, 0], "explanation": "1 → why you are here; 2 → don't be pulled astray; 3 → sample survey of how you spent the day.", "id": "en-tx-007", "kind": "matching", "language": "en", "options": ["Take a 'sample survey' of how you spent the day", "Remember why you are here, why you have come", "Don't let situations pull you astray or dilute your purpose"], "question": "Match each of the three points Sri Babuji gives for the spiritual objective to its meaning: 1. Remember the goal 2. Guard its intensity 3. Keep up the focus", "source_label": "Fire of Love: The Objective", "source_link": "https://www.youtube.com/watch?v=RqROyzZJjVI&t=0s"}, {"answer": 0, "explanation": "Take a 'sample survey' of how the day was spent — what you aspired for, where you are going.", "id": "en-tx-008", "kind": "single_select", "language": "en", "options": ["Reviewing how you spent your day", "Counting your japa repetitions", "Surveying fellow devotees", "Listing your desires"], "question": "What does Sri Babuji mean by a 'sample survey'?", "source_label": "Fire of Love: The Objective", "source_link": "https://www.youtube.com/watch?v=RqROyzZJjVI&t=60s"}, {"answer": "Spiritual progress is not growth or development but unfoldment — like a bud blossoming into a flower: nothing is added; the folds of what is already there slowly open.", "explanation": "Tap to reveal: unfoldment — discovering the real is removing the cover.", "id": "en-tx-009", "kind": "flashcard", "language": "en", "question": "'Unfoldment' — how does Sri Babuji distinguish it from growth?", "source_label": "Fire of Love: Unfoldment", "source_link": "https://www.youtube.com/watch?v=o-i9fNqmeUc&t=0s"}, {"answer": true, "explanation": "The key word is to enjoy the process: love is to be experienced and enjoyed, not suffered.", "id": "en-tx-010", "kind": "true_false", "language": "en", "question": "Sri Babuji says love is to be experienced and enjoyed, not suffered.", "source_label": "Fire of Love: Unfoldment", "source_link": "https://www.youtube.com/watch?v=o-i9fNqmeUc&t=60s"}, {"answer": "Sai devotee", "explanation": "His own words: 'I am not a guru, I am a Sai devotee... what I share with you is my love of Sai Baba.'", "id": "en-tx-011", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words: 'I am not a guru, I am a ___.'", "source_label": "Fire of Love 2007 intro", "source_link": "https://www.youtube.com/watch?v=oshNMzmPojQ&t=120s"}, {"answer": 0, "explanation": "The intro notes his transforming mystic experience at 18 and his settling in Shirdi in 1989.", "id": "en-tx-012", "kind": "single_select", "language": "en", "options": ["1989", "1975", "1995", "2001"], "question": "Since which year has Sri Babuji made Shirdi his home, according to the 2007 intro?", "source_label": "Fire of Love 2007 intro", "source_link": "https://www.youtube.com/watch?v=oshNMzmPojQ&t=60s"}, {"answer": true, "explanation": "The intro presents Sai Baba as a master described as a rare fusion of power, love and knowledge.", "id": "en-tx-013", "kind": "true_false", "language": "en", "question": "Sri Babuji describes Sai Baba as a rare fusion of power, love and knowledge.", "source_label": "Fire of Love 2007 intro", "source_link": "https://www.youtube.com/watch?v=oshNMzmPojQ&t=0s"}, {"answer": 0, "explanation": "The intro notes his transforming mystic experience at 18.", "id": "en-tx-014", "kind": "single_select", "language": "en", "options": ["18", "12", "25", "30"], "question": "At what age did Sri Babuji have his transforming mystic experience, according to the 2007 intro?", "source_label": "Fire of Love 2007 intro", "source_link": "https://www.youtube.com/watch?v=oshNMzmPojQ&t=60s"}, {"answer": 0, "explanation": "Guru means big: the interplay of that bigness with our smallness, until the self withers away, is the experience of the guru.", "id": "en-tx-015", "kind": "single_select", "language": "en", "options": ["Big", "Teacher", "Light", "Grace"], "question": "What does Sri Babuji say 'guru' means?", "source_label": "Fire of Love: The Magnificence", "source_link": "https://www.youtube.com/watch?v=sm_HMB__Hyo&t=60s"}, {"answer": false, "explanation": "The mind focuses on greatness and experiences its own smallness with wonder, not humiliation.", "id": "en-tx-016", "kind": "true_false", "language": "en", "question": "Experiencing one's own smallness before greatness — the Himalayas, the sky, Arunachala, the Sadguru — should be felt as humiliation.", "source_label": "Fire of Love: The Magnificence", "source_link": "https://www.youtube.com/watch?v=sm_HMB__Hyo&t=0s"}, {"answer": "Such darshan should give aesthetic enjoyment and happiness, leaving no room for suffering.", "explanation": "Tap to reveal: the aesthetics of smallness — enjoying becoming dust underneath his feet.", "id": "en-tx-017", "kind": "flashcard", "language": "en", "question": "'Aesthetic enjoyment' — what should darshan of the Sadguru give?", "source_label": "Fire of Love: The Magnificence", "source_link": "https://www.youtube.com/watch?v=sm_HMB__Hyo&t=120s"}, {"answer": "Strangely familiar yet unknown — the mixture of strangeness and familiarity that is the first pull of the magnet.", "explanation": "Tap to reveal: the Sadguru connects to the missing part in us.", "id": "en-tx-018", "kind": "flashcard", "language": "en", "question": "'The familiar stranger' — what does Sri Babuji mean by this name for the Sadguru?", "source_label": "Fire of Love: Familiar Stranger", "source_link": "https://www.youtube.com/watch?v=vOZA7XTXxxc&t=60s"}, {"answer": true, "explanation": "Having everything yet feeling something missing — what is missing is Love: not family love, but something else.", "id": "en-tx-019", "kind": "true_false", "language": "en", "question": "Sri Babuji says what is missing in life is Love — not family love, but something else.", "source_label": "Fire of Love: Familiar Stranger", "source_link": "https://www.youtube.com/watch?v=vOZA7XTXxxc&t=60s"}, {"answer": [1, 0, 2], "explanation": "1 → the Sadguru, strangely familiar yet unknown; 2 → life as a wrong calculation lacking the right formula; 3 → the mixture of strangeness and familiarity.", "id": "en-tx-020", "kind": "matching", "language": "en", "options": ["Life with something missing — lacking the right formula", "The Sadguru: strangely familiar yet unknown", "The mixture of strangeness and familiarity"], "question": "Match each image Sri Babuji uses to its meaning: 1. A familiar stranger 2. A wrong mathematical calculation 3. The first pull of the magnet", "source_label": "Fire of Love: Familiar Stranger", "source_link": "https://www.youtube.com/watch?v=vOZA7XTXxxc&t=0s"}, {"answer": 0, "explanation": "The trailer records his two meanings of samadhi: a tomb, and the state where all needs are answered.", "id": "en-tx-021", "kind": "single_select", "language": "en", "options": ["A tomb, and the state where all needs are answered", "Meditation and absorption", "Silence and chanting", "Service and worship"], "question": "In the Rose Petals 2011 trailer, what two meanings of 'samadhi' does Sri Babuji give?", "source_label": "Rose Petals 2011 trailer", "source_link": "https://www.youtube.com/watch?v=IXAvnIHxzdM&t=180s"}, {"answer": "feet", "explanation": "His words in the trailer: the real namaskar is the awareness of Baba's feet on our head.", "id": "en-tx-022", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words: 'The real namaskar is the awareness of Baba's ___ on our head.'", "source_label": "Rose Petals 2011 trailer", "source_link": "https://www.youtube.com/watch?v=IXAvnIHxzdM&t=660s"}, {"answer": "Express love to strengthen it — the more you express, the more it grows.", "explanation": "Tap to reveal: expressing love strengthens it.", "id": "en-tx-023", "kind": "flashcard", "language": "en", "question": "'Express love' — what does Sri Babuji teach about expressing love?", "source_label": "Rose Petals 2011 trailer", "source_link": "https://www.youtube.com/watch?v=IXAvnIHxzdM&t=360s"}, {"answer": "refuse", "explanation": "His words: 'I don't call anybody but I don't refuse anybody.'", "id": "en-tx-024", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words: 'I don't call anybody but I don't ___ anybody.'", "source_label": "Rose Petals 2011 trailer", "source_link": "https://www.youtube.com/watch?v=IXAvnIHxzdM&t=540s"}, {"answer": 0, "explanation": "The judge's address: Guruji taught a simple sadhana suited to modern times — Gurusthan and meditation.", "id": "en-tx-025", "kind": "single_select", "language": "en", "options": ["Gurusthan and meditation", "Fasting and silence", "Scriptural study", "Pilgrimages"], "question": "What sadhana did Sri Babuji teach the retired judge as suited to modern times?", "source_label": "Saibaba Central School Annual Day 2014", "source_link": "https://www.youtube.com/watch?v=ZAaTnbOBA1Y&t=4800s"}, {"answer": "sadhana", "explanation": "His simple teaching, repeated to the judge: 'Be happy, blissful; bliss is our sadhana.'", "id": "en-tx-026", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words: 'Be happy, blissful — bliss is our ___.'", "source_label": "Saibaba Central School Annual Day 2014", "source_link": "https://www.youtube.com/watch?v=ZAaTnbOBA1Y&t=5280s"}, {"answer": true, "explanation": "The judge's heartfelt address: no one was dearer to Guruji than Swami Vivekananda.", "id": "en-tx-027", "kind": "true_false", "language": "en", "question": "The retired judge said no one was dearer to Sri Babuji than Swami Vivekananda.", "source_label": "Saibaba Central School Annual Day 2014", "source_link": "https://www.youtube.com/watch?v=ZAaTnbOBA1Y&t=4500s"}, {"answer": 0, "explanation": "The guru is like a window — conditioned in four walls, we look through him at the unlimited sky.", "id": "en-tx-028", "kind": "single_select", "language": "en", "options": ["A window through which we see the unlimited sky", "A lamp in the dark", "A bridge over a river", "A boat across the ocean"], "question": "In the 'Sparks from the Fire of Love' documentary, what does Sri Babuji compare the guru to?", "source_label": "Sparks from the Fire of Love (documentary)", "source_link": "https://www.youtube.com/watch?v=uJbwwO4sDNg&t=739s"}, {"answer": "Buddha", "explanation": "His words: 'Everybody should have their own path — everybody becomes a Buddha.'", "id": "en-tx-029", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words: 'Everybody should have their own path — everybody becomes a ___.'", "source_label": "Sparks from the Fire of Love (documentary)", "source_link": "https://www.youtube.com/watch?v=uJbwwO4sDNg&t=1642s"}, {"answer": "Conditioned in four walls, we look through the guru at the unlimited sky.", "explanation": "Tap to reveal: the guru as a window.", "id": "en-tx-030", "kind": "flashcard", "language": "en", "question": "'The guru is like a window' — what does Sri Babuji mean?", "source_label": "Sparks from the Fire of Love (documentary)", "source_link": "https://www.youtube.com/watch?v=uJbwwO4sDNg&t=739s"}, {"answer": [1, 2, 0], "explanation": "1 → one stone fells the mango, but the eleven before taught the art of throwing; 2 → he learns the science until it becomes spontaneous art; 3 → the truth is in between.", "id": "en-tx-031", "kind": "matching", "language": "en", "options": ["The truth is in between: practice is gradual, realization is instantaneous", "One stone fells the mango — but the eleven stones before taught the art of throwing", "The sportsman learns the science until it becomes spontaneous art"], "question": "Match each image Sri Babuji uses to its meaning: 1. Throwing stones at a mango 2. The sportsman 3. Gradual or instantaneous?", "source_label": "Is enlightenment gradual or instantaneous?", "source_link": "https://www.youtube.com/watch?v=7NmooPW4tkQ&t=0s"}, {"answer": false, "explanation": "The truth is in between: practice is gradual, realization is instantaneous.", "id": "en-tx-032", "kind": "true_false", "language": "en", "question": "Sri Babuji says enlightenment is purely instantaneous.", "source_label": "Is enlightenment gradual or instantaneous?", "source_link": "https://www.youtube.com/watch?v=7NmooPW4tkQ&t=0s"}, {"answer": "instantaneous", "explanation": "His answer to the long-debated question: 'Practice is gradual; realization is instantaneous.'", "id": "en-tx-033", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's answer: 'Practice is gradual; realization is ___.'", "source_label": "Is enlightenment gradual or instantaneous?", "source_link": "https://www.youtube.com/watch?v=7NmooPW4tkQ&t=120s"}, {"answer": 0, "explanation": "Real progress is the transformation of one's personality — how you look at the world and yourself, how you interact with people.", "id": "en-tx-034", "kind": "single_select", "language": "en", "options": ["The transformation of one's personality", "Flashes of light and visions", "Booms of sound", "Longer meditation sittings"], "question": "What does Sri Babuji say is the real sign of spiritual progress?", "source_label": "How do I know whether I have progressed?", "source_link": "https://www.youtube.com/watch?v=OnNz1Zb6thQ&t=34s"}, {"answer": "True transformation is usually gradual, like the graying of hair — you look in the mirror daily and one day find it grey.", "explanation": "Tap to reveal: real change is like the graying of hair.", "id": "en-tx-035", "kind": "flashcard", "language": "en", "question": "'Like the graying of hair' — what does Sri Babuji say about real transformation?", "source_label": "How do I know whether I have progressed?", "source_link": "https://www.youtube.com/watch?v=OnNz1Zb6thQ&t=186s"}, {"answer": false, "explanation": "Without any change in personality, dislikes, or temptations, such experiences are just mental aberrations — complexes and patterns not given up.", "id": "en-tx-036", "kind": "true_false", "language": "en", "question": "Sri Babuji says dazzling experiences like visions and flashes of light are sure signs of spiritual progress.", "source_label": "How do I know whether I have progressed?", "source_link": "https://www.youtube.com/watch?v=OnNz1Zb6thQ&t=85s"}, {"answer": true, "explanation": "In worldly matters success and failure are visible, but in spiritual matters helplessness can hide under the guise of a seeker.", "id": "en-tx-039", "kind": "true_false", "language": "en", "question": "Sri Babuji says spirituality is definitely not for those who fail in the world — turning to it as an escape is the worst reason.", "source_label": "What if someone needs worldly acceptance first?", "source_link": "https://www.youtube.com/watch?v=Hj5K0LdkmLs&t=120s"}, {"answer": 0, "explanation": "The search becomes superimposed and artificial — he would only be imitating another seeker.", "id": "en-tx-040", "kind": "single_select", "language": "en", "options": ["The search becomes superimposed and artificial — he only imitates another seeker", "He becomes enlightened quickly", "He loses all fear at once", "He gains instant dispassion"], "question": "What happens when someone is told the world is transient before he sees its futility himself?", "source_label": "What if someone needs worldly acceptance first?", "source_link": "https://www.youtube.com/watch?v=Hj5K0LdkmLs&t=0s"}, {"answer": 0, "explanation": "Mirabai saw no man but Krishna.", "id": "en-tx-041", "kind": "single_select", "language": "en", "options": ["She saw no man but Krishna", "As brothers", "As strangers", "As equals to Krishna"], "question": "How did Mirabai see men?", "source_label": "Mirabai's all-consuming love", "source_link": "https://www.youtube.com/watch?v=XL8SeO6N6d4&t=180s"}, {"answer": "The experience of incompleteness seeking completion — Ramana put himself in the role of a bride before Arunachala.", "explanation": "Tap to reveal: the feminine principle in devotion.", "id": "en-tx-042", "kind": "flashcard", "language": "en", "question": "'The feminine principle' — what does Sri Babuji say it is?", "source_label": "Mirabai's all-consuming love", "source_link": "https://www.youtube.com/watch?v=XL8SeO6N6d4&t=240s"}, {"answer": "The street artist who refused a platter of diamonds as a sanyasi, then begged for tips as a dancer — 'we play our role perfectly.'", "explanation": "Tap to reveal: the Guru must play his role perfectly — doing what is good for you whether you like it or not.", "id": "en-tx-043", "kind": "flashcard", "language": "en", "question": "'The sanyasi and the dancer' — what is the story Sri Babuji tells about the role of the Guru?", "source_label": "The role of the Guru", "source_link": "https://www.youtube.com/watch?v=BaoYhRGzWVo&t=60s"}, {"answer": true, "explanation": "He must play his role perfectly — doing what he thinks is good for you whether you like it or not, not what you like.", "id": "en-tx-044", "kind": "true_false", "language": "en", "question": "Sri Babuji says the Guru must do what is good for you whether you like it or not, not what you like.", "source_label": "The role of the Guru", "source_link": "https://www.youtube.com/watch?v=BaoYhRGzWVo&t=300s"}, {"answer": 0, "explanation": "One whose emotions have been completely harmonized becomes like a magnet: when the devotee (the iron) comes into contact, the Guru becomes one with him and restores balance from within.", "id": "en-tx-045", "kind": "single_select", "language": "en", "options": ["The Satguru whose harmonized emotions attract and balance the devotee", "A guru who pulls crowds to himself", "The attraction of worldly power", "A trick of the mind"], "question": "What is the magnet-and-iron analogy for in 'What is Sai Baba's state of being'?", "source_label": "What is Sai Baba's state of being?", "source_link": "https://www.youtube.com/watch?v=G57dV5-8Yyw&t=16s"}, {"answer": "Asked how the Guru helps millions at once: for him there are no 'millions' — as you don't count the millions of cells in your body yet feel and respond to each one.", "explanation": "Tap to reveal: the body-cells analogy for the Guru's all-at-once care.", "id": "en-tx-046", "kind": "flashcard", "language": "en", "question": "'The body-cells analogy' — how does Sri Babuji answer 'how can he do this for millions at once?'", "source_label": "What is Sai Baba's state of being?", "source_link": "https://www.youtube.com/watch?v=G57dV5-8Yyw&t=214s"}, {"answer": true, "explanation": "A devotee who could not visit Shirdi was approached by a stranger who asked for his seat and handed him a packet of udi sent from Sri Lanka.", "id": "en-tx-047", "kind": "true_false", "language": "en", "question": "In the train incident, a stranger handed a devotee traveling with his little son a packet of udi sent from Sri Lanka.", "source_label": "What is Sai Baba's state of being?", "source_link": "https://www.youtube.com/watch?v=G57dV5-8Yyw&t=264s"}, {"answer": 0, "explanation": "The world is like a dark statue — we see it and react with fear, love, jealousy, until the Sadguru takes our hand to the light.", "id": "en-tx-048", "kind": "single_select", "language": "en", "options": ["A dark statue", "A deep ocean", "A dark forest", "A mirror"], "question": "What analogy does Sri Babuji use for the world in 'Is the experience of the world the same for a realised person'?", "source_label": "Experience of the world for a realised person", "source_link": "https://www.youtube.com/watch?v=B4nC5wPuB8M&t=180s"}, {"answer": true, "explanation": "A saint like Bhagavan sees the same thing we see, but experiences it totally differently.", "id": "en-tx-049", "kind": "true_false", "language": "en", "question": "A saint like Bhagavan sees the same world we see, but experiences it totally differently.", "source_label": "Experience of the world for a realised person", "source_link": "https://www.youtube.com/watch?v=B4nC5wPuB8M&t=240s"}, {"answer": "We are all bores, dry bores, always feeling that bore-ness — always craving for some water to come out, but it’s not coming; go one step deeper and a spring will come up — and then irrigate the whole of life.", "explanation": "Tap to reveal: the dry bores and the spring within.", "id": "en-tx-058", "kind": "flashcard", "language": "en", "question": "'Dry bores' — what does Sri Babuji say about boredom?", "source_label": "Deep dive into boredom", "source_link": "https://www.youtube.com/watch?v=3i1VpNZ6bkk&t=240s"}, {"answer": false, "explanation": "Don't act on boredom at once — stand a little and look into it; ask what is actually happening to your fulfillment.", "id": "en-tx-059", "kind": "true_false", "language": "en", "question": "Sri Babuji advises us to flee boredom at once by acting on it immediately.", "source_label": "Deep dive into boredom", "source_link": "https://www.youtube.com/watch?v=3i1VpNZ6bkk&t=180s"}, {"answer": 0, "explanation": "Left idle, we produce our own movies — we are the producer, director, actor, and scriptwriter, keeping the patterns alive for entertainment.", "id": "en-tx-060", "kind": "single_select", "language": "en", "options": ["We ourselves", "The ego's helpers", "Our memories", "The guru"], "question": "Who is the 'producer, director, actor and scriptwriter' of our inner movies?", "source_label": "Deep dive into boredom", "source_link": "https://www.youtube.com/watch?v=3i1VpNZ6bkk&t=60s"}, {"answer": "Connectedness to Baba acts like a fuse: the power is there, the fans and bulbs are there, but nothing works unless the fuse is intact.", "explanation": "Tap to reveal: fusing ourselves to Baba is the technique.", "id": "en-tx-061", "kind": "flashcard", "language": "en", "question": "'The fuse' — what does Sri Babuji say connectedness to Baba acts like?", "source_label": "How can we integrate our emotions through love?", "source_link": "https://www.youtube.com/watch?v=N2pTbzGP_mw&t=120s"}, {"answer": true, "explanation": "Traditional paths demand renouncing the mundane, creating a clash for the householder; the Sai devotee feels no clash — even pulls considered opposite to the path are integrated, fused.", "id": "en-tx-062", "kind": "true_false", "language": "en", "question": "The Sai devotee feels no clash between worldly pulls and the spiritual path — even opposite pulls are integrated and fused.", "source_label": "How can we integrate our emotions through love?", "source_link": "https://www.youtube.com/watch?v=N2pTbzGP_mw&t=60s"}, {"answer": 0, "explanation": "Have an object of love: focus all your pulls towards Baba — 'I want a good job, I want Baba also — Baba, give me a job.'", "id": "en-tx-063", "kind": "single_select", "language": "en", "options": ["Focus them all towards Baba — 'Baba, give me a job'", "Suppress them", "Renounce the job", "Hide them from Baba"], "question": "What should one do with worldly pulls like wanting a good job?", "source_label": "How can we integrate our emotions through love?", "source_link": "https://www.youtube.com/watch?v=N2pTbzGP_mw&t=0s"}, {"answer": "Sri Babuji's rejection of Vedantic answers that dissolve the suffering mind instead of giving it a solution — 'the suffering mind itself must get the solution.'", "explanation": "Tap to reveal: rejecting clever answers that kill the patient.", "id": "en-tx-064", "kind": "flashcard", "language": "en", "question": "'Operation success, patient died' — what does Sri Babuji reject with this phrase?", "source_label": "Tiruvannamalai satsang, 16 Nov 2004", "source_link": "https://www.youtube.com/watch?v=MRKz86OSU5U&t=1080s"}, {"answer": 0, "explanation": "As a boy he was drawn to Baba's photograph because Baba looked so human and tangible, unlike the strange gods and goddesses.", "id": "en-tx-065", "kind": "single_select", "language": "en", "options": ["Baba looked so human and tangible, unlike the strange gods and goddesses", "The photograph glowed", "A saint told him to", "He saw Baba in a dream"], "question": "Why was Sri Babuji drawn to Baba's photograph as a boy?", "source_label": "Tiruvannamalai satsang, 16 Nov 2004", "source_link": "https://www.youtube.com/watch?v=MRKz86OSU5U&t=840s"}, {"answer": 0, "explanation": "On meditation he gives no techniques: ignite love and meditation becomes your need — you become the author of your own million techniques.", "id": "en-tx-066", "kind": "single_select", "language": "en", "options": ["Don't ask for techniques — ignite love; meditation must become your need", "Repeat the name 108 times daily", "Sit for one hour without moving", "Follow Patanjali's sutras strictly"], "question": "What is Sri Babuji's advice on meditation technique?", "source_label": "Tiruvannamalai satsang, 16 Nov 2004", "source_link": "https://www.youtube.com/watch?v=MRKz86OSU5U&t=1740s"}, {"answer": "We are pots turned down in Baba's ocean of grace; tilting the vessel a little — the namaskar — lets grace in, and the bubbles that escape are our experiences.", "explanation": "Tap to reveal: the empty vessel in Baba's ocean of grace.", "id": "en-tx-067", "kind": "flashcard", "language": "en", "question": "'The empty vessel' — what does Sri Babuji illustrate with it?", "source_label": "Tiruvannamalai satsang, 16 Nov 2004", "source_link": "https://www.youtube.com/watch?v=MRKz86OSU5U&t=3780s"}, {"answer": true, "explanation": "Baba never differentiated between the spiritual and the worldly life — both are the search for fulfillment and happiness.", "id": "en-tx-068", "kind": "true_false", "language": "en", "question": "Sri Babuji says Baba fulfills our worldly desires first, and then the focus slowly shifts from the object of desire to the One who gives it.", "source_label": "Tiruvannamalai satsang, 16 Nov 2004", "source_link": "https://www.youtube.com/watch?v=MRKz86OSU5U&t=0s"}, {"answer": 0, "explanation": "Satsangs are the long hand, inner transformation the short hand — not always visible.", "id": "en-tx-069", "kind": "single_select", "language": "en", "options": ["Satsangs are the long hand, inner transformation the short hand — not always visible", "Time flies in satsang", "Be punctual in spiritual life", "The guru controls time"], "question": "What is the 'clock' analogy about?", "source_label": "Tiruvannamalai satsang, 16 Nov 2004", "source_link": "https://www.youtube.com/watch?v=MRKz86OSU5U&t=2760s"}, {"answer": "Drop prestige and self-respect at Baba's door; the real interview is the inside view.", "explanation": "Tap to reveal: the real interview is the inside view.", "id": "en-tx-070", "kind": "flashcard", "language": "en", "question": "'The real interview' — what does Sri Babuji say it is?", "source_label": "Tiruvannamalai satsang, 16 Nov 2004", "source_link": "https://www.youtube.com/watch?v=MRKz86OSU5U&t=3420s"}, {"answer": true, "explanation": "As long as Baba is the concrete expression of your abstract sense of fulfillment, you are already connected — the connection is spontaneous.", "id": "en-tx-071", "kind": "true_false", "language": "en", "question": "Sri Babuji says the connection to Baba is spontaneous, not something effort can produce.", "source_label": "2022 Guru Purnima, Day 2", "source_link": "https://www.youtube.com/watch?v=ShJgcI5Gt_I&t=2160s"}, {"answer": 0, "explanation": "If the connection is so fragile, let it go — and aspire for a connection so strong that even if you try to disconnect you cannot.", "id": "en-tx-072", "kind": "single_select", "language": "en", "options": ["A connection so strong that even if you try to disconnect you cannot", "More temple visits", "A stricter daily routine", "A new mantra"], "question": "What should one aspire for when feeling disconnected from Baba when away from Shirdi?", "source_label": "2022 Guru Purnima, Day 2", "source_link": "https://www.youtube.com/watch?v=ShJgcI5Gt_I&t=1980s"}, {"answer": "Real spiritual strength lies first in resisting environmental influence, and eventually in influencing the environment yourself.", "explanation": "Tap to reveal: first resist the environment's influence, then influence it.", "id": "en-tx-073", "kind": "flashcard", "language": "en", "question": "'Environmental influence' — what does Sri Babuji say real spiritual strength is?", "source_label": "2022 Guru Purnima, Day 2", "source_link": "https://www.youtube.com/watch?v=ShJgcI5Gt_I&t=2040s"}, {"answer": true, "explanation": "Those who preach formlessness came in form — Buddha had a form.", "id": "en-tx-074", "kind": "true_false", "language": "en", "question": "Sri Babuji says those who preach formlessness came in form — Buddha had a form.", "source_label": "Experiencing the formless through the form", "source_link": "https://www.youtube.com/watch?v=99VzLtxPl1g&t=0s"}, {"answer": 0, "explanation": "He could present Sai Baba as pure abstraction, the guru principle — but because of the conditions of your personality, that is not what you require.", "id": "en-tx-075", "kind": "single_select", "language": "en", "options": ["First accept the form; find the window — look through the window and see what lies beyond", "Reject all forms at once", "Worship only the formless", "Treat all forms as maya"], "question": "What is Sri Babuji's advice about the form?", "source_label": "Experiencing the formless through the form", "source_link": "https://www.youtube.com/watch?v=99VzLtxPl1g&t=63s"}, {"answer": 0, "explanation": "In Sufi tradition, when the disciple finishes, the Guru gives a token — a stick, cloth, brick — to keep always; Baba's brick was His Guru's prasad.", "id": "en-tx-081", "kind": "single_select", "language": "en", "options": ["It was His Guru's prasad", "It was His pillow", "It marked His seat", "He found it in Dwarkamai"], "question": "Why did Baba always keep a brick with Him?", "source_label": "Why did Baba keep a brick?", "source_link": "https://www.youtube.com/watch?v=zDkVlRrcEFc&t=120s"}, {"answer": [0, 1, 2], "explanation": "A stick, cloth or brick — tokens the disciple keeps always; keeping the Guru's article is part of the tradition.", "id": "en-tx-082", "kind": "multi_select", "language": "en", "options": ["A stick", "A cloth", "A brick", "A crown"], "question": "Which tokens does Sri Babuji say a Guru gives the disciple on completion in Sufi tradition? (Choose all that apply)", "source_label": "Why did Baba keep a brick?", "source_link": "https://www.youtube.com/watch?v=zDkVlRrcEFc&t=60s"}, {"answer": true, "explanation": "What Baba is — the state which operates everything, which is in all creatures — that is His real nature.", "id": "en-tx-083", "kind": "true_false", "language": "en", "question": "Sri Babuji says Baba's real nature is the state which operates everything, which is in all creatures.", "source_label": "Sai Baba's all-pervading nature", "source_link": "https://www.youtube.com/watch?v=e5NEb1svhUY&t=0s"}, {"answer": 0, "explanation": "The same nature manifests itself in the form of Baba, trying to make us aware of that inner nature; He has taken different forms.", "id": "en-tx-084", "kind": "single_select", "language": "en", "options": ["The same inner nature manifesting in form, to make us aware of that inner nature", "An illusion to be discarded", "A historical accident", "A mere symbol"], "question": "What is Baba's form, according to Sri Babuji?", "source_label": "Sai Baba's all-pervading nature", "source_link": "https://www.youtube.com/watch?v=e5NEb1svhUY&t=0s"}, {"answer": "Baba works like a surgeon — He must operate, and under anesthesia we are unaware; we resist because it goes against our will (our ego).", "explanation": "Tap to reveal: the surgeon analogy for Baba's ways.", "id": "en-tx-085", "kind": "flashcard", "language": "en", "question": "'The surgeon' — how does Sri Babuji say Baba works with us?", "source_label": "Baba's ways of working with us", "source_link": "https://www.youtube.com/watch?v=WVctPUgOGNs&t=0s"}, {"answer": [0, 1, 2], "explanation": "Baba works like a surgeon; disappointment comes from undue expectation; His ways are inscrutable.", "id": "en-tx-086", "kind": "multi_select", "language": "en", "options": ["Baba works like a surgeon — we resist under anesthesia, unaware", "Disappointment comes from undue expectation", "His ways are inscrutable — even disappointment He uses for our transformation", "Baba never lets a devotee feel disappointment"], "question": "Which of these does Sri Babuji teach about Baba's ways of working with us? (Choose all that apply)", "source_label": "Baba's ways of working with us", "source_link": "https://www.youtube.com/watch?v=WVctPUgOGNs&t=60s"}, {"answer": "five", "explanation": "His words: 'If you seek ninety percent and He has given five, take the five — He loves you even though you deserve nothing, and that is the grace.'", "id": "en-tx-087", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words: 'If you seek ninety percent and He has given five, take the ___.'", "source_label": "Sense of Gratitude", "source_link": "https://www.youtube.com/watch?v=njdD83qa-98&t=60s"}, {"answer": 0, "explanation": "Complaining in the very spirit of grace turns the whole thing into a business — as if, because you read namaskar to Baba once, He were obligated to you.", "id": "en-tx-088", "kind": "single_select", "language": "en", "options": ["Complaining in the spirit of grace — as if reading namaskar once obligated Him", "Giving dakshina", "Attending satsangs", "Asking for boons"], "question": "What turns the spiritual life into a business, according to Sri Babuji?", "source_label": "Sense of Gratitude", "source_link": "https://www.youtube.com/watch?v=njdD83qa-98&t=120s"}, {"answer": "Three men of the priestly, ministerial and royal castes, reduced by misfortune to beggars — we receive so much from Baba, yet gratitude is missing.", "explanation": "Tap to reveal: the story that exposes our ungratefulness.", "id": "en-tx-089", "kind": "flashcard", "language": "en", "question": "'The three beggars' — what is the story Sri Babuji tells about gratitude?", "source_label": "Sense of Gratitude", "source_link": "https://www.youtube.com/watch?v=njdD83qa-98&t=240s"}, {"answer": 0, "explanation": "Not merely sitting with closed eyes — liveliness is in how you react with the world when eyes are open.", "id": "en-tx-096", "kind": "single_select", "language": "en", "options": ["How you react with the world when eyes are open — not merely sitting with closed eyes", "Longer meditation sittings", "More japa repetitions", "Reading more scriptures"], "question": "What makes sadhana lively?", "source_label": "How can our sadhana be lively?", "source_link": "https://www.youtube.com/watch?v=Y17Wp9-3C0Q&t=0s"}, {"answer": true, "explanation": "Make a diary each day: what took me away from my path? How much space has Baba taken in my 24 hours?", "id": "en-tx-097", "kind": "true_false", "language": "en", "question": "Sri Babuji advises keeping a daily diary: what took you away from your path, and how much space Baba took in your 24 hours.", "source_label": "How can our sadhana be lively?", "source_link": "https://www.youtube.com/watch?v=Y17Wp9-3C0Q&t=120s"}, {"answer": 0, "explanation": "Baba's words: to inherit His state one must become really worthy — and the first step is not bringing disgrace to our father by fighting over petty things.", "id": "en-tx-102", "kind": "single_select", "language": "en", "options": ["Don't bring disgrace to our father by fighting among yourselves over petty things", "Attend satsang every day", "Give more dakshina", "Fast every Thursday"], "question": "What is the first step to becoming worthy children of Baba?", "source_label": "How to become worthy children of Baba?", "source_link": "https://www.youtube.com/watch?v=27aJ_i1p1Sg&t=70s"}, {"answer": [0, 1, 2], "explanation": "Jealousies, envy, power mongering, money, deception — the petty things that make even ordinary people seem better than quarreling devotees.", "id": "en-tx-103", "kind": "multi_select", "language": "en", "options": ["Jealousies", "Envy", "Power mongering and money", "Long meditation sittings"], "question": "What petty things does Sri Babuji say devotees fight over, bringing disgrace to our father? (Choose all that apply)", "source_label": "How to become worthy children of Baba?", "source_link": "https://www.youtube.com/watch?v=27aJ_i1p1Sg&t=161s"}, {"answer": "Whatever comes from the Guru's mouth is mantra — not the word but the carrier of spiritual power.", "explanation": "Tap to reveal: mantra as the carrier of spiritual power.", "id": "en-tx-104", "kind": "flashcard", "language": "en", "question": "'Whatever comes from the Guru's mouth is mantra' — what does Sri Babuji mean?", "source_label": "How to escape prarabdha?", "source_link": "https://www.youtube.com/watch?v=14wszfJM_gU&t=120s"}, {"answer": true, "explanation": "'I found a Guru, I follow him — who cares about the path'; serving the Guru's instruction itself is grace.", "id": "en-tx-105", "kind": "true_false", "language": "en", "question": "Sri Babuji says to follow the Guru like a blind man follows: 'I found a Guru, I follow him — who cares about the path.'", "source_label": "How to escape prarabdha?", "source_link": "https://www.youtube.com/watch?v=14wszfJM_gU&t=180s"}, {"answer": [1, 2, 0], "explanation": "1 → know why you are here, why you have come; 2 → don't let it be diluted or diverted by situations; 3 → take a sample survey of how you spent the day.", "id": "en-tx-106", "kind": "matching", "language": "en", "options": ["Take a sample survey of how you spent the day", "Know why you are here, why you have come", "Don't let your purpose be diluted or diverted by situations"], "question": "Match each of the three points to its meaning: 1. Have a goal 2. Guard the awareness of purpose 3. Do things that keep up the focus", "source_label": "Remember These Three Points", "source_link": "https://www.youtube.com/watch?v=bMZBdwH8plE&t=0s"}, {"answer": 0, "explanation": "'Come to Arunachala for Baba, for Guruji — how many minutes in the 24 hours were you actually focused on that?'", "id": "en-tx-107", "kind": "single_select", "language": "en", "options": ["How many minutes in the 24 hours were you actually focused on that", "How many bhajans you sang", "How early you woke up", "How much you donated"], "question": "What is the test Sri Babuji gives for keeping focus?", "source_label": "Remember These Three Points", "source_link": "https://www.youtube.com/watch?v=bMZBdwH8plE&t=142s"}, {"answer": false, "explanation": "No — that is where seeking truly begins: seeking doesn't stop, it takes another dimension — no longer seeking to get, but seeking to experience to the full.", "id": "en-tx-108", "kind": "true_false", "language": "en", "question": "Sri Babuji says the experience of fulfillment with an open heart is the end of seeking.", "source_label": "The End Of Seeking?", "source_link": "https://www.youtube.com/watch?v=lwYhF029Z0E&t=0s"}, {"answer": "The job-seeker analogy: reaching the bus station you sit happily as if you had arrived — but the bus still must carry you to Hyderabad; seeking becomes happy, fulfilled seeking.", "explanation": "Tap to reveal: the Hyderabad bus analogy.", "id": "en-tx-109", "kind": "flashcard", "language": "en", "question": "'The Hyderabad bus' — what does Sri Babuji illustrate with it?", "source_label": "The End Of Seeking?", "source_link": "https://www.youtube.com/watch?v=lwYhF029Z0E&t=60s"}, {"answer": "The songwriter feels unworthy to take prasad from Baba's hands — 'I am a broom'; yet 'I collect the dust of the devotees; this is my job.'", "explanation": "Tap to reveal: the broom analogy of humility.", "id": "en-tx-110", "kind": "flashcard", "language": "en", "question": "'The broom' — what does the aarti songwriter mean by it?", "source_label": "The Two Arati Songs We Sing", "source_link": "https://www.youtube.com/watch?v=t5l2_XfOx3Q&t=38s"}, {"answer": true, "explanation": "A Muslim devotee wrote them in Muslim idiom out of reverence — 'so confident Baba is a Muslim' — and words like 'Nazar' show his deep feeling.", "id": "en-tx-111", "kind": "true_false", "language": "en", "question": "The aarti songwriter chose Islamic/Urdu vocabulary like 'Nazar' out of reverence, confident that Baba is a Muslim too.", "source_label": "The Two Arati Songs We Sing", "source_link": "https://www.youtube.com/watch?v=t5l2_XfOx3Q&t=98s"}, {"answer": 0, "explanation": "A blank mind is never the real need — Baba caters to basic human needs, which never change; what we experience is fulfillment, and that is love.", "id": "en-tx-112", "kind": "single_select", "language": "en", "options": ["A blank mind is never the real need — Baba caters to basic human needs; fulfillment is love", "Seek the blank mind", "Blankness is the highest samadhi", "Empty the mind every day"], "question": "What does Sri Babuji say about spiritual blankness?", "source_label": "Shirdi satsang, 17 Jan 1998 (telecast)", "source_link": "https://www.youtube.com/watch?v=CE2FjRB5Zeg&t=2340s"}, {"answer": true, "explanation": "Bhagavan (Ramana) meant the real I — the Atma beyond the limited personality, the false ego.", "id": "en-tx-113", "kind": "true_false", "language": "en", "question": "On 'Who am I': Bhagavan meant the real I — the Atma beyond the limited personality, the false ego.", "source_label": "Shirdi satsang, 17 Jan 1998 (telecast)", "source_link": "https://www.youtube.com/watch?v=CE2FjRB5Zeg&t=2940s"}, {"answer": "Even after 20 years, Baba is still a mystery — a sense of security and happiness draws the mind to Him, yet He remains an enigma.", "explanation": "Tap to reveal: the Sadguru as familiar stranger.", "id": "en-tx-114", "kind": "flashcard", "language": "en", "question": "'Strangely familiar, familiarly strange' — what draws the mind to the Sadguru?", "source_label": "Sadguru — A Familiar Stranger", "source_link": "https://www.youtube.com/watch?v=afeHX8Eyu8o&t=60s"}, {"answer": true, "explanation": "Don't fight doubt — it is insecurity felt in absence; trust follows love, never the reverse.", "id": "en-tx-115", "kind": "true_false", "language": "en", "question": "Sri Babuji says doubt is only insecurity, and trust follows love — never the reverse.", "source_label": "Tiruvannamalai satsang, 16 Apr 1998", "source_link": "https://www.youtube.com/watch?v=7rB1W5RwchA&t=600s"}, {"answer": "Grace is power given with knowledge and love when all effort fails — not earned, not charity.", "explanation": "Tap to reveal: grace as power with love and knowledge.", "id": "en-tx-116", "kind": "flashcard", "language": "en", "question": "'Grace' — how does Sri Babuji define it?", "source_label": "Tiruvannamalai satsang, 16 Apr 1998", "source_link": "https://www.youtube.com/watch?v=7rB1W5RwchA&t=2220s"}, {"answer": "The experience of love is like fire, and the ego acts as the firewood — in the beginning it supports the fire, but the stronger fire of love eventually burns it completely.", "explanation": "Tap to reveal: the ego as firewood in the fire of love.", "id": "en-tx-117", "kind": "flashcard", "language": "en", "question": "'The ego as firewood' — what does Sri Babuji say about ego in the longing for love?", "source_label": "Udi — Carrier of Love", "source_link": "https://www.youtube.com/watch?v=w7fAi7Oflm4&t=0s"}, {"answer": 0, "explanation": "Udi carries His love because it is the remnant of His love — at once a symbol, a carrier, and a reminder.", "id": "en-tx-118", "kind": "single_select", "language": "en", "options": ["The remnant of Baba's love — at once a symbol, a carrier, and a reminder", "Sacred ash meant only for healing", "A ritual requirement", "A souvenir from Shirdi"], "question": "What is udi, according to Sri Babuji?", "source_label": "Udi — Carrier of Love", "source_link": "https://www.youtube.com/watch?v=w7fAi7Oflm4&t=112s"}, {"answer": [0, 1, 2], "explanation": "He obeyed every instruction — going here and there, doing this and that, including his marriage — not from obligation but simply because he loved him.", "id": "en-tx-119", "kind": "multi_select", "language": "en", "options": ["Going here and there as asked", "Doing this and that as asked", "His marriage", "Arguing when he disagreed"], "question": "Sri Babuji recalls obeying his own guru's instructions out of love. Which of these did he obey? (Choose all that apply)", "source_label": "In love, likes and dislikes wither away", "source_link": "https://www.youtube.com/watch?v=8AdqvU9ssGo&t=0s"}, {"answer": 0, "explanation": "Mingled with the attraction comes a sense of security — no warranty given, nothing received, yet the certainty 'he will take care.'", "id": "en-tx-120", "kind": "single_select", "language": "en", "options": ["A sense of security — no warranty given, yet the certainty 'he will take care'", "Fear of punishment", "Desire for miracles", "Social approval"], "question": "What mingles with the attraction to the Sadguru?", "source_label": "All beings seek fulfilment", "source_link": "https://www.youtube.com/watch?v=X3ifaeUCbuA&t=180s"}, {"answer": "With a Sadguru, no practices and no techniques are needed — everything becomes a mantra; love is the cargo.", "explanation": "Tap to reveal: love is the cargo, mantra the vehicle.", "id": "en-tx-121", "kind": "flashcard", "language": "en", "question": "'Love is the cargo' — what does Sri Babuji say about practice with a Sadguru?", "source_label": "Sri Sai Baba Satsang, 29 Aug 2026", "source_link": "https://www.youtube.com/watch?v=CIkexsHFyOY&t=3780s"}, {"answer": "life", "explanation": "His words: 'You love Baba because you love life. He is life.'", "id": "en-tx-122", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words: 'You love Baba because you love life. He is ___.'", "source_label": "Sri Sai Baba Satsang, 4 Sep 2026 (evening)", "source_link": "https://www.youtube.com/watch?v=dFqjPVsek04&t=1860s"}, {"answer": "Do not be dry flowers: keep the freshness of blooming flowers offered at Baba's feet — seniority must not kill freshness; every time is the first time.", "explanation": "Tap to reveal: keep the freshness of blooming flowers.", "id": "en-tx-123", "kind": "flashcard", "language": "en", "question": "'Dry flowers' — what does Sri Babuji warn devotees about?", "source_label": "Sri Sai Baba Satsang, 4 Sep 2026 (evening)", "source_link": "https://www.youtube.com/watch?v=dFqjPVsek04&t=4140s"}, {"answer": 0, "explanation": "'If a book helps you read it, if not throw it away' — focus on your real need, not on scriptural commentary.", "id": "en-tx-124", "kind": "single_select", "language": "en", "options": ["If a book helps you read it, if not throw it away", "Read every scripture cover to cover", "Avoid all books", "Memorize the Satcharitra"], "question": "What does Sri Babuji say about reading books?", "source_label": "Sri Sai Baba Satsang, 4 Sep 2026 (morning)", "source_link": "https://www.youtube.com/watch?v=u8_W2NhScHg&t=6660s"}, {"answer": "Memory is awareness — be on the stove like milk on the stove; and don't live like the buffalo, ruminating anxieties.", "explanation": "Tap to reveal: memory as awareness.", "id": "en-tx-125", "kind": "flashcard", "language": "en", "question": "'The milk on the stove' — what does Sri Babuji teach about memory?", "source_label": "Sri Sai Baba Satsang, 12 Sep 2026", "source_link": "https://www.youtube.com/watch?v=C_y0NBqU9bs&t=2700s"}, {"answer": "speak", "explanation": "His words on Baba after 1918: even the physical body was a small tomb, and now it is a bigger tomb that can reach more people — 'my tomb will speak.'", "id": "en-tx-126", "kind": "quote_completion", "language": "en", "question": "Complete Sri Babuji's words: 'My tomb will ___.'", "source_label": "Sri Sai Baba Satsang, 13 Sep 2026", "source_link": "https://www.youtube.com/watch?v=xIUnpgziU54&t=5280s"}, {"answer": "The lover of mystery never asks for the solution at the end of the movie — find your own burning question instead of imitating Buddha or Maharshi.", "explanation": "Tap to reveal: the lover of mystery.", "id": "en-tx-127", "kind": "flashcard", "language": "en", "question": "'The lover of mystery' — what does Sri Babuji say about finding one's own path?", "source_label": "Sri Sai Baba Satsang, 29 Aug 2026", "source_link": "https://www.youtube.com/watch?v=CIkexsHFyOY&t=5820s"}, {"answer": 0, "explanation": "The speaker asks 'in whose presence if at all those karma theories are right' and answers that 'they are all these theories become powerless' — in the Sadguru's presence.", "id": "en-tx-128", "kind": "single_select", "language": "en", "options": ["In the Sadguru's presence", "In the presence of a temple priest", "In the presence of an astrologer", "In the presence of a scholar"], "question": "In the \"Sadguru Sannidhi\" talk, in whose presence do all the karma theories become powerless?", "source_label": "Sadguru Sannidhi (2022)", "source_link": "https://www.youtube.com/watch?v=AuMe0EGbx-U&t=438s"}, {"answer": "act", "explanation": "His words: 'Karma doesn't apply, it doesn't act — it becomes powerless.'", "id": "en-tx-129", "kind": "quote_completion", "language": "en", "question": "Complete the words spoken in the \"Sadguru Sannidhi\" talk: \"Karma doesn't apply, it doesn't ___.\"", "source_label": "Sadguru Sannidhi (2022)", "source_link": "https://www.youtube.com/watch?v=AuMe0EGbx-U&t=430s"}, {"answer": "It is predestined that I will get this experience through Baba; it is also predetermined — that is why I am getting this.", "explanation": "Tap to reveal: experiences received through Baba are predestined and predetermined.", "id": "en-tx-130", "kind": "flashcard", "language": "en", "question": "In the \"Sadguru Sannidhi\" talk, what is said about the experience one gets through Baba?", "source_label": "Sadguru Sannidhi (2022)", "source_link": "https://www.youtube.com/watch?v=AuMe0EGbx-U&t=486s"}, {"answer": "monkey tricks", "explanation": "His words: 'And there is no end to the monkey tricks of the Mind.'", "id": "en-tx-131", "kind": "quote_completion", "language": "en", "question": "Complete the words spoken in the \"Sadguru Sannidhi\" talk: \"And there is no end to the ___ of the Mind.\"", "source_label": "Sadguru Sannidhi (2022)", "source_link": "https://www.youtube.com/watch?v=AuMe0EGbx-U&t=493s"}, {"answer": true, "explanation": "His words: 'Everything Changes, Everything Changes.'", "id": "en-tx-132", "kind": "true_false", "language": "en", "question": "In the \"Sadguru Sannidhi\" talk, the speaker says 'Everything Changes.'", "source_label": "Sadguru Sannidhi (2022)", "source_link": "https://www.youtube.com/watch?v=AuMe0EGbx-U&t=527s"}, {"answer": 2, "explanation": "1918లో బాబా మహాసమాధి చెందారు; 1988 విజయదశమికి డెబ్భయి ఏళ్లు నిండాయి. గ్రంథంలో 'మొన్న (1988) విజయదశమికి డెబ్భయి ఏళ్ళయింది' అని ఉంది.", "id": "te-bk-001", "kind": "single_select", "language": "te", "options": ["ఐదు దశాబ్దాలు (50 ఏళ్లు)", "ఆరు దశాబ్దాలు (60 ఏళ్లు)", "డెబ్భయి ఏళ్లు (70 ఏళ్లు)", "ఎనభై ఏళ్లు (80 ఏళ్లు)"], "question": "1988వ సంవత్సరానికి శ్రీసాయిబాబా మహాసమాధి చెంది ఎన్ని సంవత్సరాలు అయింది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=9"}, {"answer": "అతిశయోక్తి కాదేమో!", "explanation": "గ్రంథం మొదటి అధ్యాయంలోని వాక్యం: 'శ్రీసాయిబాబా చిత్రపటం లేని ఇల్లు, సాయిమందిరం లేని పట్టణం, దక్షిణభారతంలో — ముఖ్యంగా ఆంధ్రదేశంలో— ఈనాడు బహు అరుదంటే అతిశయోక్తి కాదేమో!'", "id": "te-bk-002", "kind": "quote_completion", "language": "te", "question": "శ్రీబాబుజీ వాక్యాన్ని పూర్తి చేయండి: 'శ్రీసాయిబాబా చిత్రపటం లేని ఇల్లు, సాయిమందిరం లేని పట్టణం, దక్షిణభారతంలో — ముఖ్యంగా ఆంధ్రదేశంలో — ఈనాడు బహు అరుదంటే ___'", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=9"}, {"answer": true, "explanation": "రాముడు, కృష్ణుడు వంటి మహాపురుషులు ఆరాధ్యదైవాలుగా స్థిరపడడానికి ఎంతో కాలం పట్టింది; కానీ బాబా మహాసమాధి చెందిన అనతికాలంలోనే భారతీయ జీవనంలో భాగమయ్యారు.", "id": "te-bk-003", "kind": "true_false", "language": "te", "question": "శ్రీసాయిబాబా మహాసమాధి చెందిన అనతికాలంలోనే భారతీయ ఆధ్యాత్మిక జీవనంలో ఒక భాగమయ్యారు.", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=9"}, {"answer": 1, "explanation": "రెండవ అధ్యాయం 'సాయిచూపే తొలిమెట్టు!' బాబా ఉపదేశాలలో అత్యంత ప్రాచుర్యం పొందిన 'సూక్తి'గా 'Look to me and I look to you!'ను పేర్కొంటుంది.", "id": "te-bk-004", "kind": "single_select", "language": "te", "options": ["'సబ్ కా మాలిక్ ఏక్'", "'Look to me and I look to you!'", "'శ్రద్ధా సబూరీ'", "'అల్లా మాలిక్'"], "question": "శ్రీసాయిబాబా అత్యంత ప్రాచుర్యం పొందిన ఉపదేశాలలో 'సూక్తి'గా పేర్కొనబడినది ఏది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 9", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=17"}, {"answer": true, "explanation": "'and' (సముచ్చయం) స్థానంలో 'if' (షరతు) చేర్చడం వల్ల 'అస్పష్టంగా తొంగిచూస్తున్న షరతు' అపార్థాలకు దారితీసిందని గ్రంథం వివరిస్తుంది.", "id": "te-bk-005", "kind": "true_false", "language": "te", "question": "'Look to me and I look to you!' అనే వాక్యంలోని 'and'ను 'if'గా మార్చడం వల్ల మూలార్థంలోని షరతులేని హామీ షరతుతో కూడినదిగా మారిపోయింది.", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 9", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=17"}, {"answer": 1, "explanation": "మూలానువాదాన్ని అనుసరించి 'నాపై నీ దృష్టి నిలుపు; నీపై నా దృష్టి నిలుపుతాను' అని తెలుగులోకి అనువదించాలని గ్రంథం పేర్కొంటుంది.", "id": "te-bk-006", "kind": "single_select", "language": "te", "options": ["'నన్ను చూడు, నిన్ను చూస్తాను'", "'నాపై నీ దృష్టి నిలుపు; నీపై నా దృష్టి నిలుపుతాను'", "'నావైపు చూస్తే నీవైపు చూస్తాను'", "'నన్ను నమ్ము, నిన్ను కాపాడతాను'"], "question": "'Look to me and I look to you!'కు గ్రంథం సూచించిన సరైన తెలుగు అనువాదం ఏది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 9", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=17"}, {"answer": "నేనందరిని సమానదృష్టితో చూస్తాను!", "explanation": "గ్రంథంలోని బాబా వాక్యం: 'నా అనుగ్రహం లేక ఆకుకైనా కదలదు. నేనందరిని సమానదృష్టితో చూస్తాను!' ('I look equally on all! Not a leaf moves except by my grace.')", "id": "te-bk-007", "kind": "quote_completion", "language": "te", "question": "బాబా మాటను పూర్తి చేయండి: 'నా అనుగ్రహం లేక ఆకుకైనా కదలదు. ___'", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 10", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=18"}, {"answer": 1, "explanation": "బాబానే వివరించారు: 'ఋణానుబంధం'ని! ఆ ఋణానుబంధానికైనా మొదట ఏదో కారణం ఉండాలి కదా — వెనుక ఎన్నో జన్మల బంధమే కారణం.", "id": "te-bk-008", "kind": "single_select", "language": "te", "options": ["వారి పూర్వజన్మ పుణ్యం వల్ల", "'ఋణానుబంధం' వల్ల", "వారి ధనం వల్ల", "వారి విద్య వల్ల"], "question": "బాబా దృష్టి అందరిపైనా సమానంగా ప్రసరిస్తుంటే కొందరే ఆయన భక్తులుగా ఎందుకు ఎంపికవుతారు? గ్రంథం చెప్పిన కారణం ఏది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 12", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=20"}, {"answer": "నాకు అప్పజెప్పబడిన ప్రతి పైసకు నేనే అల్లాకు లెక్కచెప్పుకోవాలి!", "explanation": "ఋణానుబంధాన్ని వివరిస్తూ బాబా అన్న మాట: 'వెనుక ఎన్నోజన్మలలో మీతో వున్నాను. ఇక రాబోయే జన్మలెన్నిటిలోనూ మీతో ఉండగలను. మనం మళ్ళీ మళ్ళీ కలుసుకొంటాము. నాకు అప్పజెప్పబడిన ప్రతి పైసకు నేనే అల్లాకు లెక్కచెప్పుకోవాలి!'", "id": "te-bk-009", "kind": "quote_completion", "language": "te", "question": "బాబా మాటను పూర్తి చేయండి: 'వెనుక ఎన్నోజన్మలలో మీతో వున్నాను. ఇక రాబోయే జన్మలెన్నిటిలోనూ మీతో ఉండగలను. మనం మళ్ళీ మళ్ళీ కలుసుకొంటాము. ___'", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 12", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=20"}, {"answer": "వెనుక ఎన్నో జన్మల నుండి బాబాతో కలిగిన బంధం; ఈ బంధం వల్లనే కొందరు ఆయన భక్తులుగా ఎంపికవుతారు. బాబా: 'తనకు అప్పజెప్పబడ్డ పైసలని' వారిని ఉద్ధరిస్తారు.", "explanation": "మూడవ అధ్యాయం 'బాబాతో ఋణానుబంధం పెంచుకోవడమెలా?'లోని కీలక భావన.", "id": "te-bk-010", "kind": "flashcard", "language": "te", "question": "ఋణానుబంధం", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 12", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=20"}, {"answer": "చేయవలసినదంతా నేను చేసి, మిమ్ములను చివరికంటా గమ్యం చేరుస్తాను!", "explanation": "నాలుగవ అధ్యాయంలోని శ్రీసాయి ఉపదేశం: 'గురువుకు పగ్గాలు అప్పగించి నిశ్చింతగా ఊరక కూర్చుంటే చాలు! చేయవలసినదంతా నేను చేసి, మిమ్ములను చివరికంటా గమ్యం చేరుస్తాను!'", "id": "te-bk-011", "kind": "quote_completion", "language": "te", "question": "శ్రీసాయి ఉపదేశాన్ని పూర్తి చేయండి: 'గురువుకు పగ్గాలు అప్పగించి నిశ్చింతగా ఊరక కూర్చుంటే చాలు! ___'", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 25", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=33"}, {"answer": 1, "explanation": "'ఊరకుండుట దెలియ ఉత్తమయోగంబు! మానసంబు కలిమి మధ్యమంబు' అని వేమన చెప్పారని గ్రంథం ఉదహరిస్తుంది.", "id": "te-bk-012", "kind": "single_select", "language": "te", "options": ["కఠిన తపస్సు చేయడం", "ఊరకుండుట దెలియడం", "నిరంతర జపం చేయడం", "తీర్థయాత్రలు చేయడం"], "question": "వేమన యోగీంద్రుని మాట ప్రకారం ఉత్తమ యోగం ఏది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 25", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=33"}, {"answer": true, "explanation": "ఐదవ అధ్యాయం: 'శ్రీసాయిబాబా మనకందించినది మధ్యేమార్గం. ఇటు మితిమీరిన భోగలాలసతను, అటు అలవిమాలిన హఠయోగాన్ని బాబా ఆమోదించలేదు.'", "id": "te-bk-013", "kind": "true_false", "language": "te", "question": "శ్రీసాయిబాబా మితిమీరిన భోగలాలసతను, అటు అలవిమాలిన ఉపవాసాలను ఆమోదించలేదు; ఆయన బోధించింది మధ్యేమార్గం.", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 31", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=39"}, {"answer": 1, "explanation": "ఉప=దగ్గరగా/సమీపంలో, వాసము=ఉండటం. మనస్సును విషయాలతో నింపక ఖాళీగా ఉంచుకొని, అందులో మన ఉపాసనాదైవాన్ని ప్రతిష్ఠించుకొని ఆయనకు అంతరంగంలో దగ్గరపడడమే ఉపవాసం.", "id": "te-bk-014", "kind": "single_select", "language": "te", "options": ["నిరాహారంగా ఉండటం", "దగ్గరగా (భగవంతుని చెంత) ఉండటం", "నిద్రను జయించడం", "మౌనం పాటించడం"], "question": "'ఉపవాస' అనే పదానికి గ్రంథం చెప్పిన అసలైన అర్థం ఏది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 32", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=40"}, {"answer": "ఆకలితో కడుపు కాలుతున్నవాడికి ఏమీ తోచకపోవడం సహజమే! ఆకలి కడుపుతో పూజాధ్యానాలు చేస్తే దేహంలోని ప్రాణచలనం అస్తవ్యస్తమై శోష, నిద్రతో కూడిన తమస్సు మనస్సును ఆవరిస్తుంది.", "explanation": "ఉపవాస అధ్యాయంలో ఆకలితో సాధన సాధ్యం కాదని చెప్పే సంస్కృత సూక్తి.", "id": "te-bk-015", "kind": "flashcard", "language": "te", "question": "బుభుక్షితం న ప్రతిభాతి కించిత్", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 32", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=40"}, {"answer": false, "explanation": "గ్రంథం: 'అటు ఆధ్యాత్మికలక్ష్యాన్ని సాధింపబూనిన యోగసాధకునికి, ఇటు లౌకిక లాభాన్ని పొందగోరే కార్యసాధకునికి - ఇరువురికి - బద్ధకపు నిద్ర ఓ బద్ధశత్రువు!'", "id": "te-bk-016", "kind": "true_false", "language": "te", "question": "బద్ధకపు నిద్ర యోగసాధకునికి మాత్రమే శత్రువు; లౌకిక లాభాన్ని పొందగోరే కార్యసాధకునికి కాదు.", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 51", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=59"}, {"answer": 1, "explanation": "'బొత్తిగా ఆహారం లేకుండా కొన్ని వారాలపాటైనా మనగలమేమో గానీ, అస్సలు నిద్రపోకుండా కొన్ని రోజులు కూడా ఉండటం అసాధ్యం!'", "id": "te-bk-017", "kind": "single_select", "language": "te", "options": ["నీరు", "నిద్ర", "గాలి", "వెలుతురు"], "question": "ఆహారం లేకుండా కొన్ని వారాలపాటు మనగలమేమో గానీ, దేని లేకుండా కొన్ని రోజులు కూడా ఉండటం అసాధ్యం?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 51", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=59"}, {"answer": [0, 1, 2, 3], "explanation": "గ్రంథం: 'కొందరిది మొద్దునిద్ర; మరికొందరిది మాగన్ను నిద్ర; కొంతమందిది కలతనిద్ర; ఇంకొంతమందిది సరిగా 'పట్టిని' నిద్ర!'", "id": "te-bk-018", "kind": "multi_select", "language": "te", "options": ["మొద్దునిద్ర", "మాగన్ను నిద్ర", "కలతనిద్ర", "సరిగా 'పట్టిని' నిద్ర"], "question": "నిద్ర గురించి గ్రంథం పేర్కొన్న రకాలు ఏవి? (సరైనవన్నీ ఎంచుకోండి)", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 51", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=59"}, {"answer": 1, "explanation": "మంత్ర భావం: 'తొడిమ నుండి విడివడిన దోసపండు వలె మృత్యువు నుండి బయటపడడము గాక!' మృత్యుంజయ మంత్ర పునశ్చరణ చేత మృత్యువు దరిచేరదనే విశ్వాసం అపార్థం అని గ్రంథం స్పష్టం చేస్తుంది.", "id": "te-bk-019", "kind": "single_select", "language": "te", "options": ["మరణం లేకుండా చేసుకోవడం", "తొడిమ నుండి విడివడిన దోసపండు వలె మృత్యువు నుండి బయటపడడం", "దీర్ఘాయుష్షు పొందడం", "స్వర్గానికి వెళ్లడం"], "question": "మృత్యుంజయ మంత్రం యొక్క భావం ఏమిటి?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 63", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=71"}, {"answer": "ఊర్వారుక మివ బంధనాత్ మృత్యోర్ముక్షీయ మామృతాత్", "explanation": "గ్రంథంలో ఇవ్వబడిన మంత్రం: 'త్ర్యంబకం యజామహే సుగంధిం పుష్టి వర్ధనమ్ ఊర్వారుక మివ బంధనాత్ మృత్యోర్ముక్షీయ మామృతాత్' — ఈ మంత్రాన్ని ఊది ధారణచేసేప్పుడు (విధిగా) పఠిస్తారు.", "id": "te-bk-020", "kind": "quote_completion", "language": "te", "question": "మృత్యుంజయ మంత్రాన్ని పూర్తి చేయండి: 'త్ర్యంబకం యజామహే సుగంధిం పుష్టి వర్ధనమ్ ___'", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 63", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=71"}, {"answer": "వారసలు నన్ను చూడనట్లే!", "explanation": "శిరిడీ యాత్ర అధ్యాయంలో బాబా మాట: 'సాయి అంటే ఈ మూడున్నర మూరల దేహం మాత్రమే కాదు. బాబా శిరిడీలోనే ఉన్నాడని యెవరైనా అనుకొంటే, వారసలు నన్ను చూడనట్లే!'", "id": "te-bk-021", "kind": "quote_completion", "language": "te", "question": "బాబా మాటను పూర్తి చేయండి: 'సాయి అంటే ఈ మూడున్నర మూరల దేహం మాత్రమే కాదు. బాబా శిరిడీలోనే ఉన్నాడని యెవరైనా అనుకొంటే, ___'", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 71", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=79"}, {"answer": true, "explanation": "శ్రద్ధాభక్తులతో తరచు శిరిడీ సందర్శించే సాయిభక్తులు ఎదుర్కొనే 'హఠబోధ'గా గ్రంథం దీన్ని పేర్కొంటుంది; తీర్థాలను, మహాత్ముల సమాధి స్థానాలను సాధకులు విధిగా దర్శించాలని సంప్రదాయం నిర్దేశిస్తుందని కూడా చెబుతుంది.", "id": "te-bk-022", "kind": "true_false", "language": "te", "question": "'సాయి సర్వాంతర్యామి, శిరిడీ వెళ్ళాల్సిన పనిలేదు' అనే వాదాన్ని గ్రంథం 'హఠబోధ'గా పేర్కొంటుంది.", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 71", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=79"}, {"answer": 1, "explanation": "పరిపూర్ణమైన శ్రీసాయి సంప్రదాయం దత్త సంప్రదాయంలో 'ఒక భాగం' మాత్రమేనని, సాయిభక్తులకు సాయిచరిత్ర కంటే శ్రీగురుచరిత్ర పారాయణే ప్రధానమనే ప్రచారం సరికాదని గ్రంథం వివరిస్తుంది.", "id": "te-bk-023", "kind": "single_select", "language": "te", "options": ["గురుచరిత్ర పారాయణ సాయి భక్తులకు తప్పనిసరి", "సాయి సంప్రదాయం వేరు; సాయి భక్తులకు సాయి చరిత్రే ప్రధానం", "గురుచరిత్రను సాయి భక్తులు ముట్టుకోకూడదు", "రెండూ సమానమే, ఏదైనా పారాయణ చేయవచ్చు"], "question": "సాయి భక్తులకు శ్రీగురుచరిత్ర పారాయణ విధాయకమా అనే ప్రశ్నకు గ్రంథం ఇచ్చిన సమాధానం సారాంశం ఏది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 89", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=97"}, {"answer": 2, "explanation": "'శిరిడీ సందర్శించి అక్కడ శ్రీసాయిబాబా సమాధిమందిరంలో నిత్యం జరిగే నాలుగు ఆరతులలో పాల్గొన్న సాయిభక్తులకు...' అని గ్రంథం పేర్కొంటుంది.", "id": "te-bk-024", "kind": "single_select", "language": "te", "options": ["రెండు", "మూడు", "నాలుగు", "ఐదు"], "question": "శిరిడీ సమాధి మందిరంలో నిత్యం జరిగే ఆరతులు ఎన్ని?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 133", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=141"}, {"answer": true, "explanation": "'ఎందరో సాయిభక్తులకు శిరిడీ ఆరతులు 'వేదమంత్రాలవంటివి'' అని గ్రంథం పేర్కొంటుంది.", "id": "te-bk-025", "kind": "true_false", "language": "te", "question": "కొందరు సాయిభక్తులు శిరిడీ ఆరతులను వేదమంత్రాలవలె భావిస్తారు.", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 133", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=141"}, {"answer": ["సాయియోగంలో ఉపవాస నియమం", "బాబాతో ఋణానుబంధం పెంచుకోవడమెలా?", "'ఊర'కుండుట తెలుపు ఉత్తమయోగం!", "సాయియోగంలో ఉపవాస నియమం"], "explanation": "మధ్యేమార్గం (అధ్యాయం 5), ఋణానుబంధం (అధ్యాయం 3), ఊరకుండుట (అధ్యాయం 4), ఉపవాస నిర్వచనం (అధ్యాయం 5).", "id": "te-bk-026", "kind": "matching", "language": "te", "options": ["మధ్యేమార్గం", "ఋణానుబంధం", "ఊరకుండుటే ఉత్తమ యోగం", "ఉపవాసం అంటే దగ్గరగా ఉండటం"], "question": "క్రింది భావాలను వాటి అధ్యాయాలతో జతపరచండి.", "source_label": "Sai Bhakti Sadhana Rahasyam, వివిధ అధ్యాయాలు", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf"}, {"answer": 1, "explanation": "'ఏ కాలానికి అనుగుణమైన ధర్మాన్ని ఆ కాలంలో పాటించడం వివేకం; 'కాలధర్మం' చెందిన ఆచారాలను పట్టుకొని వ్రేలాడడం అవివేకం!' అనే సందర్భంలో బాబా 'జైసాదేశ్ వైసావేశ్' అన్నారు.", "id": "te-bk-027", "kind": "single_select", "language": "te", "options": ["దేశభక్తిని పెంపొందించడానికి", "ఏ కాలానికి అనుగుణమైన ధర్మాన్ని ఆ కాలంలో పాటించడం వివేకం అని చెప్పడానికి", "వేషధారణ ముఖ్యమని చెప్పడానికి", "యాత్రలు చేయమని చెప్పడానికి"], "question": "'జైసాదేశ్ వైసావేశ్' అని శ్రీసాయిబాబా ఎందుకు అన్నారు?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 31", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=39"}, {"answer": "'నాపై నీ దృష్టి నిలుపు' — బాబాపై దృష్టి నిలపడం సాధనలో తొలి మెట్టు; 'మనసు ఎరుకే మలిమెట్టు!'", "explanation": "రెండవ అధ్యాయం శీర్షిక: 'సాయిచూపే తొలిమెట్టు - మనసు ఎరుకే మలిమెట్టు!'", "id": "te-bk-028", "kind": "flashcard", "language": "te", "question": "సాయిచూపే తొలిమెట్టు", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 9", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=17"}, {"answer": true, "explanation": "'తనకు అప్పజెప్పబడ్డ పైసలని' బాబా తన సహజ నిగూఢరీతిలో పిలిచారని గ్రంథం పేర్కొంటుంది.", "id": "te-bk-029", "kind": "true_false", "language": "te", "question": "శ్రీసాయిబాబా తమ భక్తులను 'తనకు అప్పజెప్పబడ్డ పైసలని' పిలిచారు.", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 12", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=20"}, {"answer": 0, "explanation": "'అలా అప్పగించాలంటే, మన మనసు యొక్క పగ్గాలు ముందు మన చేతిలోకి రావాలి కదా? అలా మన మనసు యొక్క పగ్గాలు మనకు స్వాధీనం కావడానికి బాబా బోధించిన అనేక ఉపాయాలలో...'", "id": "te-bk-030", "kind": "single_select", "language": "te", "options": ["మనస్సు యొక్క పగ్గాలు ముందు మన చేతిలోకి రావాలి", "గురువును విడిచిపెట్టాలి", "ధనాన్ని త్యాగం చేయాలి", "ఇల్లు విడిచిపెట్టాలి"], "question": "మనస్సనే రథం యొక్క పగ్గాలు పూర్తిగా బాబాకు అప్పగించాలంటే ముందు ఏమి జరగాలి?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 25", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=33"}, {"answer": [1, 2], "explanation": "ఉప=దగ్గరగా, వాసము=ఉండటం. ఆకలి కడుపుతో పూజాధ్యానాలు చేస్తే తమస్సు మనస్సును ఆవరిస్తుంది; 'బుభుక్షితం న ప్రతిభాతి కించిత్'.", "id": "te-bk-031", "kind": "multi_select", "language": "te", "options": ["ఉపవాసం అంటే నిరాహారంగా ఉండటం", "ఉపవాసం అంటే భగవంతునికి దగ్గరగా ఉండటం", "ఆకలితో సాధన చేయడం తమస్సుకు దారితీస్తుంది", "ఉపవాసం అంటే మౌనంగా ఉండటం"], "question": "ఉపవాసం గురించి గ్రంథం చెప్పిన సరైన అంశాలు ఏవి?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 32", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=40"}, {"answer": 1, "explanation": "'నిద్రయొక్క అసలు తత్త్వాన్ని ఆకళింపు చేసుకోవడం — ఆవులిస్తూ నిద్రపోయినంత — తేలికకాదు! ఎందుకంటే, నిద్రలోని 'అనుభవం' మాత్రమే మెలుకువ ఎరుకకు అందుతుంది; నిద్రలోని 'నిజం' నిద్ర మెల్కొనగానే మరుగుపడుతుంది.'", "id": "te-bk-032", "kind": "single_select", "language": "te", "options": ["నిద్రలో అనుభవం లేదని చెప్పడానికి", "నిద్రయొక్క అసలు తత్త్వాన్ని ఆకళింపు చేసుకోవడం — నిద్రపోయినంత మాత్రాన తేలిక కాదని చెప్పడానికి", "నిద్ర మంచిది కాదని చెప్పడానికి", "కలలు నిజం కాదని చెప్పడానికి"], "question": "నిద్రలోని 'అనుభవం' మాత్రమే మెలుకువ ఎరుకకు అందుతుందని, నిద్రలోని 'నిజం' నిద్ర మెల్కొనగానే మరుగుపడుతుందని గ్రంథం ఎందుకు చెబుతుంది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 51", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=59"}, {"answer": false, "explanation": "గ్రంథం ఈ విశ్వాసాన్ని 'మహామోజు' (భ్రమ)గా పేర్కొంటుంది; 'అకాల మృత్యుహరణమ్' అనే అర్థంలో మహర్షులు 'మృత్యువు' 'మృత్యుంజయము' అనే పదాలు వాడారని, జపించి మరణం లేకుండా చేసుకొన్నవారు ఎవరైనా ఉన్నారా అని ప్రశ్నిస్తుంది.", "id": "te-bk-033", "kind": "true_false", "language": "te", "question": "మృత్యుంజయ మంత్ర పునశ్చరణ చేత మృత్యువు దరిచేరదని నమ్మడం సరైన విశ్వాసమే అని గ్రంథం సమర్థిస్తుంది.", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 63", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=71"}, {"answer": 1, "explanation": "'శిరిడీయాత్ర చేయని సాయిభక్తులకు కూడా ఆ ఆరతుల ధ్వనులు వింటుంటే వారి హృదయాలలో అవి ఒక చిత్రమైన అనుభూతిని కలిగిస్తాయి.'", "id": "te-bk-034", "kind": "single_select", "language": "te", "options": ["ఆరతులు కేవలం శిరిడీలో మాత్రమే జరుగుతాయి", "శిరిడీ యాత్ర చేయని భక్తులు కూడా ఆరతుల ధ్వనులు వింటుంటే హృదయాలలో చిత్రమైన అనుభూతిని పొందుతారు", "ఆరతులు సంస్కృతంలో మాత్రమే ఉంటాయి", "ఆరతులకు భక్తులు హాజరు కావాల్సిన అవసరం లేదు"], "question": "శిరిడీ ఆరతుల గురించి గ్రంథం ప్రస్తావించిన విశేషం ఏది?", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 133", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=141"}, {"answer": "నిత్యం నాలుగు ఆరతులు; కొందరి దృష్టిలో వేదమంత్రాలవంటివి; శిరిడీ ఆరతులు జరగని సాయిమందిరాలు అసలు సాయిమందిరాలే కావని మరికొందరి విశ్వాసం.", "explanation": "22వ అధ్యాయం 'సాయిభక్తి సంప్రదాయంలో శిరిడీ ఆరతులు' నుండి.", "id": "te-bk-035", "kind": "flashcard", "language": "te", "question": "సాయిభక్తి సంప్రదాయంలో శిరిడీ ఆరతులు", "source_label": "Sai Bhakti Sadhana Rahasyam, p. 133", "source_link": "https://downloads.saibaba.com/publications/pdfs/sbsr.pdf#page=141"}, {"answer": 1, "explanation": "మొదటి అనుభవం: జస్టిస్ ఎం.బి. రేగే, బి.ఎ., ఎల్‌ఎల్‌.బి., వయస్సు సుమారు 50 సంవత్సరాలు, సౌరాష్ట్ర, ఇండోర్.", "id": "te-bk-036", "kind": "single_select", "language": "te", "options": ["ప్రొఫెసర్ జి.జి. నార్కే", "జస్టిస్ ఎం.బి. రేగే", "దాసగణు మహారాజ్", "రావు బహదూర్ దుమాల్"], "question": "'శ్రీసాయిబాబాను నేను సృష్టి, స్థితి, లయకారకునిగా భావిస్తాను' అని చెప్పిన భక్తుడు ఎవరు?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=17"}, {"answer": true, "explanation": "'వారు మహాసమాధి (1918) చెందక ముందు కూడా నేను అలాగే భావించేవాడిని. ఇప్పటికీ నాలో అదే భావముంది. వారు ఎక్కడికీ వెళ్ళిపోలేదు. ఇప్పటికీ, ఎప్పటికీ మనతోనే ఉన్నారు, ఉంటారు.'", "id": "te-bk-037", "kind": "true_false", "language": "te", "question": "జస్టిస్ రేగే బాబా మహాసమాధికి ముందు కూడా ఆయన్ను సృష్టి స్థితి లయకారకునిగా భావించారు; మహాసమాధి తర్వాత కూడా బాబా మనతోనే ఉన్నారని నమ్మారు.", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=17"}, {"answer": 0, "explanation": "రేగే: 'మీరు నిగూఢంగా మాట్లాడే మాటలు నేను అర్థం చేసుకోలేకపోతున్నాను. మీరు నాకేదైనా చెప్పదలిస్తే నాకర్థమయ్యేట్లు చెప్పండి!' అన్నారు. అప్పటి నుండి బాబా నాతో నీతికథల రూపంలో కాకుండా స్పష్టంగా మాట్లాడేవారు.", "id": "te-bk-038", "kind": "single_select", "language": "te", "options": ["నీతికథల రూపంలో కాకుండా స్పష్టంగా మాట్లాడేవారు", "మౌనంగా ఉండేవారు", "సంస్కృతంలో మాత్రమే మాట్లాడేవారు", "ఇతర భక్తుల ద్వారా చెప్పేవారు"], "question": "జస్టిస్ రేగే బాబాను 'నిగూఢంగా కాకుండా అర్థమయ్యేట్లు చెప్పండి' అని కోరిన తర్వాత బాబా ఎలా మాట్లాడేవారు?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=17"}, {"answer": "జిన్నేపాయా ఉన్నేఛుపాయా!", "explanation": "ప్రొఫెసర్ నార్కే ఉదహరించిన కబీర్ వాక్యం: 'జిన్నేపాయా ఉన్నేఛుపాయా!' (ఎవరు దేన్నైతే పొందారో దానిని గుప్తంగా ఉంచుతారు).", "id": "te-bk-039", "kind": "quote_completion", "language": "te", "question": "ఆధ్యాత్మిక అనుభవాలను వెల్లడి చేయలేమని చెప్పడానికి ప్రొఫెసర్ నార్కే ఉదహరించిన కబీర్ వాక్యాన్ని పూర్తి చేయండి: '___'", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 17", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=33"}, {"answer": 1, "explanation": "'శ్రీసాయిబాబాను నేను నిత్యం ఇంట్లో పూజించే దేవతల మధ్య ఉంచాను. శ్రీసాయిబాబా భగవంతుడే కాని ఒక సాధారణ సత్పురుషుడు మాత్రం కాదు.'", "id": "te-bk-040", "kind": "single_select", "language": "te", "options": ["ఒక సాధారణ సత్పురుషునిగా", "భగవంతునిగా (సాధారణ సత్పురుషుడు మాత్రం కాదు)", "ఒక గొప్ప పండితునిగా", "ఒక సంఘసంస్కర్తగా"], "question": "ప్రొఫెసర్ జి.జి. నార్కే శ్రీసాయిబాబాను ఎలా భావించారు?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 17", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=33"}, {"answer": true, "explanation": "'మా మామగారైన బూటీ, నా భార్య, మా అమ్మ' శ్రీసాయిబాబా పట్ల నాకున్న విశ్వాసాన్ని పెంపొందించడానికి తోడ్పడ్డారు.", "id": "te-bk-041", "kind": "true_false", "language": "te", "question": "ప్రొఫెసర్ నార్కే మామగారు, భార్య, తల్లి ఆయనకు సాయిబాబా పట్ల విశ్వాసం పెంపొందించడానికి తోడ్పడ్డారు.", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 17", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=33"}, {"answer": 0, "explanation": "దాసగణు మహారాజ్ ఉర్ఫ్ గణపతిరావు దత్తాత్రేయ సహస్రబుద్ధే, కీర్తనాకారుడు, వయస్సు సుమారు 78 సంవత్సరాలు, బ్రాహ్మణుడు, నాందేడు (నిజాం రాష్ట్రం).", "id": "te-bk-042", "kind": "single_select", "language": "te", "options": ["గణపతిరావు దత్తాత్రేయ సహస్రబుద్ధే", "గోపాలరావు", "నానాసాహెబ్ చందోర్కర్", "మహల్సాపతి"], "question": "దాసగణు మహారాజ్ అసలు పేరు ఏమిటి?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": [0, 1, 2], "explanation": "భక్తిసారామృతంలో 26, 65, 66, 67 అధ్యాయాలు (1925), భక్తిలీలామృతంలో 31 (1906), 32, 33 అధ్యాయాలు, సంతకథామృతంలో 57వ అధ్యాయములో బాబాను గురించి పేర్కొని ఉన్నారు.", "id": "te-bk-043", "kind": "multi_select", "language": "te", "options": ["భక్తిసారామృతం", "భక్తిలీలామృతం", "సంతకథామృతం", "జ్ఞానేశ్వరి"], "question": "దాసగణు మహారాజ్ బాబాను గురించి ఏ గ్రంథాలలో పేర్కొన్నారు?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": true, "explanation": "'నేను బాబాను అరుదుగా దర్శిస్తూ ఉండేవాడిని. శిరిడీలో ఉన్నప్పుడు బాబా నన్ను మసీదులో ఎక్కువ సమయం ఉండనిచ్చేవారు కాదు. విఠల్ మందిరానికి పంపేవారు.'", "id": "te-bk-044", "kind": "true_false", "language": "te", "question": "దాసగణు మహారాజ్ శిరిడీలో ఉన్నప్పుడు బాబా ఆయన్ను మసీదులో ఎక్కువ సమయం ఉండనిచ్చేవారు కాదు; విఠల్ మందిరానికి పంపేవారు.", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": 1, "explanation": "'పోలీసు శాఖలో హవల్దారుగా పని చేసినందున నాకు ఈ పరిశోధన సులభంగా సాగింది.'", "id": "te-bk-045", "kind": "single_select", "language": "te", "options": ["ఉపాధ్యాయునిగా", "పోలీసు శాఖలో హవల్దారుగా", "వైద్యునిగా", "న్యాయవాదిగా"], "question": "దాసగణు మహారాజ్ బాబా గురించి పరిశోధన చేయడానికి ఏ వృత్తి తోడ్పడింది?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": 0, "explanation": "'అతను నన్ను బాబా దగ్గరకు తీసుకువెళ్ళాడు. బాబా నన్ను చూసిన వెంటనే నా భవిష్యత్తు చదివి నా కాలక్షేపపు కార్యక్రమాలను, ఉద్యోగాన్ని మాన్పించి, ఆధ్యాత్మిక పథంలో నన్ను నడిపించాలని సంకల్పించారు.'", "id": "te-bk-046", "kind": "single_select", "language": "te", "options": ["నానాసాహెబ్ చందోర్కర్", "మహల్సాపతి", "శ్యామా", "బూటీ"], "question": "దాసగణు మహారాజ్ను బాబా దగ్గరకు తీసుకువెళ్ళింది ఎవరు?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": "ఇతనికి తమాషాలన్నా, ఉద్యోగమన్నా అమిత మక్కువ. వాటినుండిని ఇతడు విడివిపెట్టాలి!", "explanation": "బాబా నానాసాహెబ్తో అన్న మాట: 'ఇతనికి తమాషాలన్నా, ఉద్యోగమన్నా అమిత మక్కువ. వాటినుండిని ఇతడు విడివిపెట్టాలి!' అదే విషయం దాసగణుతో కూడా చెప్పారు.", "id": "te-bk-047", "kind": "quote_completion", "language": "te", "question": "దాసగణు గురించి బాబా నానాసాహెబ్తో అన్న మాటను పూర్తి చేయండి: 'ఇతనికి తమాషాలన్నా, ఉద్యోగమన్నా అమిత మక్కువ. ___'", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": 1, "explanation": "చోటూబాయి ప్రధాన్ అనుభవం 321(1): పిల్లలందరికీ పొంగు (మీజిల్స్) పోసింది. డాక్టరు పరిస్థితి ప్రమాదకరంగా ఉందని చెప్పాడు. బాబా కనిపించి 'ఉదయం ఆరు, ఆరున్నర గంటలకు వాడికి బాగా ఆహారం పెట్టు' అన్నారు. బిడ్డ కోలుకున్నాడు.", "id": "te-bk-048", "kind": "single_select", "language": "te", "options": ["టైఫాయిడ్", "పొంగు (మీజిల్స్)", "మలేరియా", "కలరా"], "question": "శ్రీమతి చోటూబాయి ప్రధాన్ పిల్లవానికి వచ్చిన జబ్బు ఏది?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 139", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=155"}, {"answer": "ఉదయం ఆరు, ఆరున్నర గంటలకు వాడికి బాగా ఆహారం పెట్టు", "explanation": "బాబా చోటూబాయికి కనిపించి అన్న మాట: 'ఎందుకమ్మా దుఃఖిస్తావు? పిల్లవాడు బాగానే ఉన్నాడు. ఉదయం ఆరు, ఆరున్నర గంటలకు వాడికి బాగా ఆహారం పెట్టు'.", "id": "te-bk-049", "kind": "quote_completion", "language": "te", "question": "జబ్బుపడిన పిల్లవాని గురించి బాబా చోటూబాయితో అన్న మాటను పూర్తి చేయండి: 'ఎందుకమ్మా దుఃఖిస్తావు? పిల్లవాడు బాగానే ఉన్నాడు. ___'", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 139", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=155"}, {"answer": true, "explanation": "323(2): ఒకరాత్రి 11 గం॥ల సమయంలో బాబా నా కలలో కన్పించి, 'నిద్రపోతున్నావా? లే! పిల్లవాడికి మూర్ఛ వస్తుంది' అన్నారు. రాత్రి 2 గంటలప్పుడు మూర్ఛ లక్షణాలు కనిపించాయి; సిద్ధంగా ఉంచిన మందు ఇవ్వగా అర్ధగంటలో తగ్గిపోయాయి.", "id": "te-bk-050", "kind": "true_false", "language": "te", "question": "బాబా కలలో ముందుగానే హెచ్చరించడం వల్ల చోటూబాయి పిల్లవాని మూర్ఛకు సిద్ధంగా ఉండి కాపాడుకోగలిగారు.", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 139", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=155"}, {"answer": "చూసావా నానా! ఈ తల్లి నా రెండు పాదాలను కోసి తీసుకువెళుతోంది", "explanation": "324(3): వెండి పాదుకలను బాబా పాదాలపై పెట్టి పూజించమని బాబా చెప్పారు; తర్వాత వాటిని తిరిగి ఇస్తూ నానాసాహెబ్తో 'చూసావా నానా! ఈ తల్లి నా రెండు పాదాలను కోసి తీసుకువెళుతోంది (నానాసాహెబ్ మాఝే పాయ్ పహా కాపూన్ నేలే)' అన్నారు.", "id": "te-bk-051", "kind": "quote_completion", "language": "te", "question": "వెండి పాదుకలను తిరిగి ఇస్తూ బాబా నానాసాహెబ్తో అన్న మాటను పూర్తి చేయండి: '___'", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 139", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=155"}, {"answer": 2, "explanation": "జస్టిస్ రేగే అనుభవం చిన్నికృష్ణ రాజాసాహెబ్ బహద్దూర్ అనే పేరుతో వెల్లడించారు (ఫుట్నోట్).", "id": "te-bk-052", "kind": "single_select", "language": "te", "options": ["జస్టిస్ రేగే స్వయంగా", "చిన్నికృష్ణ రాజాసాహెబ్ బహద్దూర్", "బి.వి. నరసింహస్వామి", "దాసగణు మహారాజ్"], "question": "జస్టిస్ రేగే తమ అనుభవాలను ఏ పేరుతో వెల్లడించారు?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=17"}, {"answer": ["జస్టిస్ ఎం.బి. రేగే", "ప్రొఫెసర్ జి.జి. నార్కే", "దాసగణు మహారాజ్", "శ్రీమతి చోటూబాయి ప్రధాన్"], "explanation": "వీరి అనుభవాలు వరుసగా పేజీలు 1, 17, 165, 139లలో ఉన్నాయి.", "id": "te-bk-053", "kind": "matching", "language": "te", "options": ["బాబాను సృష్టి స్థితి లయకారకునిగా భావించినవారు", "కబీర్ 'జిన్నేపాయా ఉన్నేఛుపాయా'ను ఉదహరించినవారు", "భక్తిసారామృతం రచించినవారు", "కలలో బాబా హెచ్చరికతో బిడ్డను కాపాడుకున్నవారు"], "question": "భక్తులను వారి విశేషాలతో జతపరచండి.", "source_label": "Sri Saibhaktha Anubhava Samhita, వివిధ పేజీలు", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf"}, {"answer": "నిగూఢంగా మాట్లాడే మాటలు అర్థం చేసుకోలేకపోతున్నాను; అర్థమయ్యేట్లు చెప్పమని కోరిన భక్తుడు. అప్పటి నుండి బాబా నీతికథల రూపంలో కాకుండా స్పష్టంగా మాట్లాడేవారు.", "explanation": "జస్టిస్ ఎం.బి. రేగే అనుభవం (పు. 1) నుండి.", "id": "te-bk-054", "kind": "flashcard", "language": "te", "question": "జస్టిస్ రేగే — బాబాతో స్పష్టమైన మాటలు", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=17"}, {"answer": true, "explanation": "'శ్రీసాయిబాబా భగవంతుడే కాని ఒక సాధారణ సత్పురుషుడు మాత్రం కాదు. వారి కళ్ళల్లో ప్రకాశించే దివ్య తేజస్సు వారొక గొప్ప సత్పురుషుడని తెలియజేస్తుంది.'", "id": "te-bk-055", "kind": "true_false", "language": "te", "question": "ప్రొఫెసర్ నార్కే దృష్టిలో శ్రీసాయిబాబా కేవలం ఒక సాధారణ సత్పురుషుడు మాత్రమే.", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 17", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=33"}, {"answer": 1, "explanation": "'బాబా తమ గతానికి సంబంధించిన కొన్ని వాస్తవాలను స్వయంగా వెల్లడించారు. అవి చాలా స్వల్పమే.'", "id": "te-bk-056", "kind": "single_select", "language": "te", "options": ["దాసగణు ఊహించి రాశారు", "బాబా స్వయంగా వెల్లడించారు", "ఇతర భక్తులు చెప్పారు", "శ్యామా డైరీ నుండి సేకరించారు"], "question": "బాబా గతానికి సంబంధించిన వాస్తవాలు దాసగణుకు ఎలా తెలిశాయి?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": [0, 1], "explanation": "దాసగణు: 'నాకు సాహిత్యం పట్ల, నాటకకళ పట్ల మక్కువ ఉండేది. అందువలన నేను వీథి నాటకాలలో (తమాషాలలో) పాల్గొనేవాడిని.' లావణీ మొదలైన ఛందస్సులను ఉపయోగించి ఆశువుగా పద్యాలు చెప్పగలిగేవారు.", "id": "te-bk-057", "kind": "multi_select", "language": "te", "options": ["వీథి నాటకాలలో (తమాషాలలో) పాల్గొనేవారు", "లావణీ ఛందస్సులో ఆశువుగా పద్యాలు చెప్పగలిగేవారు", "శాస్త్రీయ సంగీత విద్వాంసుడు", "చిత్రకారుడు"], "question": "దాసగణు మహారాజ్ సాహిత్య, కళా ఆసక్తుల గురించి సరైనవి ఏవి?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": false, "explanation": "బాబా దాసగణును చూసిన వెంటనే ఆయన భవిష్యత్తు చదివి, కాలక్షేపపు కార్యక్రమాలను, ఉద్యోగాన్ని మాన్పించి ఆధ్యాత్మిక పథంలో నడిపించాలని సంకల్పించారు.", "id": "te-bk-058", "kind": "true_false", "language": "te", "question": "బాబా దాసగణును తమాషాలు, ఉద్యోగం కొనసాగించమని ఆశీర్వదించారు.", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": "బాబా తమ పాదాలను ముందుకు చాపి, పాదుకలను తమ పాదాలపై పెట్టి పూజించుకోమని చెప్పారు.", "explanation": "324(3) అనుభవం: కలలో బాబా పాదాలకు పసుపు కుంకుమ పెట్టమన్నారు; చందోర్కర్ సలహాతో వెండి పాదుకలను శిరిడీకి తీసుకువెళ్ళి బాబా ముందుంచగా, బాబా తమ పాదాలను ముందుకు చాపి వాటిని తమ పాదాలపై పెట్టి పూజించుకోమని చెప్పారు.", "id": "te-bk-059", "kind": "flashcard", "language": "te", "question": "చోటూబాయి — వెండి పాదుకల పూజ", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 139", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=155"}, {"answer": 1, "explanation": "ప్రొఫెసర్ నార్కే: 'అందువల్ల అనుభవాల గురించి చెప్పడానికి ప్రయత్నించినప్పుడు నా గొంతు సహజంగానే మూగబోతుంది.' అయినా సాయిబాబాను గురించి, వారి తత్త్వాన్ని గురించి జగమెరిగిన సత్యాలను చెప్పడానికి సంకోచించలేదు.", "id": "te-bk-060", "kind": "single_select", "language": "te", "options": ["అనుభవాలన్నీ అబద్ధమని", "అనుభవాలు గుప్తంగా ఉంచాలని, కానీ జగమెరిగిన సత్యాలు చెప్పవచ్చని", "బాబా గురించి ఎవరికీ చెప్పవద్దని", "కేవలం పండితులకే చెప్పాలని"], "question": "అనుభవాలను వెల్లడించడం గురించి ప్రొఫెసర్ నార్కే వైఖరి ఏమిటి?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 17", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=33"}, {"answer": true, "explanation": "రేగే: 'వారు ఎక్కడికీ వెళ్ళిపోలేదు. ఇప్పటికీ, ఎప్పటికీ మనతోనే ఉన్నారు, ఉంటారు.'", "id": "te-bk-061", "kind": "true_false", "language": "te", "question": "జస్టిస్ రేగే నమ్మకం ప్రకారం శ్రీసాయిబాబా ఎక్కడికీ వెళ్ళిపోలేదు; ఎప్పటికీ మనతోనే ఉంటారు.", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=17"}, {"answer": 0, "explanation": "దాసగణు: 'నేను బాబాను గురించి వ్రాసేముందు, వారి గురించి కొన్ని పరిశోధనలు జరిపాను. కొన్ని వాస్తవాలు నా స్వీయ పరిశీలనతో వ్రాసినవి.'", "id": "te-bk-062", "kind": "single_select", "language": "te", "options": ["స్వీయ పరిశీలనతో", "ఇతరులు చెప్పినవి విని", "కలలో కని", "ఊహించి"], "question": "దాసగణు బాబా గురించి వ్రాసిన కొన్ని వాస్తవాలు ఎలా సేకరించారు?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 165", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=181"}, {"answer": "మూర్ఛ వస్తుంది — రాత్రి 11 గంటలకు కలలో 'నిద్రపోతున్నావా? లే! పిల్లవాడికి మూర్ఛ వస్తుంది' అని బాబా హెచ్చరించారు; తల్లి వేడినీళ్ళు, నిప్పు, ఉడుకులోన్ మొదలైనవన్నీ సిద్ధంగా ఉంచారు.", "explanation": "323(2) అనుభవం నుండి.", "id": "te-bk-063", "kind": "flashcard", "language": "te", "question": "చోటూబాయి — కలలో హెచ్చరిక", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 139", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=155"}, {"answer": [0, 2], "explanation": "రేగేకు వేదాంతం, తత్త్వశాస్త్రాల పట్ల ఆసక్తి లేదు ('వేదాంత, తత్త్వశాస్త్రాల పట్ల నాకు ఆసక్తి లేదు'); బాబా కొన్ని సందర్భాలలో దృష్టాంతాలు, నీతికథలతో నిగూఢంగా మాట్లాడేవారు.", "id": "te-bk-064", "kind": "multi_select", "language": "te", "options": ["వేదాంతం, తత్త్వశాస్త్రాల పట్ల ఆసక్తి లేదు", "సంస్కృత పండితుడు", "బాబా దృష్టాంతాలు, నీతికథలతో నిగూఢంగా మాట్లాడేవారు", "బాబాను ఎప్పుడూ చూడలేదు"], "question": "జస్టిస్ రేగే గురించి సరైన అంశాలు ఏవి?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 1", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=17"}, {"answer": 1, "explanation": "నార్కే: 'వారి చర్యలు, మహిమలు అత్యద్భుతమైనవి. ఇక నేను ఆధ్యాత్మికత వైపు ఎలా మళ్ళానో, బాబాతో నాకెలా పరిచయం ఏర్పడిందో వరుసగా వివరిస్తాను.'", "id": "te-bk-065", "kind": "single_select", "language": "te", "options": ["సామాన్యమైనవి", "అత్యద్భుతమైనవి", "అర్థం కానివి", "భయంకరమైనవి"], "question": "ప్రొఫెసర్ నార్కే దృష్టిలో బాబా చర్యలు, మహిమలు ఎలాంటివి?", "source_label": "Sri Saibhaktha Anubhava Samhita, p. 17", "source_link": "https://downloads.saibaba.com/publications/pdfs/Anubhava_Samhita.pdf#page=33"}, {"answer": 1, "explanation": "'ప్రేమే సూత్రం' (Love is the Principle) పరిచయంలో: 'సాయిబాబా మన కోరికలను విడిచిపెట్టమని అడగరు. బదులుగా ఆయన తన ప్రభావాన్ని చూపి, కోరికలు ఉపరితలానికి వచ్చి తీరేలా పరిస్థితులను సృష్టిస్తారు — అణచివేయడానికి లేదా విచ్చలవిడిగా తీర్చుకోవడానికి కాదు.'", "id": "te-bk-066", "kind": "single_select", "language": "te", "options": ["కోరికలను నెరవేర్చడం", "వ్యక్తి రూపాంతరం చెందడం", "అద్భుతాలు చూడటం", "ధనం సంపాదించడం"], "question": "శ్రీబాబుజీ బోధ ప్రకారం కోరిక తీరడం వెనుక అసలు ఉద్దేశం ఏమిటి?", "source_label": "Sai Deevena (Bound to Love), 'Love is the Principle'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": "హృదయంలో రూపాంతరం", "explanation": "శ్రీబాబుజీ: 'ఒక అనుభవం తర్వాత హృదయంలో రూపాంతరం రావాలి. ఆ అనుభవం మన వ్యక్తిత్వంలో, దృక్పథంలో, భయాలలో మార్పు తెచ్చిందో లేదో చూడాలి.'", "id": "te-bk-067", "kind": "quote_completion", "language": "te", "question": "శ్రీబాబుజీ మాటను పూర్తి చేయండి: 'ఒక అనుభవం తర్వాత ___ రావాలి.'", "source_label": "Sai Deevena (Bound to Love), 'Love is the Principle'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": true, "explanation": "శ్రీసాయిబాబా: 'నా భక్తులు అడిగినది ఇస్తాను, నేను ఇవ్వాలనుకున్నది అడిగేవరకు.' (I give my devotees what they ask for, until they ask for what I want to give them.)", "id": "te-bk-068", "kind": "true_false", "language": "te", "question": "'నా భక్తులు అడిగినది ఇస్తాను, నేను ఇవ్వాలనుకున్నది అడిగేవరకు' అని శ్రీసాయిబాబా అన్నారు.", "source_label": "Sai Deevena (Bound to Love), పరిచయం", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 1, "explanation": "శ్రీబాబుజీ: 'సాయిబాబా ముందు కూర్చున్నప్పుడు నీలో ఏదో కదులుతుంది, ప్రేమ ప్రవహిస్తుంది. చాలా సంతోషంగా, ఉత్సాహంగా ఉంటావు. చింతలు, సమస్యలన్నీ మరచిపోతావు. భద్రతా భావం కలుగుతుంది. నీలో ఆ ప్రేమను, పరిపూర్ణతను రేకెత్తించినవాడే నీ సద్గురువు.'", "id": "te-bk-069", "kind": "single_select", "language": "te", "options": ["మంత్రోపదేశం ఇచ్చినవాడు", "నీలో ప్రేమను, పరిపూర్ణతను రేకెత్తించినవాడు", "దీక్ష ఇచ్చినవాడు", "గుడి కట్టించినవాడు"], "question": "శ్రీబాబుజీ నిర్వచనం ప్రకారం సద్గురువు ఎవరు?", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": "నా గురువు ప్రతిరోజూ వచ్చినా ఇలాగే ఆహ్వానిస్తాను!", "explanation": "భక్తుడు 'ఆచార్య భరద్వాజ ప్రతిసారీ ఇంత ఆడంబరంగా ఆహ్వానించాలా?' అని అడిగితే గురూజీ నొక్కి చెప్పారు: 'కొండయ్యా, ఇది గుర్తుంచుకో, ఎప్పుడూ మరవకు! నా గురువు ప్రతివారం కాకుండా ప్రతిరోజూ వచ్చినా నేను ఇలాగే ఆహ్వానిస్తాను!'", "id": "te-bk-070", "kind": "quote_completion", "language": "te", "question": "తమ గురువు ఆచార్య భరద్వాజను ప్రతిసారీ ఆడంబరంగా ఆహ్వానించడం గురించి శ్రీబాబుజీ అన్న మాటను పూర్తి చేయండి: 'కొండయ్యా, ఇది గుర్తుంచుకో! నా గురువు ప్రతిరోజూ వచ్చినా ___'", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": true, "explanation": "శ్రీబాబుజీ: 'అన్ని ఆచారాలు ప్రేమ వ్యక్తీకరణగానే మొదలయ్యాయి, ఏదో భావాన్ని వ్యక్తం చేసే చర్యగా. దాన్ని తిరిగి చేయడం ద్వారా అదే భావాన్ని పొందాలని చూస్తాం.'", "id": "te-bk-071", "kind": "true_false", "language": "te", "question": "శ్రీబాబుజీ బోధ ప్రకారం అన్ని ఆచారాలు ప్రేమ వ్యక్తీకరణగానే మొదలయ్యాయి.", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 1, "explanation": "భక్తుడు: 'అంటే చర్య భావాన్ని రేకెత్తిస్తుందా?' శ్రీబాబుజీ: 'అవును. ఆచారం యొక్క అర్థం అందులోనే ఉంది.'", "id": "te-bk-072", "kind": "single_select", "language": "te", "options": ["ఆచారాలు అర్థరహితం", "చర్య భావాన్ని రేకెత్తిస్తుంది — అందులోనే ఆచారం యొక్క అర్థం ఉంది", "భావం లేకుండా చర్య చేయాలి", "ఆచారాలు కేవలం సంప్రదాయం కోసం"], "question": "ఆచారాల గురించి శ్రీబాబుజీ చెప్పిన ముఖ్యాంశం ఏది?", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": false, "explanation": "శ్రీబాబుజీ: 'అది కేవలం యాంత్రికమైతే అందులో అర్థం లేదు. కానీ కొన్నిసార్లు తిరిగి చేస్తూ ఉండడం వల్ల అదే భావం మళ్ళీ రేకెత్తుతుంది.'", "id": "te-bk-073", "kind": "true_false", "language": "te", "question": "ఆచారం యాంత్రికమైనా అందులో పూర్తి అర్థం ఉంటుందని శ్రీబాబుజీ చెప్పారు.", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 2, "explanation": "కౌసానీ ప్రయాణంలో బస్సు చక్రం నట్లు అన్నీ ఊడిపోయాయి; లోతైన లోయ పక్కన బస్సు పడిపోకుండా ఆగింది. డ్రైవర్ 'మేము అక్కడ పడి చనిపోయి ఉండాల్సింది. గురూజీ చాలా గొప్పవారు. మమ్మల్నందరినీ కాపాడారు!' అని పాదాలపై పడ్డాడు.", "id": "te-bk-074", "kind": "single_select", "language": "te", "options": ["ఇంజన్ ఆగిపోయింది", "చక్రం నట్లు అన్నీ ఊడిపోయాయి", "బ్రేకులు పనిచేయలేదు", "డ్రైవర్ నిద్రపోయాడు"], "question": "కౌసానీ ప్రయాణంలో బస్సుకు ఏమి జరిగింది?", "source_label": "Sai Deevena (Bound to Love), 'A journey of wonders'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 1, "explanation": "సిమ్లాలో మంచు లేదు; భక్తుడు 'ఇక్కడ మంచు ఎందుకు కురవడం లేదు?' అని అడిగితే గురూజీ: 'ఎందుకు చింతిస్తావు? బాబా మంచు కురవాలని అనుకుంటే ఎంతసేపు పడుతుంది?' కొద్దిసేపటికే మంచు కురిసి తెల్లవారేసరికి దట్టంగా పేరుకుంది.", "id": "te-bk-075", "kind": "single_select", "language": "te", "options": ["మంచు కురవదని చెప్పారు", "'బాబా మంచు కురవాలని అనుకుంటే ఎంతసేపు?' అన్నారు", "వెంటనే వెళ్ళిపోదాం అన్నారు", "ఇది సహజమే అన్నారు"], "question": "సిమ్లాలో మంచు కురవడం లేదని భక్తుడు అడిగినప్పుడు గురూజీ ఏమన్నారు?", "source_label": "Sai Deevena (Bound to Love), 'A journey of wonders'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": true, "explanation": "హోటల్ సిబ్బంది మూడు సంవత్సరాలుగా ఇంత భారీ మంచు కురవలేదని, ఇంత ఆలస్యంగా సీజన్లో ఆశ్చర్యపోయామని చెప్పారు.", "id": "te-bk-076", "kind": "true_false", "language": "te", "question": "సిమ్లా హోటల్ సిబ్బంది మూడు సంవత్సరాలుగా ఇంత భారీ మంచు చూడలేదని చెప్పారు.", "source_label": "Sai Deevena (Bound to Love), 'A journey of wonders'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": "శాంతించు! (Calm down!)", "explanation": "తిరువణ్ణామలై ప్రయాణంలో రెండు పంక్చర్లు, తప్పిన దారి వల్ల మధ్యాహ్నం 2 గంటల విమానానికి 3 గంటలకు చేరుకున్నారు. గురూజీ 'శాంతించు!' (Calm down!) అని చెప్పారు. విమానం ఆలస్యమై వారు అడుగుపెడుతుండగానే దిగింది.", "id": "te-bk-077", "kind": "quote_completion", "language": "te", "question": "విమానం తప్పిపోతుందని ఆందోళన చెందిన భక్తునితో గురూజీ అన్న మాటను పూర్తి చేయండి: '___'", "source_label": "Sai Deevena (Bound to Love), 'Calm down!'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 1, "explanation": "సిబ్బంది 'మీకు విమానం ఆలస్యమై ఈ సమయానికి వస్తుందని ఎలా తెలుసు?' అని అడిగితే వారు 'మేము మా గురూజీతో వచ్చాం' అని జవాబిచ్చారు.", "id": "te-bk-078", "kind": "single_select", "language": "te", "options": ["విమానాశ్రయ అధికారులకు ఫోన్ చేశాం", "మేము మా గురూజీతో వచ్చాం", "మాకు ముందే తెలుసు", "అదృష్టం"], "question": "విమానం ఆలస్యం గురించి ఎలా తెలుసని సిబ్బంది అడిగితే భక్తులు ఏమని జవాబిచ్చారు?", "source_label": "Sai Deevena (Bound to Love), 'Calm down!'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": [0, 1, 2], "explanation": "కోరికలు తీరడం వల్ల వ్యక్తిత్వంలో, దృక్పథంలో మార్పు; భయాలు, ఇష్టాయిష్టాలలో మార్పు; ఇబ్బంది పెట్టే అలవాట్లు అదృశ్యం — ఇవన్నీ రూపాంతరానికి చిహ్నాలు.", "id": "te-bk-079", "kind": "multi_select", "language": "te", "options": ["వ్యక్తిత్వంలో, దృక్పథంలో మార్పు", "భయాలు, ఇష్టాయిష్టాలలో మార్పు", "ఇబ్బంది పెట్టే అలవాట్లు అదృశ్యం కావడం", "ధనం పెరగడం"], "question": "అనుభవం తర్వాత రూపాంతరం చెందిందో లేదో ఎలా తెలుసుకోవాలి? శ్రీబాబుజీ చెప్పిన చిహ్నాలు ఏవి?", "source_label": "Sai Deevena (Bound to Love), 'Love is the Principle'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": "ప్రేమే సూత్రం", "explanation": "బౌండ్ టు లవ్ పరిచయ అధ్యాయం శీర్షిక 'Love is the Principle' (ప్రేమే సూత్రం). సాయిబాబా మార్గంలో కోరికలు తీరడం అనే అనుభవం ప్రేమ బంధం అభివృద్ధికి ఇంధనం.", "id": "te-bk-080", "kind": "flashcard", "language": "te", "question": "బౌండ్ టు లవ్ — ప్రేమే సూత్రం", "source_label": "Sai Deevena (Bound to Love), పరిచయం", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": false, "explanation": "శ్రీబాబుజీ: 'సాయిబాబా మన కోరికలను విడిచిపెట్టమని లేదా నాశనం చేయమని అడగరు.'", "id": "te-bk-081", "kind": "true_false", "language": "te", "question": "సాయిబాబా మన కోరికలను విడిచిపెట్టమని లేదా నాశనం చేయమని అడుగుతారని శ్రీబాబుజీ చెప్పారు.", "source_label": "Sai Deevena (Bound to Love), 'Love is the Principle'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 0, "explanation": "1974లో నెల్లూరులో గురూజీ అమ్మమ్మ ఇంటి భాగంలో అద్దెకు ఉన్న భక్తుడు; గురూజీ చెల్లెలు సుచిత్ర ద్వారా పరిచయం. గురూజీ సాయిబాబాను ప్రార్థించమని సూచించారు.", "id": "te-bk-082", "kind": "single_select", "language": "te", "options": ["నెల్లూరు", "వెంకటగిరి", "తెనాలి", "హైదరాబాద్"], "question": "'We had no idea' అనుభవంలో భక్తుడు 1974లో ఎక్కడ నివసిస్తున్నారు?", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": true, "explanation": "'ఆ చిత్రాన్ని చూసినప్పుడల్లా శాంతి, ఆనందాల తరంగం నన్ను ముంచెత్తేది, నన్ను ఆశ్చర్యపరిచేది.'", "id": "te-bk-083", "kind": "true_false", "language": "te", "question": "సాయిబాబా చిత్రాన్ని చూసినప్పుడల్లా భక్తునికి శాంతి, ఆనందాల తరంగం కలిగేది.", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 1, "explanation": "గురూజీ తమ గురువు ఆచార్య భరద్వాజను పరిచయం చేశారు; ఆయన వెంకటగిరిలో సత్సంగం ఇవ్వడం ప్రారంభించారు.", "id": "te-bk-084", "kind": "single_select", "language": "te", "options": ["నానాసాహెబ్ చందోర్కర్", "ఆచార్య భరద్వాజ", "దాసగణు మహారాజ్", "శ్యామా"], "question": "గురూజీ తమ గురువుగా పరిచయం చేసినవారు ఎవరు?", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": ["గురూజీ గురువును ప్రతిసారీ ఆడంబరంగా ఆహ్వానించేవారు", "ఆచారం ప్రేమ వ్యక్తీకరణగా మొదలవుతుంది", "సద్గురువు ప్రేమను రేకెత్తిస్తారు"], "explanation": "'We had no idea' అనుభవంలోని మూడు ముఖ్యాంశాలు.", "id": "te-bk-085", "kind": "matching", "language": "te", "options": ["గురుభక్తి", "ఆచారాల అర్థం", "సద్గురువు నిర్వచనం"], "question": "భావాలను వాటి వివరణలతో జతపరచండి.", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": false, "explanation": "బస్సు చక్రం నట్లు అన్నీ ఊడిపోయినా లోయలో పడలేదు; డ్రైవర్ గురూజీ పాదాలపై పడ్డాడు. తర్వాత మూడు ఖాళీ జీపులు వచ్చి కౌసానీ చేర్చాయి.", "id": "te-bk-086", "kind": "true_false", "language": "te", "question": "కౌసానీ ప్రయాణంలో బస్సు లోయలో పడిపోయింది.", "source_label": "Sai Deevena (Bound to Love), 'A journey of wonders'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 0, "explanation": "దూరదర్శన్ రిపోర్టర్లు ఆకస్మిక మంచు గురించి ఇంటర్వ్యూ చేస్తుండగా భక్తుల కోటులకు పిన్ చేసిన బాబా, గురూజీ చిన్న చిత్రాన్ని చూసి ప్రశ్నలు అడిగారు.", "id": "te-bk-087", "kind": "single_select", "language": "te", "options": ["దూరదర్శన్ రిపోర్టర్లు", "పర్యాటకులు", "హోటల్ సిబ్బంది", "సైనికులు"], "question": "సిమ్లాలో ఆకస్మిక మంచు గురించి ఎవరు ఇంటర్వ్యూ చేస్తున్నారు?", "source_label": "Sai Deevena (Bound to Love), 'A journey of wonders'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": true, "explanation": "రిపోర్టర్ 'మీ గురూజీ డబ్బు కూడా ఇవ్వగలరా?' అని అడిగితే భక్తులు 'అవును' అన్నారు.", "id": "te-bk-088", "kind": "true_false", "language": "te", "question": "దూరదర్శన్ రిపోర్టర్ గురూజీ డబ్బు ఇవ్వగలరా అని అడిగారు.", "source_label": "Sai Deevena (Bound to Love), 'A journey of wonders'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": "కృతజ్ఞత", "explanation": "'బాబా మనకు వివిధ రకాల అనుభవాలను ఇస్తారు, తద్వారా ఆయనకు మనకు ఏది ఉత్తమమో తెలుసని గ్రహిస్తాం. శ్రద్ధగా చూసుకుంటున్నారనే భావం నుండి కృతజ్ఞత పుడుతుంది, అది భక్తిగా అభివృద్ధి చెందుతుంది.'", "id": "te-bk-089", "kind": "quote_completion", "language": "te", "question": "శ్రీబాబుజీ మాటను పూర్తి చేయండి: 'బాబా మనకు ఏది ఉత్తమమో తెలుసని గ్రహించడం వల్ల శ్రద్ధగా చూసుకుంటున్నారనే భావం కలుగుతుంది; ఆ భావం నుండి ___ పుడుతుంది.'", "source_label": "Sai Deevena (Bound to Love), 'Love is the Principle'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 1, "explanation": "'అప్పుడు బాబా పట్ల ప్రేమ నెమ్మదిగా మరింత మరింత పెద్ద మంటగా పెరుగుతుంది, అది ఇతర భావాలన్నింటినీ దహించేవరకు.'", "id": "te-bk-090", "kind": "single_select", "language": "te", "options": ["జ్ఞానం", "ప్రేమ", "భయం", "కోపం"], "question": "శ్రీబాబుజీ ప్రకారం హృదయంలో రగిలి అన్ని బంధాలను దహించే మంట ఏది?", "source_label": "Sai Deevena (Bound to Love), 'Love is the Principle'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": "బాబా కోరిక తీరిస్తే అది వారి రూపాంతరం కోసమే; వ్యక్తికి తెలియకపోయినా పర్వాలేదు. అది బాబా ఇచ్చిన అనుభవమని తెలిస్తే చాలు.", "explanation": "'వారికి అలాగే అనిపించవచ్చు; రూపాంతరం గురించి ఆలోచన కూడా ఉండకపోవచ్చు. కానీ బాబా కోరిక తీరిస్తే అది వారి రూపాంతరం కోసమే.'", "id": "te-bk-091", "kind": "flashcard", "language": "te", "question": "కోరిక తీర్చడం — రూపాంతరం కోసమే", "source_label": "Sai Deevena (Bound to Love), 'Love is the Principle'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": [0, 1], "explanation": "1976 మేలో వెంకటగిరిలో ఇండస్ట్రియల్ ట్రైనింగ్ ఇన్స్టిట్యూట్లో జూనియర్ అసిస్టెంట్గా ఉద్యోగం; రెండు నెలల తర్వాత గురూజీ తండ్రి హెడ్మాస్టర్గా బదిలీపై వచ్చారు.", "id": "te-bk-092", "kind": "multi_select", "language": "te", "options": ["1976లో వెంకటగిరికి మారారు", "ఇండస్ట్రియల్ ట్రైనింగ్ ఇన్స్టిట్యూట్లో జూనియర్ అసిస్టెంట్", "ఉపాధ్యాయునిగా పనిచేశారు", "వైద్యునిగా పనిచేశారు"], "question": "'We had no idea' భక్తుని గురించి సరైనవి ఏవి?", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": false, "explanation": "గురూజీ గురువారం (గురువు సంప్రదాయిక దినం) నాడు సాయిబాబా చిత్రాన్ని ఇచ్చి ఫ్రేమ్ కట్టించమని సూచించారు.", "id": "te-bk-093", "kind": "true_false", "language": "te", "question": "గురూజీ సాయిబాబా చిత్రాన్ని సోమవారం నాడు ఇచ్చారు.", "source_label": "Sai Deevena (Bound to Love), 'We had no idea'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 0, "explanation": "'గురూజీ నిద్రపోయారు. విమానాశ్రయానికి ఫోన్ చేసి టికెట్లు రద్దు చేయాలనుకున్నాను కానీ గురూజీ నిద్రపోతుండగా మాట్లాడడానికి సాహసించలేదు.'", "id": "te-bk-094", "kind": "single_select", "language": "te", "options": ["గురూజీ నిద్రపోతుండగా మాట్లాడడానికి సాహసించలేదు", "ఫోన్ పనిచేయలేదు", "టికెట్లు దొరకలేదు", "డ్రైవర్ నిరాకరించాడు"], "question": "భక్తుడు విమానాశ్రయానికి ఫోన్ చేసి టికెట్లు రద్దు చేయాలనుకున్నా ఎందుకు చేయలేదు?", "source_label": "Sai Deevena (Bound to Love), 'Calm down!'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 1, "explanation": "శివశంకర్ పద్మనాభుని (1952–2002) హైదరాబాద్ వ్యాపారవేత్త; 'Calm down!' అనుభవం వ్రాసినవారు.", "id": "te-bk-095", "kind": "single_select", "language": "te", "options": ["కొండయ్య", "శివశంకర్ పద్మనాభుని", "వెంకటేశ్వర", "సుచిత్ర"], "question": "'Calm down!' అనుభవాన్ని వ్రాసిన భక్తుడు ఎవరు?", "source_label": "Sai Deevena (Bound to Love), 'Calm down!'", "source_link": "https://downloads.saibaba.com/publications/pdfs/SAI_DEEVENA.pdf"}, {"answer": 1, "explanation": "స్మృతి సుమాలు (పు. 8): 'సాధనలో తొలి అడుగులు వేస్తున్న వారికి అద్భుత, నిగూఢ అనుభవాలనిచ్చారు.'", "id": "te-bk-096", "kind": "single_select", "language": "te", "options": ["దీక్ష ఇచ్చారు", "అద్భుత, నిగూఢ అనుభవాలనిచ్చారు", "ధనం ఇచ్చారు", "ఉద్యోగాలు ఇప్పించారు"], "question": "సాధనలో తొలి అడుగులు వేస్తున్న వారికి శ్రీబాబుజీ ఏమి ఇచ్చారు?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": [0, 1, 2], "explanation": "'శ్రీబాబుజీ అనుగ్రహంచేత ఎందరికో అనారోగ్యం కుదిరి స్వస్థత కలిగింది. దిక్కులేక దిగాలుపడ్డ జీవితాలకు సాంత్వన చేకూరింది. ఎందరో వ్యాపారస్తులు అభివృద్ధి సాధించారు.'", "id": "te-bk-097", "kind": "multi_select", "language": "te", "options": ["అనారోగ్యం కుదిరి స్వస్థత", "దిగాలుపడ్డ జీవితాలకు సాంత్వన", "వ్యాపారస్తుల అభివృద్ధి", "రాజకీయ పదవులు"], "question": "శ్రీబాబుజీ అనుగ్రహం వల్ల కలిగిన మేలులు ఏవి?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": true, "explanation": "'ఎందరో మేధావులు ఊహకందని ఆయన మేధస్సుకు, అపార జ్ఞానానికి అవ్వెరుపొందారు, ఆ జ్ఞానసాగరంలో ఓలలాడారు.'", "id": "te-bk-098", "kind": "true_false", "language": "te", "question": "మేధావులు శ్రీబాబుజీ మేధస్సుకు, అపార జ్ఞానానికి అవ్వెరుపొందారు.", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 0, "explanation": "'చాలా సంవత్సరాలపాటు - తెలుగు, ఆంగ్లం, సంస్కృతం, హిందీ, మరాఠీ భాషల్లో ఉన్న అరుదైన, ప్రత్యేకమైన పుస్తకాలతో కూడిన విశిష్టమైన వ్యక్తిగత గ్రంథాలయాన్ని ఏర్పాటుచేసుకొన్నారు.'", "id": "te-bk-099", "kind": "single_select", "language": "te", "options": ["తెలుగు, ఆంగ్లం, సంస్కృతం, హిందీ, మరాఠీ", "కేవలం తెలుగు", "తెలుగు, తమిళం", "ఆంగ్లం మాత్రమే"], "question": "శ్రీబాబుజీ వ్యక్తిగత గ్రంథాలయంలో ఏ భాషల పుస్తకాలు ఉన్నాయి?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 1, "explanation": "'అయితే వీటన్నిటికీ ఆధారం, మూలాంశం - సాయిబాబానే.'", "id": "te-bk-100", "kind": "single_select", "language": "te", "options": ["రమణ మహర్షి", "సాయిబాబా", "వేదాలు", "తన స్వీయ అనుభవం"], "question": "శ్రీబాబుజీ పరిశోధన గ్రంథాలన్నిటికీ ఆధారం, మూలాంశం ఎవరు?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": true, "explanation": "'తెలుగు, ఆంగ్లభాషల్లో వారికి అసాధారణమైన సాధికారత ఉండేది. తమకే సొంతమైన కవితాత్మకమైన భావప్రకటనకు, ప్రత్యేకమైన శైలికి వారికి వారే సాటి.'", "id": "te-bk-101", "kind": "true_false", "language": "te", "question": "తెలుగు, ఆంగ్లభాషల్లో శ్రీబాబుజీకి అసాధారణమైన సాధికారత ఉండేది.", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 0, "explanation": "'అదే స్ఫూర్తితో శ్రీబాబుజీ కంప్యూటర్ టెక్నాలజీని నేర్చుకొన్నారు. అతి తక్కువ సమయంలో అటు హార్డ్వేర్ లోనూ ఇటు సాఫ్ట్వేర్ లోనూ నిష్ణాతులయ్యారు.'", "id": "te-bk-102", "kind": "single_select", "language": "te", "options": ["కంప్యూటర్ టెక్నాలజీ", "వైద్యశాస్త్రం", "న్యాయశాస్త్రం", "వ్యవసాయం"], "question": "వృద్ధాప్యంలో శ్రీబాబుజీ ఏ నూతన విద్యను నేర్చుకొన్నారు?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 1, "explanation": "'విద్యానగర్ కాలేజీలో విద్యార్థిగా ఉన్నప్పుడు వారి ఇంగ్లీషు లెక్చరర్ అయిన మాస్టర్ భరద్వాజగారు శ్రీబాబుజీకి సాయిబాబాను తొలిసారిగా పరిచయం చేశారు.'", "id": "te-bk-103", "kind": "single_select", "language": "te", "options": ["నానాసాహెబ్ చందోర్కర్", "మాస్టర్ భరద్వాజ", "దాసగణు మహారాజ్", "శ్యామా"], "question": "శ్రీబాబుజీకి సాయిబాబాను తొలిసారిగా పరిచయం చేసింది ఎవరు?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": "సాక్షాత్కారం సాధ్యమే", "explanation": "'శ్రీరమణమహర్షి జీవిత చరిత్ర శ్రీబాబుజీని అత్యంత ప్రభావితం చేసి, 'ఈ జీవితకాలంలో సాక్షాత్కారం సాధ్యమే' అన్న స్ఫూర్తిని ప్రసాదించింది.'", "id": "te-bk-104", "kind": "quote_completion", "language": "te", "question": "రమణమహర్షి జీవిత చరిత్ర నుండి శ్రీబాబుజీ పొందిన స్ఫూర్తిని పూర్తి చేయండి: 'ఈ జీవితకాలంలో ___'", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 0, "explanation": "'శ్రీబాబుజీ సాగించిన కఠోర సాధన, తమ 20వ యేట శ్రీసాయిబాబా అనుగ్రహం విశేషంగా ... ఫలప్రదమైంది.'", "id": "te-bk-105", "kind": "single_select", "language": "te", "options": ["20వ యేట", "30వ యేట", "40వ యేట", "50వ యేట"], "question": "శ్రీబాబుజీ కఠోర సాధన ఏ వయస్సులో ఫలప్రదమైంది?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 1, "explanation": "'జనవరి 1, 1988న శ్రీబాబుజీ 'సాయిపథం' పత్రిక స్థాపించి, అందుకవసరమైన రచన మరియు ఎడిటింగ్ స్వయంగా చేసేవారు.'", "id": "te-bk-106", "kind": "single_select", "language": "te", "options": ["1985", "1988", "1990", "1995"], "question": "శ్రీబాబుజీ 'సాయిపథం' పత్రికను ఎప్పుడు స్థాపించారు?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": "13 నవంబర్ 2010, శనివారం మధ్యాహ్నం 1గం.51నిమిషాలకు", "explanation": "'13 నవంబర్ 2010, శనివారం మధ్యాహ్నం 1గం.51నిమిషాలకు పూజ్యగురుదేవులు శ్రీసాయినాథుని శరత్బాబుజీ మహాసమాధి చెందారు.'", "id": "te-bk-107", "kind": "quote_completion", "language": "te", "question": "శ్రీబాబుజీ మహాసమాధి చెందిన తేదీ, సమయాన్ని పూర్తి చేయండి: '___ పూజ్యగురుదేవులు శ్రీసాయినాథుని శరత్బాబుజీ మహాసమాధి చెందారు.'", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": true, "explanation": "'కష్టాలతో, సమస్యలతో దిగాలుపడ్డ దీనులకు సాయిమహిమను తెలిపి, సాయిదరికి చేర్చి, సాయిప్రబోధాన్ని పంచి, సాయి ప్రేమానుగ్రహాన్ని చవిచూపించి, వారి జీవితాలను ఆనందసాయిమయం జేసిన మహాత్ములు' — శ్రీబాబుజీ.", "id": "te-bk-108", "kind": "true_false", "language": "te", "question": "శ్రీబాబుజీ కష్టాలలో ఉన్నవారికి సాయిమహిమను తెలిపి వారి జీవితాలను ఆనందమయం చేశారు.", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": 1, "explanation": "'ఆశ్రయించిన వారందరికి తల్లి, తండ్రి, సద్గురువు, సర్వం తానేయైన మహామహితాత్ములు పూజ్యశ్రీ సాయినాథుని శరత్బాబుజీ.'", "id": "te-bk-109", "kind": "single_select", "language": "te", "options": ["ఒక గొప్ప పండితుడు", "ఆశ్రయించిన వారికి తల్లి, తండ్రి, సద్గురువు, సర్వం", "ఒక సంఘసంస్కర్త", "ఒక రాజకీయ నాయకుడు"], "question": "'సాయి విశాలాకాశంలో సద్గురుచంద్రుడు' వ్యాసం శ్రీబాబుజీని ఎలా వర్ణిస్తుంది?", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": "సాయి స్మరణ మనసులో శ్వాసగా, సాయిపైనే ఆధారపడి జీవించి, సాయిని ఆరాధించి, ప్రేమించి, తన ప్రతి స్పందనను సాయిలో లయించి, సాయితో ఐక్యమయ్యారు.", "explanation": "'సాయి స్మరణ మననలో శ్వాసగా, సాయిపైనే ఆధారపడి జీవించి, సాయిని ఆరాధించి, ప్రేమించి, తన ప్రతి స్పందనను సాయిలో లయించి, సాయితో ఐక్యమయ్యారు.'", "id": "te-bk-110", "kind": "flashcard", "language": "te", "question": "శ్రీబాబుజీ — సాయితో ఐక్యం", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": [0, 1, 2], "explanation": "పు. 8: గ్రంథాలయం (5 భాషలు), కంప్యూటర్ టెక్నాలజీ, 'సాయిపథం' పత్రిక (1988).", "id": "te-bk-111", "kind": "multi_select", "language": "te", "options": ["ఐదు భాషల గ్రంథాలయం ఏర్పాటు", "వృద్ధాప్యంలో కంప్యూటర్ టెక్నాలజీ నేర్చుకోవడం", "1988లో 'సాయిపథం' పత్రిక స్థాపన", "రాజకీయాలలో పాల్గొనడం"], "question": "శ్రీబాబుజీ విశేషాలలో సరైనవి ఏవి?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": "మాస్టర్ భరద్వాజ — విద్యానగర్ కాలేజీ ఇంగ్లీషు లెక్చరర్; రమణమహర్షి — 'సాక్షాత్కారం సాధ్యమే' స్ఫూర్తి; సాయిబాబా — అన్ని పరిశోధనలకు ఆధారం.", "explanation": "స్మృతి సుమాలు పు. 8 నుండి.", "id": "te-bk-112", "kind": "matching", "language": "te", "options": ["మాస్టర్ భరద్వాజ", "రమణమహర్షి", "సాయిబాబా"], "question": "వ్యక్తులను వారి పాత్రతో జతపరచండి.", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": false, "explanation": "'శ్రీబాబుజీ పుస్తకపఠనంపట్ల మంచి అభిరుచిగల దార్శనికులు. అంతేగాకుండా గొప్ప రచయిత, గ్రంథకర్తగా విఖ్యాతిచెందారు.'", "id": "te-bk-113", "kind": "true_false", "language": "te", "question": "శ్రీబాబుజీ కేవలం పాఠకుడు మాత్రమే; రచయిత కాదు.", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 1, "explanation": "'పాశ్చాత్యులు శ్రీబాబుజీ దగ్గరకు రావడం ఆరంభించిన తర్వాత వాళ్ళ వాళ్ళ సంస్కృతి, సాహిత్యం, చరిత్ర పట్ల శ్రీబాబుజీకి ఉన్న పరిజ్ఞానం, అవగాహన చూసి వాళ్ళెంతో ఆశ్చర్యపడేవారు.'", "id": "te-bk-114", "kind": "single_select", "language": "te", "options": ["తెలుగు సంస్కృతి గురించి", "పాశ్చాత్య సంస్కృతి, సాహిత్యం, చరిత్ర గురించి", "భారతీయ వేదాల గురించి", "ఆయుర్వేదం గురించి"], "question": "పాశ్చాత్యులు శ్రీబాబుజీ ఏ విషయంలోని పరిజ్ఞానం చూసి ఆశ్చర్యపడేవారు?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": true, "explanation": "'భారతదేశ సంప్రదాయాలపట్ల, ఆధ్యాత్మిక చరిత్రపట్ల శ్రీబాబుజీకి ఎంతో గౌరవం ఉంది. అయితే, ఇతర దేశాల గురించి, ఆధునిక ప్రపంచంలోని నూతన ఆవిష్కరణల గురించి అధ్యయనం చేయడానికి అది అడ్డంకి కాలేదు.'", "id": "te-bk-115", "kind": "true_false", "language": "te", "question": "భారతీయ సంప్రదాయాల పట్ల గౌరవం ఉన్నా, ఆధునిక విషయాల అధ్యయనానికి శ్రీబాబుజీ వెనుకాడలేదు.", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": "మనకు తెలిసిన పాత విషయాలనే పట్టుకొని వేళ్ళాడటం ఎందుకు? నూతన విషయాలను అన్వేషిద్దాం.", "explanation": "శ్రీబాబుజీ: 'మనకు తెలిసిన పాత విషయాలనే పట్టుకొని వేళ్ళాడటం ఎందుకు? నూతన విషయాలను అన్వేషిద్దాం.. పరిశోధిద్దాం.. పరిశీలిద్దాం.. మనకు ఉపయోగపడేది ఉంటే గ్రహిద్దాం' అంటారు.", "id": "te-bk-116", "kind": "quote_completion", "language": "te", "question": "శ్రీబాబుజీ మాటను పూర్తి చేయండి: 'మనకు తెలిసిన పాత విషయాలనే పట్టుకొని వేళ్ళాడటం ఎందుకు? ___'", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 0, "explanation": "'ఆ ప్రజ్ఞ అంతా తమ ఇష్టదైవమైన శ్రీసాయిబాబాను ఇంకా ఇంకా ఆరాధించేందుకు... అంటే, అవిశ్రాంతంగా శ్రమించి, సాయిచరిత్రకు సంబంధించిన అంశాల పరిశోధనకో లేక సాయిబాబా ఒరిజినల్ ఫోటోని ఫోటోషాప్లో పునరుద్ధరించడానికో, మరేదైనా బాబాకు సంబంధించిన అంశాలకో ఉపయోగించారు.'", "id": "te-bk-117", "kind": "single_select", "language": "te", "options": ["సాయిబాబా సేవకే ఉపయోగించారు", "వ్యాపారం కోసం ఉపయోగించారు", "రాజకీయాల కోసం ఉపయోగించారు", "వినోదం కోసం ఉపయోగించారు"], "question": "కంప్యూటర్ ప్రజ్ఞను శ్రీబాబుజీ దేనికోసం ఉపయోగించారు?", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": false, "explanation": "'అప్పటివరకు ఎవరికీ తెలియని సాయిబాబా చరిత్ర విశేషాలు, ఒరిజినల్ ఫోటోలను వెలుగులోకి తెచ్చారు శ్రీబాబుజీ.'", "id": "te-bk-118", "kind": "true_false", "language": "te", "question": "శ్రీబాబుజీ పరిశోధన వల్ల కొత్తగా వెలుగులోకి వచ్చిన సాయిబాబా చరిత్ర విశేషాలు ఏవీ లేవు.", "source_label": "Smriti Sumalu, p. 8", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=8"}, {"answer": 1, "explanation": "'గతితప్పిన సాధన ప్రయాణంలో గమ్యం తెలియని సాధకులకు సాయిమార్గాన్ని చూపిన సన్మార్గదర్శి' — శ్రీబాబుజీ.", "id": "te-bk-119", "kind": "single_select", "language": "te", "options": ["ఒక గొప్ప వక్త", "గతితప్పిన సాధకులకు సాయిమార్గం చూపిన సన్మార్గదర్శి", "ఒక ధనవంతుడు", "ఒక రాజకీయ నాయకుడు"], "question": "'సాయి విశాలాకాశంలో సద్గురుచంద్రుడు' వ్యాసం శ్రీబాబుజీని ఏమని వర్ణిస్తుంది?", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": "చైతన్యం ప్రకృతిలో లీనమైపోయింది", "explanation": "'చైతన్యం ప్రకృతిలో లీనమైపోయింది. సాయితత్త్వ అంబరంలో అనన్య ప్రేమ వెన్నెల కురిపించిన 'శరచ్చంద్రుడు' కాలమబ్బుల చాటుకు వెళ్ళిపోయాడు.'", "id": "te-bk-120", "kind": "quote_completion", "language": "te", "question": "శ్రీబాబుజీ మహాసమాధిని వర్ణిస్తూ వ్యాసం అన్న మాటను పూర్తి చేయండి: '___'", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": [0, 1], "explanation": "పు. 11: 'మూఢాచారాలు, మెట్టవేదాంతమత్తులో జోగాడేవారిని మేల్కొలిపి సంస్కరణపథంలో పయనింపజేసిన సంస్కర్త' మరియు 'అహం, అజ్ఞానం నిండిన ఇరుకు హృదయాల కరుకుదనాన్ని, సాయి కరుణామృతధారల్లో కరిగించిన ప్రేమమూర్తి'.", "id": "te-bk-121", "kind": "multi_select", "language": "te", "options": ["మూఢాచారాల నుండి మేల్కొలిపిన సంస్కర్త", "సాయి కరుణతో హృదయాలను కరిగించిన ప్రేమమూర్తి", "ఒక కఠిన శాసకుడు", "ఒక వ్యాపారవేత్త"], "question": "శ్రీబాబుజీని వర్ణించిన తీర్లు ఏవి?", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": true, "explanation": "'సమస్యయపడని భావాలతో, చిక్కుప్రశ్నలతో దిక్కుతోచని జిజ్ఞాసువుల హృదయాల్లో జ్ఞానజ్యోతులు వెలిగించిన సాయిసుజ్ఞానదీప్తి' — శ్రీబాబుజీ.", "id": "te-bk-122", "kind": "true_false", "language": "te", "question": "శ్రీబాబుజీ జిజ్ఞాసువుల హృదయాల్లో జ్ఞానజ్యోతులు వెలిగించారు.", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": 0, "explanation": "'అంతవరకు వెన్నెల్లో ఆనందంగా నర్తిస్తున్న భక్తతారకలు దిగాలుపడి కూలిపోయాయి' — శ్రీబాబుజీ మహాసమాధి తర్వాత భక్తుల స్థితి.", "id": "te-bk-123", "kind": "single_select", "language": "te", "options": ["దిగాలుపడి కూలిపోయాయి", "ఆనందంగా నర్తిస్తూనే ఉన్నాయి", "మరింత ప్రకాశించాయి", "అదృశ్యమయ్యాయి"], "question": "శ్రీబాబుజీ మహాసమాధి తర్వాత భక్తతారకల స్థితిని వ్యాసం ఎలా వర్ణిస్తుంది?", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": "సాయిభక్త అంబరం కాంతి విహీనమయ్యింది", "explanation": "'సాయిభక్త అంబరం కాంతి విహీనమయ్యింది.'", "id": "te-bk-124", "kind": "flashcard", "language": "te", "question": "శ్రీబాబుజీ మహాసమాధి — సాయిభక్త అంబరం", "source_label": "Smriti Sumalu, p. 11", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf#page=11"}, {"answer": 1, "explanation": "స్మృతి సుమాలు — గురుపూర్ణిమ జూలై 2011లో ప్రచురించబడిన 'పూలదండ' (Flowers of Remembrance); భక్తుల జ్ఞాపకాలు, అనుభవాలు.", "id": "te-bk-125", "kind": "single_select", "language": "te", "options": ["2010", "2011", "2012", "2013"], "question": "'స్మృతి సుమాలు' (Flowers of Remembrance) ఏ సంవత్సరంలో ప్రచురించబడింది?", "source_label": "Smriti Sumalu, ప్రచురణ వివరాలు", "source_link": "https://downloads.saibaba.com/publications/pdfs/SMRITI_SUMALU.pdf"}, {"answer": 0, "explanation": "'ద్వారకా' అంటే అనేక ద్వారాలు, 'మాయి' అంటే తల్లి.", "id": "te-tx-004", "kind": "single_select", "language": "te", "options": ["అనేక ద్వారాలు గల తల్లి", "జ్ఞానానికి ద్వారం", "సాయికి నిలయం", "శాంతి మందిరం"], "question": "ద్వారకామాయి అనే పేరుకు అర్థం ఏమిటి?", "source_label": "2 Dec 2012 Shirdi satsang (Dwarakamai, part 1)", "source_link": "https://www.youtube.com/watch?v=ST_bs2q-q7M&t=3s"}, {"answer": true, "explanation": "దూని ప్రాముఖ్యం గురించి అడిగితే బాబా ఇచ్చిన సమాధానం ఇదే.", "id": "te-tx-005", "kind": "true_false", "language": "te", "question": "దూనిని 'మన పాపాలను కాల్చడానికే' వెలిగిస్తున్నామని బాబా చెప్పారు అని ఈ ప్రవచనంలో ఉంది.", "source_label": "2 Dec 2012 Shirdi satsang (Dwarakamai, part 1)", "source_link": "https://www.youtube.com/watch?v=ST_bs2q-q7M&t=12s"}, {"answer": "బాబా పాదధూళి — ఆయన స్పర్శ, ఆయన కృపకు చిహ్నం.", "explanation": "ఉదీ అంటే బాబా పాదధూళి అని శ్రీ బాబుజీ చెప్పారు.", "id": "te-tx-006", "kind": "flashcard", "language": "te", "question": "శ్రీ బాబుజీ మాటల్లో ఉదీ అంటే ఏమిటి?", "source_label": "2 Dec 2012 Shirdi satsang (Dwarakamai, part 1)", "source_link": "https://www.youtube.com/watch?v=ST_bs2q-q7M&t=16s"}, {"answer": "'సాయి' అంటే ఆనందం, 'పథం' అంటే మార్గం — ఎల్లప్పుడూ సంతోషంగా ఉండటమే సాయిపథంలో ఉండటం.", "explanation": "ఆనందజీవనమే సాయిపథం; సంతోషాన్ని పదిమందితో పంచుకుంటే మరింత సంతోషం వస్తుంది.", "id": "te-tx-007", "kind": "flashcard", "language": "te", "question": "సాయిపథం అనే పదానికి శ్రీ బాబుజీ ఇచ్చిన అర్థం ఏమిటి?", "source_label": "25 Oct 2015 satsang (Anandajeevanam Saipatham)", "source_link": "https://www.youtube.com/watch?v=SGzh0364unw&t=0s"}, {"answer": 0, "explanation": "ఒకసారి ఆలోచిస్తే అది పోతుంది; మళ్లీ వస్తే మళ్లీ ఆలోచించాలి — ఇదే వివేకం.", "id": "te-tx-008", "kind": "single_select", "language": "te", "options": ["వివేకంతో ప్రశ్నించుకోవాలి — ఇది నిజంగా సమంజసమా, నిజంగా అవసరమా అని", "వెంటనే ఏడ్చి బాబాను అడగాలి", "ఇతరులను నిందించాలి", "ఏమీ చేయకుండా మౌనంగా ఉండాలి"], "question": "దుఃఖం, అలజడి వచ్చినప్పుడు శ్రీ బాబుజీ ఏమి చేయమన్నారు?", "source_label": "25 Oct 2015 satsang (Anandajeevanam Saipatham)", "source_link": "https://www.youtube.com/watch?v=SGzh0364unw&t=60s"}, {"answer": true, "explanation": "సంతోషంగా అడగడం; అడిగినది ఇవ్వడం ఆయన వ్రతం.", "id": "te-tx-009", "kind": "true_false", "language": "te", "question": "బాబాను అడిగేటప్పుడు పిల్లవాడు తల్లిని అడిగినట్లు సంతోషంగా అడగాలి, ఏడ్చి కాదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "25 Oct 2015 satsang (Anandajeevanam Saipatham)", "source_link": "https://www.youtube.com/watch?v=SGzh0364unw&t=240s"}, {"answer": [0, 1, 2, 3], "explanation": "ఇవన్నీ మానితేనే మనకూ ఇతరులకూ తేడా ఉంటుంది — అదే సాయిపథం.", "id": "te-tx-010", "kind": "multi_select", "language": "te", "options": ["అబద్ధాలు చెప్పడం", "చాడీలు చెప్పడం", "ఇతరులకు హాని కోరడం", "వ్యాపారంలో మోసం చేయడం, లంచం తీసుకోవడం"], "question": "బాబా బోధించిన సూత్రాల ప్రకారం మనం ఏమేమి మానాలి?", "source_label": "Telugu short discourse: ఏ రకంగా సాయిపథం?", "source_link": "https://www.youtube.com/watch?v=VubNvPKaHhc&t=75s"}, {"answer": true, "explanation": "రోజుకో బాబా సూత్రం తీసుకుని పాటించాలి — 'ఈ రోజు నేను అబద్ధం చెప్పను'.", "id": "te-tx-011", "kind": "true_false", "language": "te", "question": "మార్గదర్శకం వ్యక్తి నుండి కాకుండా సూత్రాల నుండి రావాలని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu short discourse: ఏ రకంగా సాయిపథం?", "source_link": "https://www.youtube.com/watch?v=VubNvPKaHhc&t=111s"}, {"answer": 0, "explanation": "సాయిపథ సూత్రం: డబ్బును పట్టుకుని ఉంచకూడదు, నిల్వ చేయకూడదు.", "id": "te-tx-012", "kind": "single_select", "language": "te", "options": ["రోజూ వేలమంది ఇచ్చినదాన్ని సాయంత్రానికి పంచేసేవారు — ఫకీర్", "డబ్బును భద్రంగా నిల్వ చేసేవారు", "మందిరాల కోసం పెట్టుబడి పెట్టేవారు", "ధనిక భక్తుల నుండే స్వీకరించేవారు"], "question": "డబ్బు విషయంలో బాబా ఆదర్శం ఏమిటి?", "source_label": "Telugu short discourse: ఏ రకంగా సాయిపథం?", "source_link": "https://www.youtube.com/watch?v=VubNvPKaHhc&t=196s"}, {"answer": true, "explanation": "దక్షిణ ప్రారంభాన్ని గుర్తించే సంఘటన నమోదులో లేదు.", "id": "te-tx-013", "kind": "true_false", "language": "te", "question": "బాబా 1908–09 ప్రాంతం నుండి దక్షిణ స్వీకరించడం మొదలుపెట్టారు; దానికి గుర్తించదగిన 'సంఘటన' ఏదీ నమోదు కాలేదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "2022 Aradhana celebrations, Day 2 satsang", "source_link": "https://www.youtube.com/watch?v=39Qa0Thud04&t=817s"}, {"answer": 0, "explanation": "దృష్టి నివారణ క్రియలకు బదులు ఆ స్థాయికి ఎదగమని సలహా.", "id": "te-tx-014", "kind": "single_select", "language": "te", "options": ["పదిమంది నీ మీద దృష్టి పెట్టాలనుకునేంత ఎత్తుకు ఎదగాలి", "ప్రతి వారం దృష్టి తీయించుకోవాలి", "నల్లదారం కట్టుకోవాలి", "దృష్టి అనేదే లేదు"], "question": "దృష్టి (దుష్ట దృష్టి) నివారణ క్రియల గురించి అడిగితే శ్రీ బాబుజీ ఏమి సలహా ఇచ్చారు?", "source_label": "2022 Aradhana celebrations, Day 2 satsang", "source_link": "https://www.youtube.com/watch?v=39Qa0Thud04&t=855s"}, {"answer": [0, 1], "explanation": "'బాబా చూసుకుంటారు' అన్నది నిష్క్రియతకు సాకు కాకూడదు.", "id": "te-tx-015", "kind": "multi_select", "language": "te", "options": ["'బాబా చూసుకుంటారు' అన్నది ప్రయత్నానికి బదులు కాదు", "ఆచరణాత్మక సహాయం, ప్రయత్నం అవసరం", "ప్రార్థన అంటే నిష్క్రియంగా కూర్చోవడం", "బాబా అన్నీ చేస్తారు కాబట్టి మనం ఏమీ చేయనక్కర్లేదు"], "question": "ప్రార్థన గురించి శ్రీ బాబుజీ చెప్పిన సరైన అంశాలు ఏవి?", "source_label": "2022 Aradhana celebrations, Day 2 satsang", "source_link": "https://www.youtube.com/watch?v=39Qa0Thud04&t=1099s"}, {"answer": "ఉత్తరం వైపు — కూర్చున్న భంగిమలో అయితే మేలు; కుదరకపోతే కనీసం ముఖం ఉత్తరం వైపు ఉండాలి; రెండు సంప్రదాయాలూ ఉత్తరాన్నే అంగీకరిస్తాయి.", "explanation": "సమాధి సంప్రదాయం గురించి అడిగిన ప్రశ్నకు శ్రీ బాబుజీ సమాధానం.", "id": "te-tx-016", "kind": "flashcard", "language": "te", "question": "సమాధి విషయంలో శరీరాన్ని ఏ దిశకు ముఖం పెట్టి ఉంచాలి?", "source_label": "Telugu Q&A on samadhi tradition", "source_link": "https://www.youtube.com/watch?v=7yEUp2QZLAM&t=1s"}, {"answer": true, "explanation": "దర్శనం కోసం ద్వారకామాయిలో కూర్చోబెట్టి ఉంచారు; ఎత్తినప్పుడు అవయవాలు మెత్తగా ఉన్నాయి.", "id": "te-tx-017", "kind": "true_false", "language": "te", "question": "బాబా శరీరం మూడు రోజుల తర్వాత కూడా గట్టిపడలేదు; అవయవాలు నిద్రపోతున్నట్లు మెత్తగానే ఉన్నాయి.", "source_label": "Telugu Q&A on samadhi tradition", "source_link": "https://www.youtube.com/watch?v=7yEUp2QZLAM&t=2s"}, {"answer": "రూపం అస్థిరం — అది నిరాకారునికి మార్గం మాత్రమే. ఫ్రేమ్‌ను చూడకు, కిటికీ గుండా చూడు; ఫ్రేమ్ దగ్గరే ఆగిపోకు.", "explanation": "రూపంతో మొదలుపెట్టాలి కానీ అక్కడే ఆగకూడదు; బాబా రూపం ఇచ్చే ఆనందం నిరాకారం.", "id": "te-tx-018", "kind": "flashcard", "language": "te", "question": "సగుణ-నిర్గుణ ధ్యానం గురించి శ్రీ బాబుజీ చెప్పిన 'కిటికీ' ఉపమానం ఏమిటి?", "source_label": "Telugu discourse on saguna/nirguna meditation", "source_link": "https://www.youtube.com/watch?v=I59SbZW-2l8&t=1s"}, {"answer": true, "explanation": "కిటికీ గుండా కేంద్రీకరిస్తే అదే మనల్ని కిటికీ దాటి తీసుకెళ్తుంది.", "id": "te-tx-019", "kind": "true_false", "language": "te", "question": "'ఇది కేవలం ఫ్రేమ్ మాత్రమే' అనుకుంటే ఫ్రేమ్ మాత్రమే కనిపిస్తుంది, కిటికీ గుండా ఉన్నది కనిపించదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse on saguna/nirguna meditation", "source_link": "https://www.youtube.com/watch?v=I59SbZW-2l8&t=2s"}, {"answer": "కారణం లేని, స్వార్థం లేని ప్రేమ — ఎందుకో తెలియకుండానే పుట్టే ప్రేమ.", "explanation": "బాబాను చూసినప్పుడు కలిగే ప్రేమ ఇలాంటిదే.", "id": "te-tx-020", "kind": "flashcard", "language": "te", "question": "అవ్యాజమైన ప్రేమ అంటే ఏమిటి?", "source_label": "Telugu discourse on avyaja prema", "source_link": "https://www.youtube.com/watch?v=BZRHz3K5AqE&t=0s"}, {"answer": true, "explanation": "'పరిచయమున్న అపరిచితుడు, అపరిచయమైన పరిచితుడు' — familiar stranger and strangely familiar.", "id": "te-tx-021", "kind": "true_false", "language": "te", "question": "బాబాను చూసినప్పుడు ఆయన అపరిచితుడిలా అనిపిస్తూనే, ఎంతో పరిచితుడిలా కూడా అనిపిస్తారు అని శ్రీ బాబుజీ అన్నారు.", "source_label": "Telugu discourse on avyaja prema", "source_link": "https://www.youtube.com/watch?v=BZRHz3K5AqE&t=2s"}, {"answer": 0, "explanation": "మనసు ఇతరులను నిందించి, సెలవులు-పనుల సాకులు చెప్పి తన అపరాధ భావాన్ని తప్పించుకుంటుంది.", "id": "te-tx-022", "kind": "single_select", "language": "te", "options": ["సాన్నిహిత్యం తగ్గినప్పుడు మనసు సాకులు, నెపాలు చెప్పుకుంటుంది", "సద్గురు కృప తగ్గిపోతుంది", "వయసు పెరగడం వల్ల", "ఇతర భక్తుల వల్ల"], "question": "సద్గురుతో మొదటి రోజుల తీవ్రానుభూతి తర్వాతి రోజుల్లో ఎందుకు తగ్గుతుంది?", "source_label": "Telugu short discourse on fading first experience", "source_link": "https://www.youtube.com/watch?v=lTn0qWd8IXM&t=0s"}, {"answer": true, "explanation": "ఉద్దేశాన్ని మరిచిపోవడమే అనుభూతి తగ్గడానికి కారణం.", "id": "te-tx-023", "kind": "true_false", "language": "te", "question": "మనం ఎందుకు వచ్చామో మరిచిపోకూడదు; ఆ ఉద్దేశ స్పృహను సజీవంగా ఉంచుకోవాలి అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu short discourse on fading first experience", "source_link": "https://www.youtube.com/watch?v=lTn0qWd8IXM&t=2s"}, {"answer": "సృష్టికర్త స్వయంగా ప్రయోజనమున్నవాడు — అందుకే సృష్టిలో ఏదీ ప్రయోజనం లేకుండా లేదు.", "explanation": "మన పుట్టుక ప్రయోజనాన్ని మనమే తెలుసుకోవడానికి ప్రయత్నించాలి.", "id": "te-tx-024", "kind": "flashcard", "language": "te", "question": "ప్రయోజకుడు అంటే ఎవరు?", "source_label": "Telugu short discourse on purpose of birth", "source_link": "https://www.youtube.com/watch?v=_K0gz0nZE9k&t=111s"}, {"answer": "10 రోజులు", "explanation": "కాలం గడుస్తోంది, వయసు గడుస్తోంది — దీన్ని ఎప్పుడూ గుర్తుంచుకోవాలి.", "id": "te-tx-025", "kind": "quote_completion", "language": "te", "question": "శ్రీ బాబుజీ గుర్తుచేసిన జీవన సత్యాన్ని పూర్తి చేయండి: \"బ్రతికేది ___\".", "source_label": "Telugu satsang extract on time passing", "source_link": "https://www.youtube.com/watch?v=2d9peKqhBH8&t=97s"}, {"answer": 0, "explanation": "తన పేరే గుర్తులేనప్పుడు స్నేహితులు లేరు, ఎవరూ లేరు — ఉన్నది అదొక్కటే; తన్మయం కావాలి, మన్మయం కాదు.", "id": "te-tx-026", "kind": "single_select", "language": "te", "options": ["తన పేరే మరిచిపోయి తన్మయమవ్వడం", "మనసులో లీనమవ్వడం (మన్మయం)", "స్నేహితులను గుర్తుంచుకోవడం", "లోకాన్ని అలాగే చూస్తూ ఉండటం"], "question": "ప్రేమ తత్త్వంలో 'బాబా, బాబా' పాట పాడుతూ ఏ స్థితికి చేరాలి?", "source_label": "Telugu satsang extract on time passing", "source_link": "https://www.youtube.com/watch?v=2d9peKqhBH8&t=400s"}, {"answer": "బాబాకు మనకు మధ్య ఉన్న గోడలు — వందల కొద్దీ ఉంటాయి. వాటిని కూల్చడమే మన ప్రయత్నం; మిగిలింది ఆయనే చేస్తాడు.", "explanation": "లక్ష్యం: బాబా తత్త్వం మన అనుభవంలోకి రావడం — ఆయన స్థితి మన స్థితి కావడం.", "id": "te-tx-027", "kind": "flashcard", "language": "te", "question": "అడ్డుగోడలు అంటే ఏమిటి? శ్రీ బాబుజీ వీటి గురించి ఏమి చెప్పారు?", "source_label": "Telugu short discourse: బాబాకు మనల్ని దూరం చేసే అడ్డుగోడలు", "source_link": "https://www.youtube.com/watch?v=DF0-PMiGT2g&t=52s"}, {"answer": "నేనే నువ్వు", "explanation": "బాబా తత్త్వం మన అనుభవం కావడమే లక్ష్యం — ఆయన స్థితి మన స్థితి కావడం.", "id": "te-tx-028", "kind": "quote_completion", "language": "te", "question": "బాబా చెప్పిన మాటను పూర్తి చేయండి: \"నువ్వే నేను, ___\".", "source_label": "Telugu short discourse: బాబాకు మనల్ని దూరం చేసే అడ్డుగోడలు", "source_link": "https://www.youtube.com/watch?v=DF0-PMiGT2g&t=40s"}, {"answer": true, "explanation": "కష్టాల్లో బాబా దూరంగా అనిపిస్తారు — తర్వాత మళ్లీ దగ్గరకు లాగుతారు.", "id": "te-tx-029", "kind": "true_false", "language": "te", "question": "ఆధ్యాత్మిక సాధన అంటే 24 గంటలూ కత్తి అంచు మీద నడక లాంటిది — ఎప్పుడూ ఎరుకతో, జాగ్రత్తగా ఉండాలి అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu short discourse: బాబాకు మనల్ని దూరం చేసే అడ్డుగోడలు", "source_link": "https://www.youtube.com/watch?v=DF0-PMiGT2g&t=91s"}, {"answer": 0, "explanation": "మన సంప్రదాయం వేరు — దాన్ని ప్రపంచానికి నిరూపించాలి.", "id": "te-tx-030", "kind": "single_select", "language": "te", "options": ["వారానికో సూత్రం తీసుకుని, పాటించి, రాసుకోవాలి", "గురువారం ఉపవాసం ఉండాలి", "గురువారం షిర్డీకి వెళ్లాలి", "గురువారం ప్రత్యేక పూజ చేయాలి"], "question": "గురువారం సత్సంగ దినం అంటే శ్రీ బాబుజీ ప్రకారం ఏమి చేయాలి?", "source_label": "11 Apr 2024 satsang on niyamam", "source_link": "https://www.youtube.com/watch?v=DkirfJp2RzA&t=0s"}, {"answer": [0, 1], "explanation": "చాక్లెట్లు తీసుకుని బడి ఎగ్గొట్టవద్దు — కష్టనివారణే లక్ష్యం కాకూడదు.", "id": "te-tx-031", "kind": "multi_select", "language": "te", "options": ["కష్టాలు తీరాలనే ఉద్దేశంతో సత్సంగానికి రావడం", "చాక్లెట్లనే లక్ష్యం చేసుకుని బడిని మరవడం", "ప్రేమతో బాబా కోసం పని చేయడం", "వారానికో సూత్రం తీసుకుని పాటించడం"], "question": "ఈ ప్రవచనం ప్రకారం ఏవి 'వ్యాపారం' (లాభాపేక్షతో చేసేవి)?", "source_label": "11 Apr 2024 satsang on niyamam", "source_link": "https://www.youtube.com/watch?v=DkirfJp2RzA&t=1s"}, {"answer": 0, "explanation": "సద్గురు కృప మన ప్రయత్నాన్ని భర్తీ చేయదు — ప్రయత్నం చేస్తే కృప దాన్ని ఆనందించే శక్తినిస్తుంది.", "id": "te-tx-032", "kind": "single_select", "language": "te", "options": ["ప్రయత్నం మనసుకు రూపం ఇస్తుంది; సోమరితనం అదుపులోకి వస్తుంది", "నిద్ర పూర్తిగా పోతుంది", "ఆరోగ్యం చెడుతుంది", "ఏమీ మారదు"], "question": "నియమంగా ఉదయం 6 గంటలకు లేవడం వల్ల ఏమి జరుగుతుంది?", "source_label": "11 Apr 2024 satsang on niyamam", "source_link": "https://www.youtube.com/watch?v=DkirfJp2RzA&t=4s"}, {"answer": "అనుగ్రహం అంటే ఆయన మనల్ని ప్రేమతో అంగీకరించడం; మన వంతు ఆయనను 'గ్రహం'లా గట్టిగా పట్టుకోవడం.", "explanation": "ప్రయత్నం సహజంగానే జరుగుతుంది; ప్రయత్నించవద్దని బలవంతం చేస్తే మరింత ఒత్తిడి.", "id": "te-tx-033", "kind": "flashcard", "language": "te", "question": "అనుగ్రహం అంటే ఏమిటి? మన వంతు ఏమిటి?", "source_label": "Telugu discourse: is our effort needed for grace?", "source_link": "https://www.youtube.com/watch?v=qhvt0GzCPbI&t=0s"}, {"answer": true, "explanation": "కృప అంటే కార్యం వెనుక ఉన్న ఆయన వైఖరి.", "id": "te-tx-034", "kind": "true_false", "language": "te", "question": "ఊహించని చోట నుండి ఫలితం వస్తే దాన్ని బాబాకు అనుసంధానం చేయడమే కృపను గుర్తించడం అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse: is our effort needed for grace?", "source_link": "https://www.youtube.com/watch?v=qhvt0GzCPbI&t=3s"}, {"answer": "బాబాను గుర్తుచేసి, ఆయన స్మరణలో మనల్ని ఉంచేదేదైనా సాయిపదమే — 'ఇది సాయిపదం, అది కాదు' అని ఆయనెప్పుడూ నిర్ణయించలేదు.", "explanation": "శ్రీ బాబుజీ సూత్రం ఒక్కటే: 'సాయి ఊసే, సాయి ధ్యానం' — ఒక్క దేవుడు, ఒక్క ధ్యానం.", "id": "te-tx-035", "kind": "flashcard", "language": "te", "question": "సాయిపదం అంటే ఏమిటి?", "source_label": "25 Apr 2024 satsang: background of Saipadalu songs", "source_link": "https://www.youtube.com/watch?v=sIC1jxoxJJ4&t=0s"}, {"answer": false, "explanation": "అవి సరదాగా రాసినవి; సత్సంగాల్లో పాడటం భక్తులే మొదలుపెట్టి సంప్రదాయం చేశారు — 'ఆ సంప్రదాయాన్ని ఎవరు మొదలుపెట్టారు? మీరే.'", "id": "te-tx-036", "kind": "true_false", "language": "te", "question": "సాయిపదాలను సత్సంగాల్లో పాడటానికే శ్రీ బాబుజీ రాశారు.", "source_label": "25 Apr 2024 satsang: background of Saipadalu songs", "source_link": "https://www.youtube.com/watch?v=sIC1jxoxJJ4&t=1s"}, {"answer": [0, 1], "explanation": "సత్సంగం మన పరివర్తన కోసం; 'సంఖ్య ముఖ్యం కాదు, నాణ్యత ముఖ్యం.'", "id": "te-tx-037", "kind": "multi_select", "language": "te", "options": ["ఎంతమంది వచ్చారనేది కాదు — పరివర్తన వచ్చిందా అనేది ముఖ్యం", "ఏ వ్యక్తీ ముఖ్యుడు కాకూడదు; బాబానే కేంద్రం కావాలి", "సత్సంగం ప్రచారం కోసం చేయాలి", "అహంకారం పెంచుకోవడానికి సత్సంగానికి రావాలి"], "question": "సత్సంగం గురించి శ్రీ బాబుజీ చెప్పిన సరైన అంశాలు ఏవి?", "source_label": "Telugu short discourse: సత్సంగాల్లో బాబానే కేంద్రం", "source_link": "https://www.youtube.com/watch?v=kd6-PDYSsks&t=47s"}, {"answer": "సాయి భక్తుం", "explanation": "అహంకారం వదులుకోవడమే సాయి భక్తి.", "id": "te-tx-038", "kind": "quote_completion", "language": "te", "question": "శ్రీ బాబుజీ చెప్పిన వాక్యాన్ని పూర్తి చేయండి: \"అహము వదిలేయుటే ___\".", "source_label": "Telugu short discourse: సత్సంగాల్లో బాబానే కేంద్రం", "source_link": "https://www.youtube.com/watch?v=kd6-PDYSsks&t=215s"}, {"answer": true, "explanation": "ఎవరూ నాయకుడు కాదు, ఎవరూ అనుచరుడు కాదు — బాబానే నాయకుడు.", "id": "te-tx-039", "kind": "true_false", "language": "te", "question": "సత్సంగానికి అహం వదులుకోవడానికి రావాలి, అహం పెంచుకోవడానికి కాదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu short discourse: సత్సంగాల్లో బాబానే కేంద్రం", "source_link": "https://www.youtube.com/watch?v=kd6-PDYSsks&t=175s"}, {"answer": 0, "explanation": "బాబా సాయంత్రానికి ఫకీర్‌గా మిగిలేవారు — ఆయన మందిరాలూ అలాగే ఉండాలి.", "id": "te-tx-040", "kind": "single_select", "language": "te", "options": ["దొంగలను ఆకర్షించే విలువైన వస్తువులేవీ ఉండకూడదు; మనందరినీ కాపాడేవాడు తన మందిరాన్ని కాపాడుకోలేడా?", "మందిరం ఎప్పుడూ తెరిచే ఉండాలి కాబట్టి", "తాళాలు ఖరీదైనవి కాబట్టి", "భక్తులకు నమ్మకం లేదు కాబట్టి"], "question": "బాబా మందిరానికి తాళాలు ఎందుకు అవసరం లేదు అని శ్రీ బాబుజీ అన్నారు?", "source_label": "6 Jun 2024 Telugu extract on Sai mandirs and satsangs", "source_link": "https://www.youtube.com/watch?v=lU1UU3766sQ&t=3s"}, {"answer": true, "explanation": "డబ్బు → అధికారం → రాజకీయాలు → బాబాకు దూరం; గురువు పట్ల ప్రేమ, బాబా పట్ల భక్తి మాత్రమే ప్రేరేపించాలి.", "id": "te-tx-041", "kind": "true_false", "language": "te", "question": "భక్తిని ఖరీదైనది చేయకూడదు; డబ్బుకూ సత్సంగానికీ సాయిపథానికీ ఎలాంటి సంబంధమూ ఉండకూడదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "6 Jun 2024 Telugu extract on Sai mandirs and satsangs", "source_link": "https://www.youtube.com/watch?v=lU1UU3766sQ&t=5s"}, {"answer": "మనమంతా బాబా కృపను అన్వేషించేవారం — బాబాను అన్వేషించు, బాబా నుండి అన్వేషించు.", "explanation": "నిరంతర ఆత్మపరిశీలన మనల్ని నిజమైన అన్వేషకులుగా ఉంచుతుంది.", "id": "te-tx-042", "kind": "flashcard", "language": "te", "question": "'సాయిసీకర్స్' అనే పేరుకు శ్రీ బాబుజీ ఇచ్చిన అర్థం ఏమిటి?", "source_label": "Telugu discourse on the meaning of 'Saiseekers'", "source_link": "https://www.youtube.com/watch?v=qTQvgWiibBw&t=0s"}, {"answer": true, "explanation": "ఆత్మపరిశీలన లేకపోతే పొగడ్త, అధికారం, గుర్తింపు వంటి ఇతర అన్వేషణలు చొరబడతాయి.", "id": "te-tx-043", "kind": "true_false", "language": "te", "question": "బాబా దర్శనం లోపల ఆత్మదర్శనంగా జరుగుతుంది అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse on the meaning of 'Saiseekers'", "source_link": "https://www.youtube.com/watch?v=qTQvgWiibBw&t=2s"}, {"answer": true, "explanation": "వార్షికోత్సవం అంటే ఏమిటో మూలానికే వెళ్లి వివరించారు.", "id": "te-tx-044", "kind": "true_false", "language": "te", "question": "ప్రదర్శన (భాష) కోసం చేయడం, ఆయన చెప్పారని మాత్రమే చేయడం తప్పు; బాబా స్మరణలో ఉంచే ఏ కార్యమైనా సరైనదే అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "20 Jun 2024 satsang on anniversaries", "source_link": "https://www.youtube.com/watch?v=lEWW-8bopWI&t=0s"}, {"answer": "మన బయటి కార్యకలాపాలు వేగంగా తిరిగే పెద్ద ముళ్లు; లోపలి మార్పు నెమ్మదిగా కనిపించే చిన్న ముళ్లు — కానీ పెద్ద ముళ్ల కదలికే చిన్న ముళ్లను నడిపిస్తుంది.", "explanation": "షిర్డీ వంటి పుణ్యక్షేత్రంలో కాలగతి గమనించబడదు — ఇది క్షేత్ర ప్రభావం, మహాత్ముని సన్నిధి ప్రభావం.", "id": "te-tx-045", "kind": "flashcard", "language": "te", "question": "శ్రీ బాబుజీ చెప్పిన 'గడియారం' ఉపమానం ఏమిటి?", "source_label": "Telugu short discourse: కాలగతి అనుభవం షిర్డీలో", "source_link": "https://www.youtube.com/watch?v=e5vwdgaR9f4&t=14s"}, {"answer": true, "explanation": "మహాత్ముని సన్నిధిలో కాలం గమనించబడదు — బాబా అన్నారు: 'నా వయసు లక్షల సంవత్సరాలు.'", "id": "te-tx-046", "kind": "true_false", "language": "te", "question": "షిర్డీ వంటి పుణ్యక్షేత్రంలో మూడు రోజులు 'నిన్ననే వచ్చినట్లు' అనిపిస్తుంది; తిరుమలలో కూడా అంతే అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu short discourse: కాలగతి అనుభవం షిర్డీలో", "source_link": "https://www.youtube.com/watch?v=e5vwdgaR9f4&t=91s"}, {"answer": "పరమాత్మ తత్త్వం ప్రతి జీవిలోనూ ఉంది. సచ్చరిత్ర పారాయణం దీన్ని మనలో ముద్రిస్తుంది — ఎవరినీ ద్వేషించకు, ప్రతి జీవినీ నిన్నుగానే చూడు.", "explanation": "బాబా పని: అన్ని జీవుల్లో ఉన్న చైతన్యం గురించిన ఎరుకను మనలో మేల్కొలపడం.", "id": "te-tx-049", "kind": "flashcard", "language": "te", "question": "సర్వజీవ స్వరూపం అంటే ఏమిటి?", "source_label": "2024 Guru Purnima Day 2 satsang", "source_link": "https://www.youtube.com/watch?v=2B3N4clsSZ8&t=14s"}, {"answer": true, "explanation": "'నేను అద్భుతాలు చేయను' — అన్ని జీవుల్లోని చైతన్య ఎరుకను మేల్కొలపడమే ఆయన పని.", "id": "te-tx-050", "kind": "true_false", "language": "te", "question": "బాబా కూర్చుని ప్రవచనాలు ఇవ్వలేదు; ఉపనిషత్ సత్యాన్ని ఆచరణలో చూపించారు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "2024 Guru Purnima Day 2 satsang", "source_link": "https://www.youtube.com/watch?v=2B3N4clsSZ8&t=10s"}, {"answer": 0, "explanation": "సద్గురు తాను సద్గురునని ఎప్పుడూ ప్రకటించుకోరు — మనిషి 'నేను మనిషిని' అని ప్రకటించుకోనట్లే.", "id": "te-tx-051", "kind": "single_select", "language": "te", "options": ["పెద్దవాడు, బరువైనవాడు; తల్లి, తండ్రి, ఆచార్యులతో సహా 14 మంది గురువులు", "మంత్రం ఇచ్చేవాడు", "దేవాలయ పూజారి", "పుస్తకం రాసినవాడు"], "question": "'గురువు' అనే పదానికి సాంప్రదాయిక అర్థం ఏమిటి?", "source_label": "2024 Guru Purnima Day 2 (Session 3) satsang on the guru", "source_link": "https://www.youtube.com/watch?v=NppOocSE1TA&t=600s"}, {"answer": true, "explanation": "అమావాస్య నుండి పూర్ణిమకు చంద్రుడు పెరిగినట్లు గురువు తనను మనలో పూర్ణుడిగా చేస్తారు.", "id": "te-tx-052", "kind": "true_false", "language": "te", "question": "స్తంభాన్ని గురువుగా తీసుకోమని బాబా చెప్పిన భక్తుడు దాన్ని పూజించాడు; నిజమైన గురుపూర్ణిమ అంటే గురువు మాటను పాటించడం — మంత్రం, పూలు కాదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "2024 Guru Purnima Day 2 (Session 3) satsang on the guru", "source_link": "https://www.youtube.com/watch?v=NppOocSE1TA&t=780s"}, {"answer": true, "explanation": "ఎవరైనా మారితే మనం బాబా చేతుల్లోని పనిముట్టు (మిషన్) మాత్రమే.", "id": "te-tx-053", "kind": "true_false", "language": "te", "question": "ఎవరూ ఎవరినీ సాయిభక్తులుగా మార్చలేరు — మారుతున్నవారిని ఆపనూ లేరు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu short discourse: ఎవ్వరూ ఎవ్వరినీ సాయిభక్తులుగా మార్చలేరు", "source_link": "https://www.youtube.com/watch?v=L-MJIDD-hVU&t=246s"}, {"answer": 0, "explanation": "ఇతరులను ఒప్పించే ప్రయత్నం చేయవద్దు — సాయి తత్త్వ ప్రచారం ఎప్పుడూ చేయవద్దు; బాబాకు ప్రచారం అవసరం లేదు.", "id": "te-tx-054", "kind": "single_select", "language": "te", "options": ["మన అనుభవమే మన ప్రమాణం; శాంతి, నిర్భయత్వం, రక్షణ దొరికితే బాబాను పట్టుకో, లేకపోతే వదిలేయి", "వారిని ఒప్పించి సాయిభక్తులుగా మార్చాలి", "వారితో వాదించి గెలవాలి", "బాబా గురించి మాట్లాడటం మానేయాలి"], "question": "బాబా గురించి వాదించేవారితో ఎలా వ్యవహరించాలి?", "source_label": "Telugu short discourse: ఎవ్వరూ ఎవ్వరినీ సాయిభక్తులుగా మార్చలేరు", "source_link": "https://www.youtube.com/watch?v=L-MJIDD-hVU&t=32s"}, {"answer": "బాబా మనల్ని చూసేలా కూర్చోవాలి — మనం బాబాను చూసేలా కాదు; ఆయన దృష్టి మన మీద పడటమే ముఖ్యం. 'నేను ఆయన సన్నిధిలో ఉన్నాను' అనే భావంతో కూర్చోవాలి.", "explanation": "భక్తుల సందేహాలకు శ్రీ బాబుజీ సమాధానాలు (పార్ట్ 1).", "id": "te-tx-055", "kind": "flashcard", "language": "te", "question": "సమాధి మందిరంలో ఎలా కూర్చోవాలి?", "source_label": "Telugu Q&A: devotees' doubts, part 1", "source_link": "https://www.youtube.com/watch?v=0jG28xVnSvw&t=3s"}, {"answer": true, "explanation": "సత్సంగం అలవాటుగా మారినప్పుడు విసుగు భక్తుల మధ్య నాటకాలు, రాజకీయాలు పుట్టిస్తుంది.", "id": "te-tx-056", "kind": "true_false", "language": "te", "question": "పారాయణ, నామం యాంత్రికంగా అనిపిస్తే ఆ యాంత్రికత మన భావంలోనే ఉంది, అభ్యాసంలో కాదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu Q&A: devotees' doubts, part 1", "source_link": "https://www.youtube.com/watch?v=0jG28xVnSvw&t=0s"}, {"answer": true, "explanation": "షిర్డీకి బాబా కోసం వెళ్లాలి — సమస్యలు వచ్చినప్పుడు మాత్రమే కాదు.", "id": "te-tx-057", "kind": "true_false", "language": "te", "question": "ప్రతి సమస్యకూ షిర్డీకి పరుగెత్తడం బలహీనత అవుతుంది అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu Q&A: devotees' doubts, part 2", "source_link": "https://www.youtube.com/watch?v=sQdTHRbog6I&t=2s"}, {"answer": 0, "explanation": "అన్నిటికీ బాబా మీద విశ్వాసం లేకుండా ఆధారపడటం మనల్ని బలహీనులను చేస్తుంది.", "id": "te-tx-058", "kind": "single_select", "language": "te", "options": ["స్వప్రయత్నం చేయాలి; మనం చేయలేనిది మాత్రమే బాబాకు వదిలేయాలి", "వెంటనే షిర్డీకి వెళ్లాలి", "ఏమీ చేయకుండా బాబా మీద ఆధారపడాలి", "ఇతరులను అడగాలి"], "question": "సమస్య వచ్చినప్పుడు ముందు ఏమి చేయాలి?", "source_label": "Telugu Q&A: devotees' doubts, part 2", "source_link": "https://www.youtube.com/watch?v=sQdTHRbog6I&t=0s"}, {"answer": "సబూరీని ఆచరించడం ద్వారా; శ్రద్ధ లేకపోవడాన్నే బాబాకు సమర్పించడం ద్వారా.", "explanation": "అవి మనసుకు సంబంధించినవి కాబట్టి 'అప్పగించేశాను' అని ప్రకటించడం కాదు — ఆచరణే సమర్పణ.", "id": "te-tx-059", "kind": "flashcard", "language": "te", "question": "శ్రద్ధా సబూరీ అనే రెండు పైసలను బాబాకు ఎలా సమర్పించాలి?", "source_label": "Telugu Q&A: devotees' doubts, part 3", "source_link": "https://www.youtube.com/watch?v=X_GrQhbyGoQ&t=0s"}, {"answer": true, "explanation": "ఆరతి ఆయన కాలంలో జరిగింది కాబట్టి ఇప్పుడు చేస్తే షిర్డీలో ఉన్న భావన కలుగుతుంది.", "id": "te-tx-060", "kind": "true_false", "language": "te", "question": "దీపారాధన ఎందుకు చేయాలి? — బాబాకు ఇష్టం కాబట్టి; వేరే కారణం, వేరే శాస్త్రం లేదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu Q&A: devotees' doubts, part 3", "source_link": "https://www.youtube.com/watch?v=X_GrQhbyGoQ&t=60s"}, {"answer": [0, 1, 2], "explanation": "అత్యవసరమైతే వెళ్లవచ్చు — కానీ తిరిగి వచ్చి నియమంగా పూర్తి చేయాలి.", "id": "te-tx-061", "kind": "multi_select", "language": "te", "options": ["తప్పనిసరిగా ఉంటే వెళ్లి, తిరిగి వచ్చి నియమంగా పూర్తి చేయాలి", "ఆసక్తి లేకపోయినా నియమంగా పూర్తి చేయాలి", "అంతరాయాలకు అసలు కారణం లోపల ఆసక్తి లేకపోవడమే", "ఒక్కసారి ఆగితే ఇక పారాయణ చేయనక్కర్లేదు"], "question": "పారాయణ, సత్సంగాలకు అంతరాయం వస్తే శ్రీ బాబుజీ చెప్పిన సరైన విధానం ఏది?", "source_label": "Telugu Q&A: devotees' doubts, part 3", "source_link": "https://www.youtube.com/watch?v=X_GrQhbyGoQ&t=180s"}, {"answer": 0, "explanation": "కోట్ల కొద్దీ కూడబెట్టడానికి అర్థం లేదు.", "id": "te-tx-062", "kind": "single_select", "language": "te", "options": ["ఖర్చు చేయడం — సంతోషంగా ఖర్చుచేసి, ఆనందించి, భద్రతకు సరిపడా మాత్రమే ఉంచుకోవాలి", "బ్యాంకులో దాచుకోవడం", "కోట్ల కొద్దీ కూడబెట్టడం", "ఇతరులకు అప్పు ఇవ్వడం"], "question": "డబ్బు యొక్క పరమార్థం (ఉద్దేశం) ఏమిటి అని బాబా చెప్పారు?", "source_label": "Sri Babuji's 70th Birthday celebrations (evening session)", "source_link": "https://www.youtube.com/watch?v=yzpCFrhYt8g&t=1260s"}, {"answer": true, "explanation": "బాబా తన మందిరాన్ని తాను చూసుకోలేకపోతే ఇంకెవరు చూసుకుంటారు?", "id": "te-tx-063", "kind": "true_false", "language": "te", "question": "బాబా మందిరానికి బ్యాంకు బ్యాలెన్స్ అవసరం లేదు; మందిర నిధులను ఖర్చు చేయాలి — 'అది సిగ్గుచేటు' అని శ్రీ బాబుజీ అన్నారు.", "source_label": "Sri Babuji's 70th Birthday celebrations (evening session)", "source_link": "https://www.youtube.com/watch?v=yzpCFrhYt8g&t=1860s"}, {"answer": [0, 1], "explanation": "ద్వేషం, అసూయ పుట్టిన వెంటనే ఆనందాన్ని దొంగిలిస్తాయి.", "id": "te-tx-064", "kind": "multi_select", "language": "te", "options": ["ద్వేషం", "అసూయ", "సత్సంగం", "ప్రార్థనలో భావం"], "question": "మన ఆనందానికి అడ్డంకులు ఏవి అని శ్రీ బాబుజీ చెప్పారు?", "source_label": "The Festival of Grace 2024 (14th Aradhana of Sri Babuji)", "source_link": "https://www.youtube.com/watch?v=e3iB6cmnv4M&t=24s"}, {"answer": true, "explanation": "బాబా మీద ఆధారపడటం అంటే షిర్డీ యాత్రలను కూడా అతిగా ప్రణాళిక వేయకపోవడం.", "id": "te-tx-065", "kind": "true_false", "language": "te", "question": "ప్రణాళికలు రెండు రకాలు — కోటగోడలా అడ్డుకునేవి, కోటలా రక్షించేవి అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "The Festival of Grace 2024 (14th Aradhana of Sri Babuji)", "source_link": "https://www.youtube.com/watch?v=e3iB6cmnv4M&t=15s"}, {"answer": 0, "explanation": "లక్ష్యం ఆనంద జీవనం — బాబాను ఆనంద స్వరూపంగా ధ్యానించాలి.", "id": "te-tx-066", "kind": "single_select", "language": "te", "options": ["మనలోని ఆనందాన్ని పెంచే మందు లేదా విటమిన్లు", "కాలక్షేపం కోసం కార్యక్రమాలు", "సంఘాన్ని పెంచే సమావేశాలు", "ప్రచార వేదికలు"], "question": "సత్సంగాలు ఏమిటి అని శ్రీ బాబుజీ వర్ణించారు?", "source_label": "The Festival of Grace 2024 (14th Aradhana of Sri Babuji)", "source_link": "https://www.youtube.com/watch?v=e3iB6cmnv4M&t=25s"}, {"answer": true, "explanation": "టెన్షన్ లేకుండా పని చేయడాన్ని ఇతరులు 'గంభీరత లేకపోవడం' అంటారు — అది వారి అవగాహన లోపం.", "id": "te-tx-067", "kind": "true_false", "language": "te", "question": "టెన్షన్ ఎవరికీ ఉద్యోగం సంపాదించలేదు; పగ్గాలు బాబాకు అప్పగించి నిజంగా నిశ్చింతగా ఉండటమే ఆయన మార్గం అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "The Festival of Grace, 14th Aradhana Day 7 (evening)", "source_link": "https://www.youtube.com/watch?v=R6DlKIpbgW8&t=10s"}, {"answer": 0, "explanation": "'నా అనుభవమే నా రుజువు' — కానీ దాన్ని ఎవరికీ నిరూపించాల్సిన అవసరం లేదు.", "id": "te-tx-068", "kind": "single_select", "language": "te", "options": ["అడిగినప్పుడే మాట్లాడాలి; మార్చడానికి కాదు; ఎగతాళికి బాధపడవద్దు; నిరూపించడానికి ప్రయత్నించవద్దు", "అందరినీ ఒప్పించి భక్తులుగా మార్చాలి", "ఎగతాళి చేస్తే వాదించాలి", "బాబా గురించి ఎవరితోనూ మాట్లాడవద్దు"], "question": "బాబా గురించి బయటివారితో ఎప్పుడు, ఎలా మాట్లాడాలి?", "source_label": "The Festival of Grace, 14th Aradhana Day 7 (evening)", "source_link": "https://www.youtube.com/watch?v=R6DlKIpbgW8&t=23s"}, {"answer": "నా అనుభవం", "explanation": "అనుభవానికి రుజువు అడగడం అవైజ్ఞానికం; బాబా ముందు మేలు చేస్తారు, తర్వాత నమ్మకం, ప్రేమ వస్తాయి.", "id": "te-tx-069", "kind": "quote_completion", "language": "te", "question": "శ్రీ బాబుజీ మాటను పూర్తి చేయండి: \"మీకు వాస్తు, జ్యోతిష్యం, క్రియలు, శకునాలు ఉన్నాయి — నాకు ___ మాత్రమే ఉంది\".", "source_label": "The Festival of Grace, 14th Aradhana Day 7 (evening)", "source_link": "https://www.youtube.com/watch?v=R6DlKIpbgW8&t=27s"}, {"answer": "ఇక్కడే", "explanation": "ఇది రహస్యం కాదు — అందరికీ చెప్పారు.", "id": "te-tx-070", "kind": "quote_completion", "language": "te", "question": "మహల్సాపతి దగ్గర బాబా స్వయంగా చెప్పిన మాటను పూర్తి చేయండి: \"___ తపస్సు చేశాను\".", "source_label": "Telugu discourse on Mahalsapati's trances", "source_link": "https://www.youtube.com/watch?v=DcrXg30MmWY&t=44s"}, {"answer": true, "explanation": "బాబా గురుస్థానం తీసుకున్న తర్వాత ఆ పూనకాలు తగ్గాయి — ఆ పూర్వరూపం బాబా స్వంతమే.", "id": "te-tx-071", "kind": "true_false", "language": "te", "question": "దాస్ గణు 1903 చరిత్రలో మహల్సాపతి విషయాలను స్పష్టంగా రాశారు — సచ్చరిత్రకు 30 ఏళ్ల ముందు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse on Mahalsapati's trances", "source_link": "https://www.youtube.com/watch?v=DcrXg30MmWY&t=161s"}, {"answer": true, "explanation": "వ్యక్తిగత అనుబంధం బంధంలా కట్టేస్తుంది; వ్యక్తి లేని చోటే ఆధ్యాత్మిక ప్రేమ నిలుస్తుంది.", "id": "te-tx-072", "kind": "true_false", "language": "te", "question": "చూసే భక్తులకు బాబా బాధపడుతున్నట్లు అనిపించింది, కానీ లోపల ఎలాంటి బాధా లేదు — అది మాయ అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu Q&A: saguna or nirguna upasana", "source_link": "https://www.youtube.com/watch?v=1uovMPvQ8MU&t=0s"}, {"answer": "బాబానే దేవుడు", "explanation": "ఆయన ఇచ్చేదే నా స్వర్గం; అలాంటి ప్రేమతో ఫిర్యాదులు కరిగిపోతాయి, క్షణంలో పర్వతమంత ప్రార్థన జరుగుతుంది.", "id": "te-tx-073", "kind": "quote_completion", "language": "te", "question": "శ్రీ బాబుజీ మాటను పూర్తి చేయండి: \"బాబా దేవుడా కాదా అన్నది ముఖ్యం కాదు — ___\".", "source_label": "Telugu Q&A: saguna or nirguna upasana", "source_link": "https://www.youtube.com/watch?v=1uovMPvQ8MU&t=6s"}, {"answer": "ఒకే భావాన్ని మనసులో మళ్లీ మళ్లీ తిప్పడం — అహంకారం, రాగద్వేషాల మడతను బట్ట నుండి ఇస్త్రీ చేసినట్లు తొలగించడం.", "explanation": "పాత మడత పోయేవరకు ఇస్త్రీ చేసి, తర్వాత వ్యతిరేక దిశలో కొత్త మడత వేయాలి.", "id": "te-tx-076", "kind": "flashcard", "language": "te", "question": "భజన అంటే ఏమిటి?", "source_label": "Telugu extract on bhajana", "source_link": "https://www.youtube.com/watch?v=Hb7IgIl96XE&t=0s"}, {"answer": "మంచి భావం చిన్న దీపం లాంటిది; లోకం, దాని ఆకర్షణల గాలి దాన్ని ఆర్పేస్తుంది; సత్సంగం దాన్ని కాపాడే చిమ్నీ.", "explanation": "జ్వాల పెద్దదైనప్పుడు శత్రువైన గాలే మిత్రుడవుతుంది — సాధకుడు లోకం వైపు లాగబడకుండా లోకాన్నే తన వైపు లాగుతాడు.", "id": "te-tx-077", "kind": "flashcard", "language": "te", "question": "సత్సంగం 'చిమ్నీ' ఉపమానం ఏమిటి?", "source_label": "Telugu extract on bhajana", "source_link": "https://www.youtube.com/watch?v=Hb7IgIl96XE&t=60s"}, {"answer": true, "explanation": "మూడు రకాల సత్సంగాల్లో రెండు: సత్పురుషుల సాంగత్యం; మహాత్ముల చరిత్రలు, బోధనలు చదవడం.", "id": "te-tx-078", "kind": "true_false", "language": "te", "question": "జ్వాల పెద్దదైనప్పుడు ఒకప్పుడు శత్రువైన గాలే దానికి మిత్రుడవుతుంది అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu extract on bhajana", "source_link": "https://www.youtube.com/watch?v=Hb7IgIl96XE&t=60s"}, {"answer": true, "explanation": "ప్రేమించినవారు అందరికంటే అందంగా కనిపిస్తారు — నా ఊరు, నా ఇల్లు గొప్పది అన్నట్లే.", "id": "te-tx-079", "kind": "true_false", "language": "te", "question": "'సాయివంటి దైవంబు లేదోయి' అనే పాట కేవలం మన ప్రేమ వ్యక్తీకరణ; మతపరమైనది కాదు, ప్రచారం కాదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu explanation of 'Sayivanti daivambu ledoyi'", "source_link": "https://www.youtube.com/watch?v=6xQdR5vUMMw&t=0s"}, {"answer": "గురుత్వ నియమం ప్రకారం దీపం పడాలి; కానీ మధ్యలో పట్టుకునే చేయి సద్గురు చేయి — నియమానికి మినహాయింపు; ఆ మినహాయింపు ఆయనను ఆశ్రయించినవారికి వర్తిస్తుంది.", "explanation": "'జరగాల్సింది జరుగుతుంది' — ప్రారబ్ధం తన నియమంతో తప్పించుకోలేదు; అయినా తల్లి ప్రార్థనతో బిడ్డ నయమైంది.", "id": "te-tx-080", "kind": "flashcard", "language": "te", "question": "ప్రారబ్ధాన్ని సద్గురు ఎలా తొలగిస్తారో చెప్పే 'దీపం' ఉపమానం ఏమిటి?", "source_label": "Telugu discourse on how the Sadguru removes prarabdha", "source_link": "https://www.youtube.com/watch?v=EhJmxd2Xwu8&t=0s"}, {"answer": true, "explanation": "బుద్ధుని మహాపరినిర్వాణం ఉదాహరణ.", "id": "te-tx-081", "kind": "true_false", "language": "te", "question": "'చివరి జీవి ముక్తి పొందేవరకు నేను నిజంగా ముక్తుడిని కాను' — సద్గురు స్వేచ్ఛలో అందరి స్వేచ్ఛా ఉంది అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse on how the Sadguru removes prarabdha", "source_link": "https://www.youtube.com/watch?v=EhJmxd2Xwu8&t=120s"}, {"answer": 0, "explanation": "ఆయన భక్తుని కోరిక ప్రకారం వస్తారు, తన ఇష్టప్రకారం కాదు; మనం ఎంత ఆలస్యం చేసినా వేచి ఉంటారు.", "id": "te-tx-082", "kind": "single_select", "language": "te", "options": ["అవసరంతో కాదు, ప్రేమతో భక్తులకు బద్ధుడు — 'నేను నీ బానిసను'", "భక్తుల అవసరాలకు బానిస", "భక్తులను శాసించేవాడు", "భక్తుల నుండి దూరంగా ఉండేవాడు"], "question": "భగవాన్ 'భక్తపరాధీనుడు' అంటే ఏమిటి?", "source_label": "Telugu discourse on how the Sadguru removes prarabdha", "source_link": "https://www.youtube.com/watch?v=EhJmxd2Xwu8&t=180s"}, {"answer": "నిరంతరం ప్రశ్నలతో వేధించేవారిని నిశ్శబ్దం చేయడానికి వాడిన ఆయుధం అది; వారు నిశ్శబ్దమైన తర్వాత ఆయన బోధించేవారు.", "explanation": "ఆయన బోధను ఒక్క ప్రశ్న-సమాధానంతో అంచనా వేయవద్దు; ఆయన జీవితం నుండి ఆయన హృదయాన్ని అర్థం చేసుకోండి.", "id": "te-tx-083", "kind": "flashcard", "language": "te", "question": "రమణ మహర్షి 'నేనెవరు?' అనేది 'బ్రహ్మాస్త్రం' అని శ్రీ బాబుజీ ఎందుకు అన్నారు?", "source_label": "Telugu discourse on Ramana Maharshi's 'Know thyself'", "source_link": "https://www.youtube.com/watch?v=KKfuaLeeugs&t=120s"}, {"answer": true, "explanation": "ఆత్మ అంతటా ఉంటే మధురై వదిలి అరుణాచలం వెళ్లి ఆ కొండ పాదాలను ఎందుకు వదలలేదు?", "id": "te-tx-084", "kind": "true_false", "language": "te", "question": "రమణ మహర్షి బోధను ఒక్క ప్రశ్న-సమాధానంతో అంచనా వేయవద్దు; ఆయన జీవితం నుండి ఆయన హృదయాన్ని అర్థం చేసుకోవాలి అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse on Ramana Maharshi's 'Know thyself'", "source_link": "https://www.youtube.com/watch?v=KKfuaLeeugs&t=0s"}, {"answer": true, "explanation": "ఏ సంస్థా, ధర్మకర్తలూ వద్దు — ప్రతి భక్తుడే తన ధర్మకర్త.", "id": "te-tx-085", "kind": "true_false", "language": "te", "question": "సాయి మందిర నిర్మాణం కోసం డబ్బు వసూలు చేయవద్దు — ఒక్క రూపాయి కూడా ఎవరి చేతుల్లోకీ రాకూడదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu extract on construction of Sai mandirs", "source_link": "https://www.youtube.com/watch?v=wESk_-aSsh0&t=0s"}, {"answer": 0, "explanation": "బాబాయే అన్నీ ఏర్పాటు చేస్తారు — మనుషులను తీసుకొస్తారు, తెలియజేస్తారు.", "id": "te-tx-086", "kind": "single_select", "language": "te", "options": ["కూలీ కాంట్రాక్టర్‌కు నేరుగా చెల్లించాలి; ఎవరి చేతుల మీదుగానూ నగదు వెళ్లకూడదు", "ట్రస్టుకు విరాళం ఇవ్వాలి", "గురువుగారికి డబ్బు ఇవ్వాలి", "విరాళాలు అడగాలి"], "question": "మందిర నిర్మాణానికి సహాయం చేయాలనుకునేవారు ఏమి చేయాలి?", "source_label": "Telugu extract on construction of Sai mandirs", "source_link": "https://www.youtube.com/watch?v=wESk_-aSsh0&t=60s"}, {"answer": 0, "explanation": "మనసు రావద్దని వంద కారణాలు, సాకులు చెబుతుంది; వాటిని వినవద్దు.", "id": "te-tx-087", "kind": "single_select", "language": "te", "options": ["తరచూ రావాలి — అలవాటు ఏర్పడుతుంది, చపలత్వం తగ్గుతుంది; రాలేనప్పుడు బాబా స్మరణలో ఉండాలి", "ఒక్కసారి వస్తే చాలు", "ఇంట్లో కూర్చుని ఆలోచించాలి", "ఎక్కువ పుస్తకాలు చదవాలి"], "question": "సద్గురు సన్నిధిలో దొరికిన నిశ్చలతను కదలకుండా ఎలా ఉంచుకోవాలి?", "source_label": "Telugu discourse: keeping the stillness from the Sadguru's presence", "source_link": "https://www.youtube.com/watch?v=b5r-1o8lHKs&t=60s"}, {"answer": true, "explanation": "ఆయన సన్నిధిలో మనసు నిశ్చలంగా ఉంటుంది; బయటకు రాగానే పలచబడుతుంది.", "id": "te-tx-088", "kind": "true_false", "language": "te", "question": "సన్నిధికి రావద్దని మనసు వంద కారణాలు, సాకులు చెబుతుంది; వాటిని వినవద్దు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse: keeping the stillness from the Sadguru's presence", "source_link": "https://www.youtube.com/watch?v=b5r-1o8lHKs&t=120s"}, {"answer": 0, "explanation": "మనకు పరిమితులు ఉన్నంతవరకు గొప్పవాడు అవసరం.", "id": "te-tx-089", "kind": "single_select", "language": "te", "options": ["మనం చిన్నవారమని తెలిసినప్పుడు; గురువు అంటే గొప్పవాడు", "ఎప్పుడూ అవసరం లేదు", "డబ్బు కావాల్సినప్పుడు", "వృద్ధాప్యంలో మాత్రమే"], "question": "గురువు ఎప్పుడు అవసరం అని శ్రీ బాబుజీ చెప్పారు?", "source_label": "Telugu short discourse on గురువు ఆవశ్యకత", "source_link": "https://www.youtube.com/watch?v=1rYvOunQiX8&t=0s"}, {"answer": true, "explanation": "ఆ ఎరుక దుఃఖంతో కాక అనంతాన్ని చూసిన ఆనందంతో కలిగితే అదే గురుతత్త్వం.", "id": "te-tx-090", "kind": "true_false", "language": "te", "question": "హిమాలయాలు, సముద్రం వంటి విశాలాన్ని చూసినప్పుడు మన చిన్నదనం ఎరుకలోకి వస్తుంది అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu short discourse on గురువు ఆవశ్యకత", "source_link": "https://www.youtube.com/watch?v=1rYvOunQiX8&t=55s"}, {"answer": true, "explanation": "క్రమబద్ధతే స్థితిని నిర్మిస్తుంది.", "id": "te-tx-091", "kind": "true_false", "language": "te", "question": "మధ్యాహ్నం 12 గంటలకు ఆకలైనా కాకపోయినా భోజనం చేసినట్లు సత్సంగ క్రమం తప్పకూడదు; యాంత్రికంగా అనిపించినా క్రమం మొదలుపెట్టాలి అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "1 May 2025 satsang: how should satsang be done", "source_link": "https://www.youtube.com/watch?v=DLIZV1wOCjw&t=0s"}, {"answer": 0, "explanation": "సత్సంగం అహం పెంచడానికి, సంఘాన్ని పెంచడానికి, ప్రచారానికి కాదు.", "id": "te-tx-092", "kind": "single_select", "language": "te", "options": ["వీలైనంతవరకు మైక్ ముందు కూర్చోవద్దు", "ముందు వరుసలోనే కూర్చోవాలి", "ఎక్కువగా మాట్లాడాలి", "అందరికీ నాయకత్వం వహించాలి"], "question": "సత్సంగంలో ప్రాముఖ్యతను ఎలా నివారించాలి?", "source_label": "1 May 2025 satsang: how should satsang be done", "source_link": "https://www.youtube.com/watch?v=DLIZV1wOCjw&t=300s"}, {"answer": "బాబా మీద దృష్టి ఉంచితే గాయపడని స్థితి వస్తుంది; ఆయన ప్రేమ కవచంలా ఇతరుల గాయాల నుండి రక్షిస్తుంది.", "explanation": "గాయపడటం అంటే అహం దెబ్బతిన్నదని అర్థం.", "id": "te-tx-093", "kind": "flashcard", "language": "te", "question": "బాబా ప్రేమ 'కవచం' ఉపమానం ఏమిటి?", "source_label": "Telugu extract: getting rid of the ego called 'I'", "source_link": "https://www.youtube.com/watch?v=Pfqv7ZfWZHk&t=60s"}, {"answer": true, "explanation": "బాబా పట్ల ప్రేమతో అన్నీ చేస్తే అహం తనంతట తానే జారిపోతుంది.", "id": "te-tx-094", "kind": "true_false", "language": "te", "question": "అహం 'నేను'ను చంపే వేదాంత లక్ష్యాలతో కాదు, ప్రేమతో మాత్రమే తగ్గుతుంది అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu extract: getting rid of the ego called 'I'", "source_link": "https://www.youtube.com/watch?v=Pfqv7ZfWZHk&t=60s"}, {"answer": "కృపతో శిక్షణ శిక్షలా అనిపిస్తుంది; మన అహమే మన ఉనికి కాబట్టి దాన్ని పోగొట్టుకోవడం మరణంలా అనిపిస్తుంది.", "explanation": "అది శిక్ష కాదు, శిక్షణ — రమణ మహర్షి 'మరణ భయం' అన్నది ఇదే.", "id": "te-tx-095", "kind": "flashcard", "language": "te", "question": "నిత్య ప్రార్థనలోని 'నీ కృపతో నన్ను శిక్షించు' అనే వాక్యానికి శ్రీ బాబుజీ ఇచ్చిన అర్థం ఏమిటి?", "source_label": "Telugu extract: getting rid of the ego called 'I'", "source_link": "https://www.youtube.com/watch?v=Pfqv7ZfWZHk&t=180s"}, {"answer": true, "explanation": "ఇష్టదైవం గురించిన ప్రవచనం.", "id": "te-tx-096", "kind": "true_false", "language": "te", "question": "బాబా తరచూ భక్తులు ధ్యానించే దేవత రూపంలోనే దర్శనం ఇచ్చేవారు — రామభక్తుడికి రాముడిగా అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse on ఇష్టదైవం", "source_link": "https://www.youtube.com/watch?v=JmtQxCpVqwM&t=0s"}, {"answer": 0, "explanation": "మనసు ఎక్కువగా ప్రేమించే దాని వైపే సహజంగా ప్రవహిస్తుంది — అదే నీ నిజ ధ్యానం.", "id": "te-tx-097", "kind": "single_select", "language": "te", "options": ["మొదటి నుండి ఆయననే నీ రాముడిగా తీసుకుంటే రాముడితోనే కొనసాగు — తప్పు లేదు", "రాముడిని వదిలేసి బాబానే పూజించాలి", "ఇద్దరినీ వదిలేయాలి", "ఇతరులు చెప్పిన దేవుడిని పూజించాలి"], "question": "అలాంటి దర్శనం తర్వాత రాముడినా, బాబానా పూజించాలి?", "source_label": "Telugu discourse on ఇష్టదైవం", "source_link": "https://www.youtube.com/watch?v=JmtQxCpVqwM&t=89s"}, {"answer": true, "explanation": "బలవంతంగా దేన్నీ వదులుకోవద్దు.", "id": "te-tx-098", "kind": "true_false", "language": "te", "question": "బాబా దగ్గరకు వచ్చేటప్పుడు ఏదో పొందుతున్న భావన ఉండాలి, పోగొట్టుకుంటున్న భావన కాదు; ఏ దేవతనూ, నేపథ్యాన్నీ వదులుకోవాల్సిన అవసరం లేదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse on ఇష్టదైవం", "source_link": "https://www.youtube.com/watch?v=JmtQxCpVqwM&t=184s"}, {"answer": "జెండా ఎత్తుకుని", "explanation": "మంచి సినిమాకు పదిమంది స్నేహితులను తీసుకెళ్లినట్లే, బాబా చేసిన మేలు పదిమందికి చేరాలని కోరుకోవాలి.", "id": "te-tx-099", "kind": "quote_completion", "language": "te", "question": "దృఢ నమ్మకం గురించి శ్రీ బాబుజీ మాటను పూర్తి చేయండి: \"సాయి బాబా నా దేవుడు, నా గురువు — ___ చెప్పు\".", "source_label": "Telugu extract: how steady should our bhakti-prema be", "source_link": "https://www.youtube.com/watch?v=H21x-OAArrQ&t=120s"}, {"answer": true, "explanation": "కొందరు భక్తులు రుణానుబంధం వల్ల ఎక్కువ కృప పొందుతారు — అయినా దాన్ని అదృష్టం అంటారు.", "id": "te-tx-100", "kind": "true_false", "language": "te", "question": "కష్టాల్లో నవగ్రహ శాంతులు, వాస్తు పరిహారాలు అంటూ చాలామంది అనేక దేవుళ్ల చుట్టూ పరుగెత్తుతారు; చివరకు బాబానే అన్నివేళలా కాపాడుతున్నారని తెలుసుకుంటారు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu extract: how steady should our bhakti-prema be", "source_link": "https://www.youtube.com/watch?v=H21x-OAArrQ&t=0s"}, {"answer": "ఇతరుల్లో సులభంగా చూస్తాం, మనలో చూడం — 'ఇతరులు నన్ను గురించి ఏమనుకుంటారో' అనే భావాన్ని కాపాడుకుంటాం. తప్పులను ఒప్పుకోవడం అహంకారాన్ని కరిగిస్తుంది.", "explanation": "'తండ్రి తప్ప ఎవరూ పరిపూర్ణులు కారు.'", "id": "te-tx-101", "kind": "flashcard", "language": "te", "question": "అహంకారాన్ని ఎలా గుర్తించాలి?", "source_label": "Telugu discourse: Giving up ego is the Sai path", "source_link": "https://www.youtube.com/watch?v=_MtH_EL3cOM&t=120s"}, {"answer": true, "explanation": "అహంకారం హిమాలయాల్లా కరుగుతుంది.", "id": "te-tx-102", "kind": "true_false", "language": "te", "question": "బాబా ముందు చిన్న పిల్లల్లా మార్గదర్శకం లేకుండా, అమాయకంగా ఉండాలి; బాధను పిల్లవాడిలా వ్యక్తం చేస్తే బాబా తన బిడ్డగా హత్తుకుంటారు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse: Giving up ego is the Sai path", "source_link": "https://www.youtube.com/watch?v=_MtH_EL3cOM&t=300s"}, {"answer": 0, "explanation": "5% మంది ప్రేమతోనే బంధించుకున్నారు — వారిలో బయజాబాయి మొదటివారు.", "id": "te-tx-103", "kind": "single_select", "language": "te", "options": ["ఆయన అద్భుతాలు చూసి", "ప్రేమతోనే", "బంధువుల ఒత్తిడితో", "యాదృచ్ఛికంగా"], "question": "బాబా ప్రత్యక్ష భక్తుల్లో 95% మంది ఎలా వచ్చారు?", "source_label": "Telugu narration of Bayajabai's life", "source_link": "https://www.youtube.com/watch?v=tL7VgCl7sUI&t=0s"}, {"answer": "నా చెల్లెలివి", "explanation": "బయజాబాయి ప్రతిజ్ఞ: బాబాకు భిక్ష పెట్టకుండా తాను భోజనం చేయకూడదు.", "id": "te-tx-104", "kind": "quote_completion", "language": "te", "question": "మొదటి దర్శనంలో బాబా ఆసనం నుండి లేచి అన్న మాటను పూర్తి చేయండి: \"అమ్మా, నువ్వు నిజంగా ___\".", "source_label": "Telugu narration of Bayajabai's life", "source_link": "https://www.youtube.com/watch?v=tL7VgCl7sUI&t=3s"}, {"answer": true, "explanation": "కొన్నిసార్లు రోజుకు రెండు-మూడు సార్లు కూడా వెళ్లేవారు.", "id": "te-tx-105", "kind": "true_false", "language": "te", "question": "భిక్ష కోసం బాబా కేవలం ఐదు ఇళ్లకే వెళ్లేవారు; బయజాబాయి ఇంటి దగ్గర 'ఆబాదే, ఆబాద్ బాయిజమా, రోటీ లావ్' అని పిలిచేవారు అని ఈ కథనంలో ఉంది.", "source_label": "Telugu narration of Bayajabai's life", "source_link": "https://www.youtube.com/watch?v=tL7VgCl7sUI&t=5s"}, {"answer": "కడిగిన గ్లాసులో కాఫీ వాసన ఉండిపోయినట్లే, గత కర్మల ప్రభావం మనసు మీద మిగిలి ఉంటుంది — ఆ మిగిలినదే వాసన.", "explanation": "ఆలోచనలు వాసనలు/సంస్కారాల నుండి పుడతాయి.", "id": "te-tx-106", "kind": "flashcard", "language": "te", "question": "ధ్యానంలో ఆలోచనల గురించి శ్రీ బాబుజీ చెప్పిన 'కాఫీ గ్లాసు' ఉపమానం ఏమిటి?", "source_label": "Telugu discourse on thoughts in meditation", "source_link": "https://www.youtube.com/watch?v=kOYe3kvuwYg&t=169s"}, {"answer": 0, "explanation": "'విచ్ఛిన్నం' అనే పదాన్ని అర్థం తెలియకుండా వాడుతున్నారని శ్రీ బాబుజీ సమాధానం.", "id": "te-tx-107", "kind": "single_select", "language": "te", "options": ["కాదు — విచ్ఛిన్నానికి ప్రధాన మార్గం ఉండాలి; ధ్యానంలో కూర్చోవడంలో మన గమ్యమే ప్రధాన మార్గం", "అవును — ఏ ఆలోచనైనా విచ్ఛిన్నమే", "ఆలోచనలు రాకూడదు", "ధ్యానం మానేయాలి"], "question": "ధ్యానంలో ఆలోచనలు వస్తే వాటిని బాబా వైపు తిప్పడం కూడా విచ్ఛిన్నమేనా?", "source_label": "Telugu discourse on thoughts in meditation", "source_link": "https://www.youtube.com/watch?v=kOYe3kvuwYg&t=43s"}, {"answer": "మనసు నిశ్చల కొలను; ఆలోచనలు విసిరిన రాళ్లు — అలలు ఢీకొంటాయి. సద్గురు పెద్ద బండరాయి — చిన్న అలలన్నీ పెద్ద అలలో కలిసిపోతాయి; బాబా ద్వారా అన్ని కోరికలూ తీరుతాయి.", "explanation": "బాబా పద్ధతి: ముందు లౌకిక కోరికలు తీర్చి, తర్వాత భక్తుడిని తన వైపు నడిపిస్తారు.", "id": "te-tx-108", "kind": "flashcard", "language": "te", "question": "సద్గురు 'పెద్ద బండరాయి' ఉపమానం ఏమిటి?", "source_label": "Telugu discourse on thoughts in meditation", "source_link": "https://www.youtube.com/watch?v=kOYe3kvuwYg&t=356s"}, {"answer": 0, "explanation": "ప్రేమను నిజంగా గుర్తిస్తే అది అదే ప్రేమగా తిరిగి ప్రవహిస్తుంది — అందులో నేర్చుకోవాల్సిందేమీ లేదు.", "id": "te-tx-109", "kind": "single_select", "language": "te", "options": ["లక్షణాలతో — మనసు బాబానే మళ్లీ మళ్లీ తలుచుకుంటుందా? వైద్యుడు మలేరియాను లక్షణాలతో నిర్ధారించినట్లే", "పరీక్ష రాసి", "ఇతరులను అడిగి", "గుర్తించలేము"], "question": "బాబా పట్ల మనలోని ప్రేమను ఎలా గుర్తించాలి?", "source_label": "Telugu Q&A: recognizing love for Baba", "source_link": "https://www.youtube.com/watch?v=yyyC8AYeA_g&t=2s"}, {"answer": true, "explanation": "లక్షణాధారిత గుర్తింపు చాలు.", "id": "te-tx-110", "kind": "true_false", "language": "te", "question": "ప్రేమ నిజమైనదని రుజువు: ఆయనను ప్రేమిస్తే ఇతరులను కూడా ప్రేమిస్తాం అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu Q&A: recognizing love for Baba", "source_link": "https://www.youtube.com/watch?v=yyyC8AYeA_g&t=3s"}, {"answer": "రత్నాలు", "explanation": "అవి జ్ఞాన రత్నాలు; 'బాబా ఇలా ఎందుకు చేశారు?' అని ఊహించడం తప్పు.", "id": "te-tx-111", "kind": "quote_completion", "language": "te", "question": "బాబా మాటను పూర్తి చేయండి: \"నా లీల సముద్రంలో ఎవరైతే మునుగుతారో వాళ్ళకి ___ లభిస్తాయి\".", "source_label": "Telugu extract on 'నా చర్యలు అనూహ్యాలు'", "source_link": "https://www.youtube.com/watch?v=OSyKUWh_-Ic&t=0s"}, {"answer": true, "explanation": "ఆయన అన్నీ ప్రేమతోనే చేస్తారు — సమగ్రానికి ప్రతికూలమనేదే లేదు.", "id": "te-tx-112", "kind": "true_false", "language": "te", "question": "'నువ్వు వేరు, నేను వేరు అనుకోవడం అబద్ధం' — ఆయన దృష్టిలో మనమంతా ఆయన భాగాలమే కాబట్టి 'మనల్ని ప్రేమించడం' అనేది వేరుగా లేదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu extract on 'నా చర్యలు అనూహ్యాలు'", "source_link": "https://www.youtube.com/watch?v=OSyKUWh_-Ic&t=1s"}, {"answer": 0, "explanation": "నిజమైన పొదుపు శాంతి, ఆనందాలే — బ్యాంకు బ్యాలెన్స్ కాదు.", "id": "te-tx-113", "kind": "single_select", "language": "te", "options": ["మన శాంతి, ఆనందం, సమయం — డాలర్లు కాదు", "డబ్బు", "బంగారం", "విలువైన కానుకలు"], "question": "బాబాకు మనం ఇచ్చే నిజమైన దక్షిణ ఏమిటి?", "source_label": "Telugu discourse: the true dakshina we give Baba", "source_link": "https://www.youtube.com/watch?v=3NcfERPXah8&t=8s"}, {"answer": true, "explanation": "సాధన అంటే బాబా పట్ల మన ప్రేమ వ్యక్తీకరణ — 'నేను పాపిని' అనే అపరాధ భావం కాదు.", "id": "te-tx-114", "kind": "true_false", "language": "te", "question": "జీవితాన్ని ఆస్వాదించడం పాపం కాదు; ప్రతి అనుభవం ఏదో నేర్పుతుంది అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse: the true dakshina we give Baba", "source_link": "https://www.youtube.com/watch?v=3NcfERPXah8&t=4s"}, {"answer": "అనుబంధాలను వదులుకోవాల్సిన అవసరం లేదు — వాటన్నిటినీ బాబాకు అనుసంధానించు, పెట్టెలను ఇంజిన్‌కు కట్టినట్లు.", "explanation": "భక్తుల సందేహాలకు శ్రీ బాబుజీ సమాధానాలు (పార్ట్ 6).", "id": "te-tx-115", "kind": "flashcard", "language": "te", "question": "అనుబంధాల గురించి 'రైలు ఇంజిన్' ఉపమానం ఏమిటి?", "source_label": "Telugu Q&A: devotees' doubts, part 6", "source_link": "https://www.youtube.com/watch?v=ls8Kz4PB0DU&t=0s"}, {"answer": true, "explanation": "అలాగే బాబాయే మన సమస్యలకు పరిష్కార ఆలోచనను నాటుతారు.", "id": "te-tx-116", "kind": "true_false", "language": "te", "question": "బాబా ఫోటో నుండి ఉదీ రాలితే నమ్మవద్దు, నమ్మకపోవద్దు — పట్టించుకోవద్దు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu Q&A: devotees' doubts, part 6", "source_link": "https://www.youtube.com/watch?v=ls8Kz4PB0DU&t=2s"}, {"answer": 0, "explanation": "అహంకారం అంటే ఇతరుల కళ్లలో మనం ఊహించుకునే మన ప్రతిబింబం; అది దెబ్బతిన్నప్పుడు కోపం పుడుతుంది.", "id": "te-tx-117", "kind": "single_select", "language": "te", "options": ["మనం ఆశించినట్లు జరగకపోవడం + ఎదుటివారిని తప్పుగా అర్థం చేసుకోవడం — రెండూ కలిసి అజ్ఞానం", "ఆకలి + నిద్రలేమి", "డబ్బు + అధికారం", "వేడి + చలి"], "question": "కోపానికి శ్రీ బాబుజీ చెప్పిన రెండు కారణాలు ఏవి?", "source_label": "2025 Vijayadasami Day 2 morning satsang on anger", "source_link": "https://www.youtube.com/watch?v=t6Ajoy4S1mY&t=11s"}, {"answer": "దేవుడు తన పాత్రలను తన ఇష్టప్రకారం సృష్టిస్తాడు; మన అనుభవం ఆయన ఊహలోనే విప్పుతుంది.", "explanation": "ప్రభుపాద్ ఎదురు ప్రశ్న: 'మీకు కోపం ఎందుకు వస్తుంది?'", "id": "te-tx-118", "kind": "flashcard", "language": "te", "question": "కరుణామయుడైన దేవుడు బాధను, అసమానతను ఎందుకు సృష్టిస్తాడనే ప్రశ్నకు 'నవలా రచయిత' ఉపమానం ఏమి చెబుతుంది?", "source_label": "2025 Vijayadasami Day 2 morning satsang on anger", "source_link": "https://www.youtube.com/watch?v=t6Ajoy4S1mY&t=35s"}, {"answer": "బాబా", "explanation": "అరుణాచలంలో భక్తులు ఆయనను గురువు అని పిలిస్తే ఇచ్చిన సమాధానం.", "id": "te-tx-119", "kind": "quote_completion", "language": "te", "question": "గురువు ఎవరు అనే ప్రశ్నకు శ్రీ బాబుజీ సమాధానాన్ని పూర్తి చేయండి: \"నాకు శిష్యుడు లేడు — మార్గదర్శకత్వం నా ద్వారా వ్యక్తమవుతుంది; ___ మాత్రమే మన గురువు\".", "source_label": "2025 Vijayadasami Day 3 evening satsang (Q&A)", "source_link": "https://www.youtube.com/watch?v=pzjkv7MFkBE&t=10s"}, {"answer": "ఆకులో వడ్డించిన ఆహారం తిన్న తర్వాత ఆకుతో పాటు పారేస్తాం; మాధ్యమాన్ని మూలంతో తికమకపడవద్దు — ఆకులోనైనా బంగారు పళ్లెంలోనైనా ఆహారం ఒక్కటే.", "explanation": "గురువు ఎవరు అనే ప్రశ్నకు సమాధానంలో భాగం.", "id": "te-tx-120", "kind": "flashcard", "language": "te", "question": "'అరటి ఆకు (విస్తరి)' ఉపమానం ఏమిటి?", "source_label": "2025 Vijayadasami Day 3 evening satsang (Q&A)", "source_link": "https://www.youtube.com/watch?v=pzjkv7MFkBE&t=12s"}, {"answer": true, "explanation": "బాబాను గుర్తుంచుకోవడం చాలు — బాబా పట్ల ప్రేమను పెంచుకోండి.", "id": "te-tx-121", "kind": "true_false", "language": "te", "question": "మనసుకు వచ్చే ప్రతి ఆలోచన వెంట పరుగెత్తవద్దు; నామస్మరణ అనే రాయితో ఆలోచనలను కొట్టాలి, లక్ష్యం జపం మీదే ఉండాలి అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "2025 Vijayadasami Day 3 evening satsang (Q&A)", "source_link": "https://www.youtube.com/watch?v=pzjkv7MFkBE&t=14s"}, {"answer": "విగ్రహంతో మాట్లాడటం ఫోన్‌తో మాట్లాడటం లాంటిది; విగ్రహం కేవలం మాధ్యమం — బాబా 'నంబర్' తెలుసుకుని, పరిచయం చేసుకుని, సంభాషణ నేర్చుకోవాలి; అందుకే సత్సంగం.", "explanation": "కావాల్సిన రెండు లక్షణాలు: బాబా ఎవరో తెలుసుకోవడం, ఆయనతో మాట్లాడాలనే బలమైన తపన.", "id": "te-tx-122", "kind": "flashcard", "language": "te", "question": "బాబాతో మాట్లాడటం గురించి 'ఫోన్' ఉపమానం ఏమిటి?", "source_label": "Telugu discourse: does Baba talk back? (child's question)", "source_link": "https://www.youtube.com/watch?v=KF1ikjdCZ4o&t=79s"}, {"answer": true, "explanation": "ఆయన సమాధానం పరిస్థితుల ద్వారా వస్తుంది; సమాధానం కోరవద్దు, ఆశించండి.", "id": "te-tx-123", "kind": "true_false", "language": "te", "question": "బాబా మాట్లాడి నీకు వినిపించకపోతే నువ్వు సరిగ్గా మాట్లాడటం లేదని అర్థం; బాబా మాట మన మాటల్లా ఉండదు అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu discourse: does Baba talk back? (child's question)", "source_link": "https://www.youtube.com/watch?v=KF1ikjdCZ4o&t=34s"}, {"answer": [0, 2, 3], "explanation": "ఇతరుల గురించి చెడుగా మాట్లాడటం బాబాకు అత్యంత అయిష్టమైనది.", "id": "te-tx-124", "kind": "multi_select", "language": "te", "options": ["విమర్శ, ప్రతికూలతలను తొలగించడం సత్సంగాల్లో మొదటి ప్రాధాన్యత", "ఇతరుల చిన్న తప్పులను పెంచి సంబంధాలు పాడుచేయడం", "లోపలి ప్రేమను వ్యక్తం చేయడం — వ్యక్తీకరణ దాన్ని పెంచుతుంది", "ఎవరి గురించీ చెడుగా మాట్లాడకపోవడం"], "question": "మాటల క్రమశిక్షణ గురించి శ్రీ బాబుజీ చెప్పిన సరైన అంశాలు ఏవి?", "source_label": "Telugu short discourse on the discipline of speech", "source_link": "https://www.youtube.com/watch?v=8EEcl1BHCqI&t=240s"}, {"answer": true, "explanation": "మహర్షి మరణించిన రౌడీలో ఒక్క మంచి గుణాన్ని చూశారు — అతను శుభ్రంగా ఉండేవాడు.", "id": "te-tx-125", "kind": "true_false", "language": "te", "question": "ఇతరుల గురించి చెడుగా మాట్లాడటం బాబాకు అత్యంత అయిష్టమైనది; అది మానసిక మాలిన్యం — బురదలో దొర్లే పంది లాంటిది అని శ్రీ బాబుజీ చెప్పారు.", "source_label": "Telugu short discourse on the discipline of speech", "source_link": "https://www.youtube.com/watch?v=8EEcl1BHCqI&t=120s"}];
